window.EXAM={"data":"PL300","code":"PL-300","store":"dataarcus-pl300-v1","ev":"pl300","outline":"../assets/data/pl300-outline.json","page":"https://dataarcus.com/tools/pl-300-practice-exam.html","dom":{"prep":{"en":"Prepare the data","ar":"تجهيز البيانات","w":"25–30%","wt":27.5},"model":{"en":"Model the data","ar":"نمذجة البيانات","w":"25–30%","wt":27.5},"viz":{"en":"Visualize and analyze the data","ar":"التصور والتحليل","w":"25–30%","wt":27.5},"manage":{"en":"Manage and secure Power BI","ar":"إدارة Power BI وتأمينه","w":"15–20%","wt":17.5}},"skill":{"get":{"d":"prep","en":"Get or connect to data","ar":"الحصول على البيانات والاتصال بها"},"clean":{"d":"prep","en":"Profile and clean the data","ar":"فحص البيانات وتنظيفها"},"transform":{"d":"prep","en":"Transform and load the data","ar":"تحويل البيانات وتحميلها"},"design":{"d":"model","en":"Design and implement a data model","ar":"تصميم نموذج البيانات"},"dax":{"d":"model","en":"Create model calculations with DAX","ar":"حسابات النموذج بـ DAX"},"perf":{"d":"model","en":"Optimize model performance","ar":"تحسين أداء النموذج"},"reports":{"d":"viz","en":"Create reports","ar":"إنشاء التقارير"},"usability":{"d":"viz","en":"Usability and storytelling","ar":"سهولة الاستخدام وسرد القصة"},"patterns":{"d":"viz","en":"Identify patterns and trends","ar":"اكتشاف الأنماط والاتجاهات"},"workspace":{"d":"manage","en":"Workspaces and assets","ar":"مساحات العمل والمحتوى"},"security":{"d":"manage","en":"Secure and govern Power BI items","ar":"تأمين وحوكمة عناصر Power BI"}},"outlineNames":{"prep":"prepare the data","model":"model the data","viz":"visualize and analyze the data","manage":"manage and secure power bi"},"mix":null,"mixText":["Questions are drawn by exam weight: about a quarter each on preparing, modeling and visualizing data, and the rest on managing and securing Power BI.","الأسئلة موزعة حسب أوزان الاختبار: نحو الربع لكل من تجهيز البيانات ونمذجتها والتصور والتحليل، والباقي لإدارة Power BI وتأمينه."],"official":[["https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/pl-300","PL-300 study guide: the skills measured","دليل مذاكرة PL-300: المهارات المقاسة"],["https://learn.microsoft.com/en-us/credentials/certifications/exams/pl-300/practice/assessment?assessment-type=practice&assessmentId=48","Microsoft's free practice assessment","التقييم التدريبي المجاني من Microsoft"],["https://learn.microsoft.com/en-us/credentials/certifications/power-bi-data-analyst-associate/","Power BI Data Analyst Associate certification page","صفحة شهادة Power BI Data Analyst Associate"],["https://learn.microsoft.com/en-us/credentials/certifications/renew-your-microsoft-certification","Renew your certification (free online assessment)","تجديد الشهادة (تقييم مجاني عبر الإنترنت)"],["https://aka.ms/examdemo","Exam sandbox: try the real exam interface","بيئة تجربة واجهة الاختبار الحقيقية"]]};
window.PL300={"v":"2026-04-20","q":[{"id":"PL-GET-001","d":"prep","s":"get","type":"single","diff":1,"tag":"Gateways","q":"Your Power BI Desktop report imports data from a SQL Server database hosted in your company's datacenter. After you publish the report, the semantic model must refresh every morning in the Power BI service. Several colleagues also publish models that use the same server. What should you configure?","opts":["An on-premises data gateway in standard mode","An on-premises data gateway in personal mode","A virtual network (VNet) data gateway","No gateway, because the Power BI service can reach any SQL Server directly"],"ans":0,"exp":"The Power BI service runs in the cloud and needs a gateway to reach data sources inside a private network. A standard on-premises data gateway is installed once on a machine that can reach the server and can be shared by many users and semantic models.","why":["","Personal mode serves only the person who installed it and can't be shared, so colleagues couldn't use it.","A VNet data gateway reaches sources inside an Azure virtual network, not a server in your own datacenter.","The service can't reach servers inside a private network without a gateway."],"ar":"مصادر داخل شبكة الشركة تحتاج on-premises data gateway، واختر standard mode لو أكثر من شخص سيستخدمها.","ref":[{"t":"What is an on-premises data gateway?","u":"https://learn.microsoft.com/en-us/power-bi/connect-data/service-gateway-onprem"}]},{"id":"PL-GET-002","d":"prep","s":"get","type":"single","diff":1,"tag":"Gateways","q":"A semantic model imports two sources: an Excel file stored in SharePoint Online and a table in Azure SQL Database that allows access from Azure services. You configure scheduled refresh in the Power BI service. Do you need an on-premises data gateway?","opts":["No. Both are cloud sources the service can reach directly","Yes, for the Excel file only","Yes, for the Azure SQL Database table only","Yes, for both sources"],"ans":0,"exp":"Cloud sources such as SharePoint Online and Azure SQL Database (with public network access allowed) are reached directly by the Power BI service by using cloud connections. A gateway is required for sources inside a private network, such as an on-premises server or a local file share.","why":["","SharePoint Online is a cloud service. No gateway is needed.","Azure SQL Database is reachable from the service when it allows public or Azure service access.","Neither source sits behind a private network."],"ar":"المصادر السحابية مثل SharePoint Online وAzure SQL لا تحتاج gateway، الـ gateway فقط للمصادر داخل شبكة خاصة.","ref":[{"t":"What is an on-premises data gateway?","u":"https://learn.microsoft.com/en-us/power-bi/connect-data/service-gateway-onprem"},{"t":"Data refresh in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/connect-data/refresh-data"}]},{"id":"PL-GET-003","d":"prep","s":"get","type":"single","diff":2,"tag":"Storage mode","q":"You connect to a sales table with 2 billion rows in a SQL Server data warehouse. Managers need to see transactions within minutes of them being written, and the table is too large to import. There is no Microsoft Fabric capacity. Which storage mode should you use for the table?","opts":["DirectQuery","Import","Direct Lake","Dual"],"ans":0,"exp":"DirectQuery leaves the data in the source and sends queries to it each time a visual loads, so results are as fresh as the source and model size isn't limited by memory. It fits very large tables and near real-time needs when the source can handle the query load.","why":["","Import copies the data into the model. It would be stale between refreshes and the table is too large to import.","Direct Lake needs Delta tables in OneLake and a Fabric capacity. The data lives in SQL Server and there's no Fabric capacity.","Dual acts as Import or DirectQuery depending on the query, but it still stores an imported copy, which isn't possible here."],"ar":"لو البيانات ضخمة جدًا وتحتاج أحدث قيمة من المصدر بدون Fabric، استخدم DirectQuery.","ref":[{"t":"Use DirectQuery in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/connect-data/desktop-directquery-about"},{"t":"Table storage mode in Power BI semantic models","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-storage-mode"}]},{"id":"PL-GET-004","d":"prep","s":"get","type":"single","diff":2,"tag":"Storage mode","q":"Your organization lands curated sales data as Delta tables in a Microsoft Fabric lakehouse. The workspace is on an F64 capacity. You need a semantic model that performs like Import mode but doesn't require copying the data into the model during refresh. Which storage mode should you choose?","opts":["Direct Lake","Import","DirectQuery","Dual"],"ans":0,"exp":"Direct Lake reads Delta tables in OneLake straight into memory. Queries are answered by the same VertiPaq engine as Import, but a refresh (framing) only updates metadata, so there's no full data copy.","why":["","Import performs well but copies all the data at each refresh, which the requirement rules out.","DirectQuery sends queries to the source every time and is usually slower than Direct Lake or Import.","Dual still keeps an imported copy of the data."],"ar":"بيانات Delta في OneLake مع Fabric capacity؟ استخدم Direct Lake: أداء قريب من Import بدون نسخ البيانات.","ref":[{"t":"Direct Lake overview","u":"https://learn.microsoft.com/en-us/fabric/fundamentals/direct-lake-overview"},{"t":"Table storage mode in Power BI semantic models","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-storage-mode"}]},{"id":"PL-GET-005","d":"prep","s":"get","type":"yesno","diff":3,"tag":"Storage mode","q":"You're comparing storage modes for a new semantic model.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["Direct Lake semantic models require a Microsoft Fabric capacity.","A Direct Lake on SQL analytics endpoint table that's based on a SQL view falls back to DirectQuery.","Import mode tables always show data changes in the source as soon as they happen."],"ans":[true,true,false],"exp":"Direct Lake is only available on Fabric capacity SKUs. Direct Lake on SQL analytics endpoints falls back to DirectQuery when it can't read a Delta table directly, for example when the table is a SQL view. Import shows the data as of the last refresh.","why":["Yes. Direct Lake licensing is Fabric capacity only.","Yes. Views aren't Delta tables, so Direct Lake on SQL falls back to DirectQuery.","No. Import data is a snapshot that updates only when the model refreshes."],"ar":"Direct Lake يحتاج Fabric capacity، والـ views في Direct Lake on SQL تتحول إلى DirectQuery، وImport يعرض البيانات حتى آخر refresh فقط.","ref":[{"t":"Direct Lake overview","u":"https://learn.microsoft.com/en-us/fabric/fundamentals/direct-lake-overview"}]},{"id":"PL-GET-006","d":"prep","s":"get","type":"single","diff":1,"tag":"Shared semantic model","q":"A certified semantic model named Sales Model is published in a workspace. You need to build a new report on it in Power BI Desktop without creating another copy of the data, so that every report uses the same measures. What should you do?","opts":["Get data from Power BI semantic models and select Sales Model (live connection)","Download the .pbix file of Sales Model and build the report inside it","Import the Sales Model tables into a new model by using the SQL Server connector","Export Sales Model to Excel and import the workbook"],"ans":0,"exp":"Connecting to a published semantic model creates a live connection. The report reuses the model's tables, relationships and measures, and no data is copied, so there's one source of truth.","why":["","Downloading the .pbix creates a second copy of the model to maintain.","Re-importing the source creates a duplicate model and duplicate logic.","Exporting to Excel loses the model and creates a static copy."],"ar":"استخدم الـ semantic model المنشور عبر live connection بدل نسخ البيانات، حتى تبقى المقاييس موحدة.","ref":[{"t":"Connect to semantic models in the Power BI service from Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/connect-data/desktop-report-lifecycle-datasets"},{"t":"Intro to semantic models across workspaces","u":"https://learn.microsoft.com/en-us/power-bi/connect-data/service-datasets-across-workspaces"}]},{"id":"PL-GET-007","d":"prep","s":"get","type":"single","diff":2,"tag":"Composite model","q":"You have a live connection report on a shared semantic model. You need to add a small Excel table of sales targets that exists only in your team and relate it to the model's Date table. What should you do?","opts":["Change the connection to a DirectQuery connection to the semantic model, then import the Excel table","Add the Excel table through Get data; live connections accept new imported tables automatically","Ask the model owner to remove the Date table","Create a calculated table that reads the Excel file"],"ans":0,"exp":"A live connection can't add other sources. When you choose Make changes to this model, the connection becomes DirectQuery to the semantic model, creating a composite model where you can add imported tables and relationships.","why":["","In a pure live connection, Get data for other sources isn't available until you switch to a composite model.","That breaks the shared model for everyone and doesn't solve the need.","DAX calculated tables can't read files."],"ar":"لإضافة بيانات إلى live connection حوّله إلى DirectQuery على الـ semantic model (composite model) ثم أضف الجدول.","ref":[{"t":"Use composite models in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-composite-models"}]},{"id":"PL-GET-008","d":"prep","s":"get","type":"single","diff":1,"tag":"Credentials","q":"You published a report whose semantic model imports from a web API that uses a key. Scheduled refresh fails with the message that the data source credentials are missing or invalid. Where do you fix this?","opts":["Semantic model settings in the Power BI service, under Data source credentials","File > Options > Data load in Power BI Desktop","The report's Format pane","Workspace settings > License info"],"ans":0,"exp":"Credentials that Power BI Desktop uses aren't published with the model. In the service, open the semantic model settings and edit the Data source credentials (or the gateway or cloud connection) so scheduled refresh can authenticate.","why":["","Desktop options only affect your local file.","The Format pane controls visual appearance.","License info doesn't store data source credentials."],"ar":"بيانات الدخول لا تُنشر مع التقرير، حدّثها من Semantic model settings > Data source credentials.","ref":[{"t":"Configure scheduled refresh","u":"https://learn.microsoft.com/en-us/power-bi/connect-data/refresh-scheduled-refresh"}]},{"id":"PL-GET-009","d":"prep","s":"get","type":"single","diff":2,"tag":"Privacy levels","q":"A query merges customer data from an on-premises SQL Server with a public web page of exchange rates. You want to make sure no customer data is ever sent to the web source while Power Query combines them. How should you set the privacy levels?","opts":["SQL Server: Organizational, web page: Public","SQL Server: Public, web page: Public","SQL Server: None, web page: None","Turn on Always ignore Privacy Level settings"],"ans":0,"exp":"Privacy levels tell the Power Query engine which data can be combined and folded between sources. Marking the database Organizational and the web page Public stops organizational data from being sent to a public source.","why":["","Marking the database Public allows its data to flow into any source.","None means privacy levels aren't configured, so the isolation you need isn't guaranteed.","Ignoring privacy levels can expose sensitive data to other sources."],"ar":"اضبط Privacy levels: البيانات الداخلية Organizational والمصادر العامة Public حتى لا تتسرب بيانات الشركة.","ref":[{"t":"Power BI Desktop privacy levels","u":"https://learn.microsoft.com/en-us/power-bi/enterprise/desktop-privacy-levels"},{"t":"Privacy levels (Power Query)","u":"https://learn.microsoft.com/en-us/power-query/privacy-levels"}]},{"id":"PL-GET-010","d":"prep","s":"get","type":"single","diff":2,"tag":"Parameters","q":"You need to move a Power BI Desktop file from a test SQL Server to the production server without editing every query. What should you create?","opts":["A Power Query parameter for the server name, used in the source step of each query","A what-if parameter","A field parameter","A calculated column that stores the server name"],"ans":0,"exp":"Power Query parameters store values such as a server or database name. Each query's source step references the parameter, so you change one value (in Desktop or in the service semantic model settings) to switch environments.","why":["","What-if parameters create a DAX table and measure for scenario analysis. They can't change a data source.","Field parameters let readers switch fields in visuals.","A calculated column is evaluated after load and can't control the connection."],"ar":"لتغيير السيرفر بسهولة استخدم Power Query parameter داخل خطوة Source.","ref":[{"t":"Parameters (Power Query)","u":"https://learn.microsoft.com/en-us/power-query/power-query-query-parameters"}]},{"id":"PL-GET-011","d":"prep","s":"get","type":"order","diff":2,"tag":"Parameters","q":"You want report consumers' semantic model to switch from the test database to production after you publish, without republishing the file. Which three actions should you perform in sequence?","opts":["In Power Query, create a text parameter named ServerName","Replace the hard-coded server in each query's Source step with ServerName","After publishing, change ServerName in the semantic model settings in the service, then refresh","Create a what-if parameter named ServerName","Add ServerName to a slicer on the report"],"ans":[0,1,2],"exp":"Create the parameter, reference it from each Source step, then after publishing edit the parameter value under the semantic model's Parameters settings and refresh.","why":["Step 1.","Step 2.","Step 3.","What-if parameters are DAX objects for scenarios and can't drive connections.","Power Query parameters aren't exposed as slicers and a slicer can't change the source."],"ar":"الخطوات: إنشاء parameter، استخدامه في Source، ثم تعديله من إعدادات الـ semantic model في الخدمة.","ref":[{"t":"Parameters (Power Query)","u":"https://learn.microsoft.com/en-us/power-query/power-query-query-parameters"}]},{"id":"PL-GET-012","d":"prep","s":"get","type":"multi","n":2,"diff":2,"tag":"Get data","q":"You need to create a single query that combines the monthly CSV exports stored in one SharePoint Online folder. All files have the same columns. Which two actions should you take? Each correct answer presents part of the solution. Select TWO.","opts":["Use the SharePoint folder connector and point it at the site URL","Filter the file list to the target folder, then select Combine files","Use the Web connector once for each CSV file","Use the Folder connector with the SharePoint site URL","Import each file separately and use Merge queries"],"ans":[0,1],"exp":"The SharePoint folder connector lists every file in the site. Filter to the right folder and file type, then use Combine files, which builds a sample-file function and appends all files into one table.","why":["Correct.","Correct.","One query per file doesn't scale and must be edited every month.","The Folder connector is for local or network folders, not SharePoint URLs.","Merge joins tables side by side. Files with the same columns need Append, which Combine files does."],"ar":"لدمج ملفات متشابهة من SharePoint استخدم SharePoint folder ثم Combine files.","ref":[{"t":"Append queries","u":"https://learn.microsoft.com/en-us/power-query/append-queries"}]},{"id":"PL-GET-013","d":"prep","s":"get","type":"single","diff":1,"tag":"Get data","q":"A data source contains 20 columns, but your report needs only 6 of them. What is the best place to remove the other 14?","opts":["In Power Query, as early as possible in the query","In the Data view, by hiding the columns","In the report, by not using them in visuals","In DAX, by creating a calculated table with SELECTCOLUMNS"],"ans":0,"exp":"Removing columns in Power Query means they're never loaded, which reduces model size and refresh time. Doing it early also helps query folding push the column selection to the source.","why":["","Hidden columns are still loaded and still take memory.","Unused columns are still loaded.","A calculated table adds a copy and doesn't remove the original columns."],"ar":"احذف الأعمدة غير المطلوبة في Power Query مبكرًا حتى لا تُحمّل أصلًا.","ref":[{"t":"Data reduction techniques for Import modeling","u":"https://learn.microsoft.com/en-us/power-bi/guidance/import-modeling-data-reduction"},{"t":"Query folding guidance in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/guidance/power-query-folding"}]},{"id":"PL-GET-014","d":"prep","s":"get","type":"single","diff":2,"tag":"Query folding","q":"A query against SQL Server has these steps: Source, Filtered rows (year = 2026), Removed columns, Added index column, Changed type. You need to know which steps are translated into SQL and run at the source. What should you do?","opts":["Look at the query folding indicators next to each step in the Applied steps pane","Open Performance Analyzer","Check the column quality bar","Look at the relationship view"],"ans":0,"exp":"Power Query shows query folding indicators beside each applied step. They reveal where folding stops, for example at an Index column step, so you can reorder steps and keep more work at the source.","why":["","Performance Analyzer measures report visuals, not Power Query folding.","Column quality shows valid, error and empty percentages.","Model view shows relationships, not folding."],"ar":"مؤشرات query folding بجانب كل خطوة تبين أين يتوقف تنفيذ الخطوات في المصدر.","ref":[{"t":"Query folding guidance in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/guidance/power-query-folding"}]},{"id":"PL-GET-015","d":"prep","s":"get","type":"yesno","diff":2,"tag":"Query folding","q":"A Power Query query connects to Azure SQL Database.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["A Filtered rows step on a column can usually fold back to the source.","Adding an Index column typically stops query folding for the steps after it.","Query folding matters only for DirectQuery and has no effect on Import refresh time."],"ans":[true,true,false],"exp":"Filters and column selection fold well to relational sources. An Index column has no SQL equivalent in most cases, so folding often stops there. Folding also speeds up Import refresh, because less data is transferred and processed.","why":["Yes. Filters translate to a WHERE clause.","Yes. Index columns commonly break folding, so add them as late as possible.","No. Folding reduces the data transferred during Import refresh too, and incremental refresh relies on it."],"ar":"الفلترة تُطوى للمصدر عادة، وIndex column يوقف الطي، والطي مهم أيضًا لسرعة refresh في Import.","ref":[{"t":"Query folding guidance in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/guidance/power-query-folding"}]},{"id":"PL-GET-016","d":"prep","s":"get","type":"single","diff":3,"tag":"Storage mode","q":"A model uses a DirectQuery fact table and an imported Product dimension. Slicers on Product are slow because every filter must be combined with the DirectQuery table. You want Product queries to be answered from memory when possible and still join efficiently with the fact table at the source. Which storage mode should you set for Product?","opts":["Dual","Import","DirectQuery","Direct Lake"],"ans":0,"exp":"Dual tables can act as Import or DirectQuery depending on the query. Queries that touch only Product use the in-memory copy, and queries joined with the DirectQuery fact table can be sent to the source together, avoiding limited relationships.","why":["","Import on the dimension creates a limited relationship to the DirectQuery fact table, which forces extra work.","DirectQuery on the dimension makes slicer queries always go to the source.","Direct Lake needs Delta tables in OneLake and a Fabric capacity."],"ar":"الجداول البعدية المرتبطة بجدول DirectQuery تُضبط غالبًا على Dual.","ref":[{"t":"Table storage mode in Power BI semantic models","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-storage-mode"},{"t":"Use composite models in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-composite-models"}]},{"id":"PL-GET-017","d":"prep","s":"get","type":"single","diff":1,"tag":"Get data","q":"You receive a JSON file that contains nested records for orders and their line items. What is the first step to turn it into a table in Power Query?","opts":["Connect with the JSON connector, convert the list to a table, then expand the record columns","Use the Text/CSV connector and split by comma","Open it in the Web connector and use Pivot column","Use DAX PATH functions"],"ans":0,"exp":"The JSON connector returns lists and records. Converting the top-level list to a table and then expanding the record and list columns flattens the structure into rows and columns.","why":["","Splitting JSON text by comma breaks nested structures.","Pivot doesn't flatten nested records.","PATH functions work with parent-child hierarchies, not JSON."],"ar":"ملف JSON: استخدم JSON connector ثم To table ثم Expand للأعمدة المتداخلة.","ref":[{"t":"JSON (Power Query connector)","u":"https://learn.microsoft.com/en-us/power-query/connectors/json"}]},{"id":"PL-GET-018","d":"prep","s":"get","type":"single","diff":2,"tag":"Get data","q":"You need Power BI Desktop to refresh a local folder of files only on your computer while you test, and you don't have admin rights to install services. Later the model will be published for a team. Which statement is correct?","opts":["Personal mode gateway can serve your own refreshes, but the team model will need a standard gateway","A personal mode gateway can be shared with the team later","Local folders never need a gateway after publishing","A VNet gateway is required for local folders"],"ans":0,"exp":"Personal mode runs under your account and serves only you. For shared, managed refresh of a team model, a standard on-premises data gateway is needed, installed on a machine that can reach the folder.","why":["","Personal mode can't be shared with other users.","A local or network folder is behind your network, so the service needs a gateway.","VNet gateways are for Azure virtual network sources."],"ar":"Personal gateway لك وحدك، أما التقارير المشتركة فتحتاج standard gateway.","ref":[{"t":"Use a personal gateway in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/connect-data/service-gateway-personal-mode"},{"t":"What is an on-premises data gateway?","u":"https://learn.microsoft.com/en-us/power-bi/connect-data/service-gateway-onprem"}]},{"id":"PL-CLN-001","d":"prep","s":"clean","type":"single","diff":1,"tag":"Profiling","q":"In Power Query, the column quality bar shows that a CustomerID column is 100% valid. Later you find nulls in that column after load. What is the most likely reason?","opts":["Column profiling is based on the top 1,000 rows by default","Column quality ignores null values","Nulls are created by the relationship with the Customer table","The model changed the data type after load"],"ans":0,"exp":"By default, the profiling tools in Power Query evaluate only the first 1,000 rows. Switch the status bar option to Column profiling based on entire data set to see the full picture.","why":["","Empty values are shown as Empty in column quality.","Relationships don't write nulls into columns.","Changing types doesn't turn valid IDs into nulls."],"ar":"أدوات الـ profiling تفحص أول 1000 صف افتراضيًا، غيّرها إلى entire data set.","ref":[{"t":"Using the data profiling tools","u":"https://learn.microsoft.com/en-us/power-query/data-profiling-tools"}]},{"id":"PL-CLN-002","d":"prep","s":"clean","type":"single","diff":1,"tag":"Profiling","q":"You need to see how many distinct and unique values a ProductCode column has, to confirm it can be used as a key. Which Power Query view gives you this directly?","opts":["Column distribution","Column quality","Query dependencies","Advanced editor"],"ans":0,"exp":"Column distribution shows the count of distinct values (different values) and unique values (values that appear exactly once) for each column. A good key has distinct and unique counts equal to the row count.","why":["","Column quality shows valid, error and empty percentages, not distinct counts.","Query dependencies shows how queries reference each other.","The advanced editor shows M code."],"ar":"Column distribution يعرض عدد القيم distinct وunique لمعرفة صلاحية المفتاح.","ref":[{"t":"Using the data profiling tools","u":"https://learn.microsoft.com/en-us/power-query/data-profiling-tools"}]},{"id":"PL-CLN-003","d":"prep","s":"clean","type":"single","diff":1,"tag":"Errors","q":"A Sales Amount column has a few errors after changing its type to Decimal Number because some rows contain the text \"N/A\". Business users want those rows kept with an empty amount. What should you do?","opts":["Use Replace errors on the column and replace with null","Use Remove errors on the column","Change the type back to Text","Filter the column to remove blanks"],"ans":0,"exp":"Replace errors swaps error values for a value you choose, such as null, and keeps the rows. Remove errors would delete the rows, which the users don't want.","why":["","Remove errors deletes the whole rows.","Text amounts can't be summed.","The errors aren't blanks, and filtering would remove rows."],"ar":"لإبقاء الصفوف مع قيمة فارغة استخدم Replace errors بـ null وليس Remove errors.","ref":[{"t":"Dealing with errors in Power Query","u":"https://learn.microsoft.com/en-us/power-query/dealing-with-errors"}]},{"id":"PL-CLN-004","d":"prep","s":"clean","type":"single","diff":2,"tag":"Errors","q":"After a refresh, Power BI Desktop shows \"Load completed with errors\" and a link to View errors for a Date column. The source now sends dates in two formats. What is the best long-term fix?","opts":["Change the column type by using Using locale (or parse the text) so both formats convert, and handle any remaining errors","Ignore the message, because errors don't affect the model","Delete the Date column","Set the column type to Any"],"ans":0,"exp":"Import errors mean some values couldn't be converted. Converting with the correct locale or parsing the text into proper dates fixes the root cause, then Replace errors or a conditional column handles true exceptions.","why":["","Rows with errors load as blanks and silently skew results.","The column is needed for time analysis.","Type Any prevents date functions and time intelligence."],"ar":"عالج أخطاء التاريخ بتحويل صحيح باستخدام Using locale ثم تعامل مع الاستثناءات.","ref":[{"t":"Dealing with errors in Power Query","u":"https://learn.microsoft.com/en-us/power-query/dealing-with-errors"},{"t":"Data types in Power Query","u":"https://learn.microsoft.com/en-us/power-query/data-types"}]},{"id":"PL-CLN-005","d":"prep","s":"clean","type":"single","diff":1,"tag":"Clean text","q":"A City column contains values such as \"dubai\", \" Dubai\" and \"DUBAI \". Visuals show three separate cities. Which two Power Query transformations fix this with the least effort?","opts":["Trim, then Capitalize Each Word","Clean, then Lowercase","Split column by delimiter, then Merge columns","Replace values three times"],"ans":0,"exp":"Trim removes leading and trailing spaces and Capitalize Each Word gives consistent casing, so all variants become \"Dubai\".","why":["","Clean removes non-printable characters but not spaces, so \" Dubai\" stays different.","Splitting and merging doesn't normalize spaces or case.","Manual replacements break when new variants appear."],"ar":"لتوحيد النصوص: Trim ثم Capitalize Each Word.","ref":[{"t":"Data types in Power Query","u":"https://learn.microsoft.com/en-us/power-query/data-types"}]},{"id":"PL-CLN-006","d":"prep","s":"clean","type":"yesno","diff":2,"tag":"Nulls","q":"You're cleaning a Discount column in Power Query.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["Replace values can replace null with 0 in a numeric column.","Fill down copies the last non-null value into the null cells below it.","Remove empty on a column filter removes rows where the column is null or an empty text value."],"ans":[true,true,true],"exp":"Replace values accepts null as the value to find. Fill down fills nulls with the value above, which is common for report-style exports. Remove empty filters out null and empty values.","why":["Yes. Type null in Value to find.","Yes. Fill down and Fill up propagate existing values into nulls.","Yes. It removes null and blank rows for that column."],"ar":"Replace values يستبدل null، وFill down ينسخ القيمة السابقة، وRemove empty يحذف الفراغات.","ref":[{"t":"Dealing with errors in Power Query","u":"https://learn.microsoft.com/en-us/power-query/dealing-with-errors"}]},{"id":"PL-CLN-007","d":"prep","s":"clean","type":"single","diff":2,"tag":"Data quality","q":"A Customer dimension has duplicate CustomerID rows because the CRM export repeats customers with different LastModified dates. You need one row per customer, keeping the most recent version. What should you do in Power Query?","opts":["Sort by LastModified descending, add Table.Buffer, then Remove duplicates on CustomerID","Remove duplicates on CustomerID without sorting","Group by CustomerID and count rows","Use Keep duplicates on CustomerID"],"ans":0,"exp":"Remove duplicates keeps the first row it finds. Sorting by the most recent date first and buffering the sorted table makes sure the kept row is the latest version. Grouping with Max of LastModified and merging back is another valid pattern.","why":["","Without sorting, the row kept is arbitrary.","Counting rows doesn't give you the latest attributes.","Keep duplicates returns only the repeated rows."],"ar":"لاختيار أحدث صف: رتّب تنازليًا حسب التاريخ ثم Remove duplicates على المفتاح.","ref":[{"t":"Best practices when working with Power Query","u":"https://learn.microsoft.com/en-us/power-query/best-practices"}]},{"id":"PL-CLN-008","d":"prep","s":"clean","type":"single","diff":1,"tag":"Profiling","q":"Where do you turn on Column quality, Column distribution and Column profile in Power Query Editor?","opts":["View tab, Data Preview group","Home tab, Transform group","Model view, Properties pane","File > Options > Report settings"],"ans":0,"exp":"The data profiling options are check boxes in the Data Preview group of the View tab in Power Query Editor.","why":["","Transform holds transformations, not profiling views.","Model view doesn't show Power Query previews.","Report settings control report behavior."],"ar":"أدوات الـ profiling من تبويب View في Power Query Editor.","ref":[{"t":"Using the data profiling tools","u":"https://learn.microsoft.com/en-us/power-query/data-profiling-tools"}]},{"id":"PL-CLN-009","d":"prep","s":"clean","type":"single","diff":2,"tag":"Unexpected values","q":"Column profile for an Age column shows a minimum of -1 and a maximum of 999. The business confirms these are placeholder values for unknown ages. How should you handle them so averages are correct?","opts":["Replace -1 and 999 with null in Power Query","Replace them with 0","Leave them and use AVERAGE in DAX","Delete the Age column"],"ans":0,"exp":"Placeholder values distort statistics. Replacing them with null marks them as unknown, and aggregation functions such as AVERAGE ignore blanks, so the results stay correct.","why":["","Zero is a real value and would pull the average down.","The placeholders would inflate and distort the average.","The column is still useful for valid rows."],"ar":"القيم الوهمية مثل -1 و999 استبدلها بـ null حتى لا تفسد المتوسطات.","ref":[{"t":"Using the data profiling tools","u":"https://learn.microsoft.com/en-us/power-query/data-profiling-tools"}]},{"id":"PL-CLN-010","d":"prep","s":"clean","type":"order","diff":2,"tag":"Errors","q":"A query fails to load because a few rows in a Price column contain text. You want to find the cause and then fix it without losing valid rows. Which three actions should you perform in sequence?","opts":["Turn on Column quality to see the error percentage for Price","Use Keep errors on a duplicate query to inspect the failing rows","In the main query, apply Replace errors on Price with null (or fix the source values)","Remove the Price column","Change the Price column type to Text in the final step"],"ans":[0,1,2],"exp":"First measure the problem with Column quality, then inspect the exact failing rows with Keep errors in a separate query, and finally fix the main query with Replace errors or a proper conversion.","why":["Step 1.","Step 2.","Step 3.","Removing the column loses needed data.","Text prices can't be summed."],"ar":"الخطوات: Column quality ثم Keep errors للفحص ثم Replace errors في الاستعلام الأساسي.","ref":[{"t":"Dealing with errors in Power Query","u":"https://learn.microsoft.com/en-us/power-query/dealing-with-errors"},{"t":"Using the data profiling tools","u":"https://learn.microsoft.com/en-us/power-query/data-profiling-tools"}]},{"id":"PL-CLN-011","d":"prep","s":"clean","type":"single","diff":2,"tag":"Data quality","q":"Two source systems code gender differently: one uses M and F, the other uses Male and Female. After appending them, you need consistent values. What is the most maintainable approach?","opts":["Create a small mapping table and merge it to translate codes to one standard value","Write a nested IF calculated column in DAX","Replace values manually in each visual","Create two separate slicers"],"ans":0,"exp":"A mapping (lookup) table in Power Query centralizes the translation. New codes are handled by adding a row, and the model stays clean for every report.","why":["","A DAX column works but is harder to maintain and adds calculation after load.","Visual-level fixes don't fix the data.","Two slicers confuse users and don't fix the data."],"ar":"لتوحيد القيم استخدم جدول mapping ودمجه في Power Query.","ref":[{"t":"Merge queries overview","u":"https://learn.microsoft.com/en-us/power-query/merge-queries-overview"}]},{"id":"PL-CLN-012","d":"prep","s":"clean","type":"multi","n":2,"diff":2,"tag":"Data quality","q":"You're profiling a new Orders table before building the model. Which two findings should you fix in Power Query before loading? Each correct answer presents a complete solution. Select TWO.","opts":["OrderID has fewer distinct values than rows, but it should be the table's unique key","OrderDate is stored as text in several formats","The table has 500,000 rows","The Amount column has a Currency format in the source","The table name is Orders"],"ans":[0,1],"exp":"A key that isn't unique causes relationship and totals problems, and dates stored as inconsistent text break time intelligence. Both are data quality issues to resolve before load. Row count, formats and names aren't problems by themselves.","why":["Correct.","Correct.","500,000 rows is a normal size.","Formatting can be set in the model.","The name is fine."],"ar":"أصلح المفاتيح المكررة والتواريخ النصية قبل التحميل.","ref":[{"t":"Using the data profiling tools","u":"https://learn.microsoft.com/en-us/power-query/data-profiling-tools"},{"t":"Data types in Power Query","u":"https://learn.microsoft.com/en-us/power-query/data-types"}]},{"id":"PL-CLN-013","d":"prep","s":"clean","type":"single","diff":3,"tag":"Errors","q":"A custom column uses Number.From([Amount]) and fails on some rows. You want the column to return 0 for those rows without removing them. Which M expression should you use?","opts":["try Number.From([Amount]) otherwise 0","if [Amount] = null then 0 else [Amount]","Number.From([Amount]) ?? 0","Table.RemoveRowsWithErrors"],"ans":0,"exp":"The try ... otherwise expression catches errors raised by an expression and returns the fallback value, so failed conversions become 0.","why":["","This handles null but not text values that fail to convert.","The ?? operator handles null, not errors.","That function removes the rows, which isn't wanted."],"ar":"لمعالجة أخطاء التحويل داخل عمود استخدم try ... otherwise.","ref":[{"t":"Dealing with errors in Power Query","u":"https://learn.microsoft.com/en-us/power-query/dealing-with-errors"}]},{"id":"PL-CLN-014","d":"prep","s":"clean","type":"single","diff":1,"tag":"Profiling","q":"You need to see a histogram of values and statistics such as min, max, average and count of errors for one column. Which feature do you use?","opts":["Column profile","Column quality","Query diagnostics","Performance Analyzer"],"ans":0,"exp":"Column profile shows detailed statistics and a value distribution chart for the selected column.","why":["","Column quality only shows valid, error and empty percentages.","Query diagnostics trace query evaluation, not column statistics.","Performance Analyzer measures visuals in reports."],"ar":"Column profile يعرض الإحصاءات والتوزيع لعمود واحد.","ref":[{"t":"Using the data profiling tools","u":"https://learn.microsoft.com/en-us/power-query/data-profiling-tools"}]},{"id":"PL-CLN-015","d":"prep","s":"clean","type":"yesno","diff":2,"tag":"Import errors","q":"A refresh in Power BI Desktop completes but warns that 12 rows have errors.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["The rows with errors are loaded, with the failing cells shown as blank.","Power Query can create an Errors query to show the failing rows.","The same rows will fail silently in the service without any indication."],"ans":[true,true,false],"exp":"Cells that fail during load are loaded as blanks, and View errors creates a query that lists them. In the service, refresh history shows errors and warnings, so failures aren't silent.","why":["Yes. The error cells become blank values in the model.","Yes. View errors creates an Errors in query group to inspect them.","No. Refresh history reports problems, and failing refreshes send notifications."],"ar":"صفوف الأخطاء تُحمّل كقيم فارغة ويمكن فحصها عبر View errors.","ref":[{"t":"Dealing with errors in Power Query","u":"https://learn.microsoft.com/en-us/power-query/dealing-with-errors"}]},{"id":"PL-TRF-001","d":"prep","s":"transform","type":"single","diff":1,"tag":"Data types","q":"A ProductCode column contains values such as 00125 and 00987. After load, the leading zeros disappear. What should you do?","opts":["Set the column's data type to Text in Power Query","Set the data type to Whole Number","Format the column with a custom format string in the model","Sort the column by another column"],"ans":0,"exp":"Codes that look like numbers but aren't used for math should be Text. Converting to a number removes leading zeros, which changes the code itself.","why":["","Whole Number strips the leading zeros.","A format string changes display only and can't restore lost zeros.","Sorting doesn't change the values."],"ar":"الأكواد ذات الأصفار في البداية نوعها Text وليس رقم.","ref":[{"t":"Data types in Power Query","u":"https://learn.microsoft.com/en-us/power-query/data-types"}]},{"id":"PL-TRF-002","d":"prep","s":"transform","type":"single","diff":2,"tag":"Data types","q":"You import a price column that should be summed with exact precision to 4 decimal places, for example currency amounts. Which data type is the best choice?","opts":["Fixed decimal number","Decimal number","Whole number","Text"],"ans":0,"exp":"Fixed decimal number (currency) stores values with four digits after the decimal and avoids floating-point rounding issues in totals.","why":["","Decimal number is a floating-point type and can show tiny rounding differences.","Whole number drops the decimals.","Text can't be aggregated."],"ar":"المبالغ المالية الأفضل لها Fixed decimal number.","ref":[{"t":"Data types in Power Query","u":"https://learn.microsoft.com/en-us/power-query/data-types"}]},{"id":"PL-TRF-003","d":"prep","s":"transform","type":"single","diff":1,"tag":"Unpivot","q":"A budget table has one row per region and one column per month (Jan, Feb, Mar and so on). You need one row per region and month with a Month column and an Amount column. What should you do?","opts":["Select the Region column and use Unpivot other columns","Select the month columns and use Pivot column","Use Transpose","Use Group by on Region"],"ans":0,"exp":"Unpivot turns column headers into attribute values, producing a long table with Region, Attribute (month) and Value columns. Unpivot other columns keeps working when new month columns appear.","why":["","Pivot does the opposite: rows to columns.","Transpose swaps all rows and columns, which isn't the shape you need.","Group by aggregates rows but doesn't reshape columns."],"ar":"الأعمدة الشهرية تتحول إلى صفوف باستخدام Unpivot other columns.","ref":[{"t":"Unpivot columns","u":"https://learn.microsoft.com/en-us/power-query/unpivot-column"}]},{"id":"PL-TRF-004","d":"prep","s":"transform","type":"single","diff":2,"tag":"Unpivot","q":"Why is Unpivot other columns usually better than Unpivot columns (selected) for a monthly budget file that gets a new month column every month?","opts":["It unpivots every column except the ones you keep, so new month columns are included automatically","It runs faster on large files","It keeps the original column order","It also changes the data types to Date"],"ans":0,"exp":"Unpivot columns hard-codes the selected column names in the M step. Unpivot other columns stores the columns to keep, so any new month column is unpivoted without editing the query.","why":["","Performance isn't the reason.","Column order isn't the difference.","Neither option changes types automatically."],"ar":"Unpivot other columns يلتقط الأعمدة الجديدة تلقائيًا.","ref":[{"t":"Unpivot columns","u":"https://learn.microsoft.com/en-us/power-query/unpivot-column"}]},{"id":"PL-TRF-005","d":"prep","s":"transform","type":"single","diff":1,"tag":"Pivot","q":"A table has columns Date, Metric and Value, where Metric contains Revenue, Cost and Units. You need separate Revenue, Cost and Units columns. What should you do?","opts":["Select Metric and use Pivot column with Value as the values column","Unpivot Metric","Transpose the table","Split Metric by delimiter"],"ans":0,"exp":"Pivot column turns the distinct values of one column into new columns and fills them from the values column, aggregating if needed.","why":["","Unpivot does the opposite.","Transpose swaps the whole table.","Splitting text doesn't reshape rows into columns."],"ar":"لتحويل القيم إلى أعمدة استخدم Pivot column.","ref":[{"t":"Pivot columns","u":"https://learn.microsoft.com/en-us/power-query/pivot-columns"}]},{"id":"PL-TRF-006","d":"prep","s":"transform","type":"single","diff":2,"tag":"Group by","q":"You need a table of total sales and number of orders per customer from an order lines table, created in Power Query. What should you use?","opts":["Group by CustomerID with an advanced grouping: Sum of Amount and Count distinct of OrderID","Remove duplicates on CustomerID","Merge the table with itself","Pivot CustomerID"],"ans":0,"exp":"Group by with the Advanced option lets you define several aggregations at once, such as a sum and a distinct count, returning one row per customer.","why":["","Removing duplicates keeps one row but doesn't aggregate.","A self-merge doesn't aggregate.","Pivoting customers into columns creates a wide, unusable table."],"ar":"للتجميع في Power Query استخدم Group by مع Advanced لعدة تجميعات.","ref":[{"t":"Grouping or summarizing rows","u":"https://learn.microsoft.com/en-us/power-query/group-by"}]},{"id":"PL-TRF-007","d":"prep","s":"transform","type":"single","diff":1,"tag":"Append","q":"You have three tables, Sales2024, Sales2025 and Sales2026, with the same columns. You need one Sales table. What should you do?","opts":["Append queries as new","Merge queries as new","Create relationships between the three tables","Use Pivot column"],"ans":0,"exp":"Append stacks tables with the same structure one under another. Append queries as new keeps the originals and creates a combined query.","why":["","Merge joins tables side by side by matching keys.","Relationships don't combine rows.","Pivot reshapes columns."],"ar":"جداول بنفس الأعمدة تُدمج فوق بعض باستخدام Append.","ref":[{"t":"Append queries","u":"https://learn.microsoft.com/en-us/power-query/append-queries"}]},{"id":"PL-TRF-008","d":"prep","s":"transform","type":"single","diff":1,"tag":"Merge","q":"An Orders query has ProductID. A Products query has ProductID and Category. You need Category in Orders during data preparation. What should you do?","opts":["Merge Orders with Products on ProductID using a left outer join, then expand Category","Append Products to Orders","Unpivot Products","Create a calculated column with RELATED before load"],"ans":0,"exp":"Merge performs a join. A left outer join keeps every order and brings matching columns from Products, which you then expand.","why":["","Append stacks rows, it doesn't look up values.","Unpivot reshapes columns.","RELATED is DAX, evaluated after load, and needs a relationship."],"ar":"لجلب عمود من جدول آخر استخدم Merge بـ left outer ثم Expand.","ref":[{"t":"Merge queries overview","u":"https://learn.microsoft.com/en-us/power-query/merge-queries-overview"}]},{"id":"PL-TRF-009","d":"prep","s":"transform","type":"single","diff":2,"tag":"Merge","q":"You need a list of customers in the Customers query who have never placed an order in the Orders query. Which join kind should you use when merging Customers with Orders on CustomerID?","opts":["Left anti","Left outer","Inner","Full outer"],"ans":0,"exp":"A left anti join returns rows from the first table that have no match in the second table, which is exactly customers without orders.","why":["","Left outer returns all customers, with or without orders.","Inner returns only customers who have orders.","Full outer returns everything from both tables."],"ar":"العملاء بدون طلبات = Left anti join.","ref":[{"t":"Merge queries overview","u":"https://learn.microsoft.com/en-us/power-query/merge-queries-overview"}]},{"id":"PL-TRF-010","d":"prep","s":"transform","type":"yesno","diff":2,"tag":"Merge","q":"You're merging two queries in Power Query.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["Fuzzy matching can match \"Contoso Ltd\" with \"Contoso Ltd.\" in a merge.","An inner join keeps rows from both tables even when they have no match.","You can merge on more than one column by selecting the columns in the same order in both tables."],"ans":[true,false,true],"exp":"Fuzzy merge compares text by similarity and can match near duplicates. An inner join keeps only matching rows. Multi-column merges pair the selected columns in the order you select them.","why":["Yes. Fuzzy matching uses a similarity threshold.","No. Inner join returns only rows with matches in both tables.","Yes. Select the key columns in matching order in both tables."],"ar":"Fuzzy merge يطابق النصوص المتشابهة، وInner join يعيد المتطابق فقط، ويمكن الدمج على أكثر من عمود.","ref":[{"t":"Merge queries overview","u":"https://learn.microsoft.com/en-us/power-query/merge-queries-overview"}]},{"id":"PL-TRF-011","d":"prep","s":"transform","type":"single","diff":2,"tag":"Reference vs duplicate","q":"You have a query named RawSales with 15 cleaning steps. You need two new queries, SalesByDay and SalesByStore, that both start from the cleaned RawSales, and any future fix to RawSales must flow to both. What should you create?","opts":["Two queries that Reference RawSales","Two queries that Duplicate RawSales","Two copies of the source file","Two calculated tables in DAX"],"ans":0,"exp":"Reference creates a new query whose source is the output of RawSales, so changes to RawSales flow through. Duplicate copies all steps into an independent query, so later fixes wouldn't flow.","why":["","Duplicates copy the steps and become independent, so fixes wouldn't propagate.","Copying files duplicates work and sources.","Calculated tables happen after load and add model size."],"ar":"Reference يرث أي تعديل على الاستعلام الأصلي، أما Duplicate فنسخة مستقلة.","ref":[{"t":"Clean, transform, and load data in Power BI (training)","u":"https://learn.microsoft.com/en-us/training/modules/clean-data-power-bi/"}]},{"id":"PL-TRF-012","d":"prep","s":"transform","type":"single","diff":2,"tag":"Reference vs duplicate","q":"You referenced a staging query named StgCustomers from two other queries. StgCustomers is only an intermediate step and must not appear as a table in the model. What should you do?","opts":["Clear Enable load for StgCustomers","Delete StgCustomers","Hide StgCustomers in Report view","Clear Include in report refresh for StgCustomers"],"ans":0,"exp":"Disabling load keeps the query available to other queries but doesn't create a table in the model, which reduces model size and clutter.","why":["","Deleting it breaks the two queries that reference it.","A hidden table is still loaded and uses memory.","Excluding it from refresh could leave dependent queries with stale data and it still loads as a table."],"ar":"الاستعلامات الوسيطة: ألغِ Enable load حتى لا تُحمّل كجداول.","ref":[{"t":"Best practices when working with Power Query","u":"https://learn.microsoft.com/en-us/power-query/best-practices"}]},{"id":"PL-TRF-013","d":"prep","s":"transform","type":"single","diff":1,"tag":"Star schema","q":"A single flat table contains order lines plus product name, product category, customer name and customer city repeated on every row. Following best practice for Power BI, how should you model it?","opts":["Split it into a Sales fact table and Product and Customer dimension tables related by keys","Keep one flat table for simplicity","Create one table per column","Create a separate table for each year"],"ans":0,"exp":"A star schema separates numeric events (facts) from descriptive attributes (dimensions). It reduces duplication, makes filtering predictable and is the design Power BI is optimized for.","why":["","Flat tables repeat attributes, grow larger and make some calculations harder.","One table per column isn't a meaningful design.","Splitting by year makes analysis across years harder."],"ar":"الأفضل في Power BI: star schema بجدول حقائق وجداول أبعاد.","ref":[{"t":"Understand star schema and the importance for Power BI","u":"https://learn.microsoft.com/en-us/power-bi/guidance/star-schema"}]},{"id":"PL-TRF-014","d":"prep","s":"transform","type":"order","diff":3,"tag":"Star schema","q":"You're building a Product dimension from a flat Sales table in Power Query. Which three actions should you perform in sequence?","opts":["Reference the Sales query to create a new query named Product","Keep only the product columns and use Remove duplicates on ProductID","In the model, relate Product[ProductID] to Sales[ProductID] (one-to-many) and remove the descriptive product columns from Sales","Duplicate the Sales query and keep all columns","Create a many-to-many relationship on ProductName"],"ans":[0,1,2],"exp":"Start from the cleaned Sales output by referencing it, reduce it to unique products, then relate the dimension to the fact table on the key and drop the repeated attributes from the fact.","why":["Step 1.","Step 2.","Step 3.","Duplicating copies all steps and keeps every column.","Names aren't reliable keys and many-to-many isn't needed."],"ar":"الخطوات: Reference ثم إبقاء أعمدة المنتج وإزالة التكرار ثم علاقة واحد لمتعدد.","ref":[{"t":"Understand star schema and the importance for Power BI","u":"https://learn.microsoft.com/en-us/power-bi/guidance/star-schema"},{"t":"Clean, transform, and load data in Power BI (training)","u":"https://learn.microsoft.com/en-us/training/modules/clean-data-power-bi/"}]},{"id":"PL-TRF-015","d":"prep","s":"transform","type":"single","diff":2,"tag":"Keys","q":"Two source systems both use numbers 1 to 5000 as CustomerID. After appending them into one Customer dimension, keys collide. What is the best way to create a unique key?","opts":["Add a column that combines the source system code and the CustomerID, and use it as the key in both the dimension and the fact","Remove duplicates on CustomerID","Use the customer name as the key","Add an Index column only in the dimension table"],"ans":0,"exp":"A composite key such as SYS1-1234 is unique across systems and can be built the same way in the fact table so relationships match. A surrogate index is also valid only if the fact gets the same value through a merge.","why":["","Removing duplicates would drop real customers.","Names aren't unique or stable.","An index in the dimension alone doesn't exist in the fact, so the relationship can't be built."],"ar":"عند تعارض المفاتيح من أنظمة مختلفة: اصنع مفتاحًا مركبًا من كود النظام + المعرف.","ref":[{"t":"Understand star schema and the importance for Power BI","u":"https://learn.microsoft.com/en-us/power-bi/guidance/star-schema"}]},{"id":"PL-TRF-016","d":"prep","s":"transform","type":"single","diff":1,"tag":"Columns","q":"You need a FullName column from FirstName and LastName with a space between them, created in Power Query. Which option is the fastest?","opts":["Select both columns and use Merge columns with a Space separator","Split column by delimiter","Group by FirstName","Pivot LastName"],"ans":0,"exp":"Merge columns (on the Add column or Transform tab) concatenates the selected columns with a separator of your choice.","why":["","Split does the opposite.","Group by aggregates rows.","Pivot reshapes values into columns."],"ar":"لدمج عمودين نصيين استخدم Merge columns مع فاصل.","ref":[{"t":"Add a column from examples","u":"https://learn.microsoft.com/en-us/power-query/column-from-example"}]},{"id":"PL-TRF-017","d":"prep","s":"transform","type":"single","diff":2,"tag":"Columns","q":"You need a column that extracts the year and quarter as text like \"2026 Q3\" from an OrderDate column, but you aren't sure how to write M. Which feature can build the column from a couple of typed examples?","opts":["Column from examples","Conditional column","Invoke custom function","Index column"],"ans":0,"exp":"Column from examples lets you type the expected output for a few rows. Power Query infers the transformation and writes the M code for you.","why":["","A conditional column uses if-then rules, which don't fit a date-to-text transformation.","Custom functions must already exist.","An index column numbers rows."],"ar":"Column from examples يكتب لك الكود من أمثلة تكتبها.","ref":[{"t":"Add a column from examples","u":"https://learn.microsoft.com/en-us/power-query/column-from-example"}]},{"id":"PL-TRF-018","d":"prep","s":"transform","type":"single","diff":2,"tag":"Semi-structured","q":"A column contains values like {\"color\":\"red\",\"size\":\"M\"} stored as text. You need Color and Size columns. What should you do?","opts":["Use Parse > JSON on the column, then expand the record","Split the column by comma","Use Transpose","Change the type to Record"],"ans":0,"exp":"Parse JSON converts the text into a record, which you then expand into separate columns.","why":["","Splitting by comma leaves quotes and keys in the values.","Transpose swaps rows and columns.","You can't set a type to Record from the type menu. Parsing is required."],"ar":"نص بصيغة JSON داخل عمود: Parse JSON ثم Expand.","ref":[{"t":"JSON (Power Query connector)","u":"https://learn.microsoft.com/en-us/power-query/connectors/json"}]},{"id":"PL-TRF-019","d":"prep","s":"transform","type":"single","diff":2,"tag":"Semi-structured","q":"An Excel report export has a two-row header: the first row holds the month, the second row holds Actual or Budget under each month. What sequence usually turns it into a proper table?","opts":["Transpose, fill down the month column, merge the two header columns, transpose back, promote headers, then unpivot","Promote headers once and unpivot","Use Group by on the first column","Remove the first two rows"],"ans":0,"exp":"Multi-row headers are handled by transposing so the header rows become columns, filling down the blank month cells, combining the two header columns into one name, transposing back and promoting headers. Then unpivot to get one row per month and type.","why":["","Promoting once loses the second header row.","Group by doesn't fix headers.","Removing the header rows loses the month and type information."],"ar":"العناوين المكونة من صفين: Transpose ثم Fill down ثم Merge ثم Transpose ثم Promote ثم Unpivot.","ref":[{"t":"Unpivot columns","u":"https://learn.microsoft.com/en-us/power-query/unpivot-column"},{"t":"Pivot columns","u":"https://learn.microsoft.com/en-us/power-query/pivot-columns"}]},{"id":"PL-TRF-020","d":"prep","s":"transform","type":"yesno","diff":2,"tag":"Loading","q":"You're configuring how queries load in Power BI Desktop.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["A query with Enable load cleared can still be referenced by other queries.","Clearing Include in report refresh stops the table from refreshing when you select Refresh.","A query with Enable load cleared still appears in the Data pane of the report."],"ans":[true,true,false],"exp":"Disabled queries still run when other queries reference them but aren't loaded into the model, so they don't appear in the Data pane. Include in report refresh controls whether a loaded table refreshes during a model refresh.","why":["Yes. It remains available as a source for other queries.","Yes. The table keeps its last loaded data during refresh.","No. It isn't loaded, so it doesn't appear in the model."],"ar":"Enable load يتحكم بالتحميل للنموذج، وInclude in report refresh يتحكم بالتحديث.","ref":[{"t":"Best practices when working with Power Query","u":"https://learn.microsoft.com/en-us/power-query/best-practices"}]},{"id":"PL-TRF-021","d":"prep","s":"transform","type":"multi","n":2,"diff":2,"tag":"Star schema","q":"You're designing a sales model. Which two columns belong in the Sales fact table rather than in a dimension? Each correct answer presents a complete solution. Select TWO.","opts":["SalesAmount","OrderQuantity","ProductColor","CustomerCity","CategoryName"],"ans":[0,1],"exp":"Fact tables store measurable events and keys. Amounts and quantities are facts. Colors, cities and category names describe entities and belong in dimensions.","why":["Correct.","Correct.","Product attributes belong in the Product dimension.","Customer attributes belong in the Customer dimension.","Category belongs in the Product dimension."],"ar":"الأرقام القابلة للجمع في جدول الحقائق، والأوصاف في الأبعاد.","ref":[{"t":"Understand star schema and the importance for Power BI","u":"https://learn.microsoft.com/en-us/power-bi/guidance/star-schema"}]},{"id":"PL-TRF-022","d":"prep","s":"transform","type":"single","diff":3,"tag":"Semi-structured","q":"A web API returns a JSON list of orders where each order has a nested list of line items. You need one row per line item with the order number repeated. What is the correct approach after converting the orders list to a table?","opts":["Expand the order record, then expand the line items list to new rows, then expand the line item records","Expand the line items list to comma-separated values","Transpose the table","Use Group by on order number"],"ans":0,"exp":"Expanding a list column to new rows creates one row per list element while keeping the parent columns such as the order number. Then expand each line item record into columns.","why":["","Extracting values into one text cell loses the row structure.","Transpose doesn't flatten nested lists.","Group by aggregates, it doesn't flatten."],"ar":"القوائم المتداخلة: Expand to New Rows ثم Expand للسجلات.","ref":[{"t":"JSON (Power Query connector)","u":"https://learn.microsoft.com/en-us/power-query/connectors/json"}]},{"id":"PL-TRF-023","d":"prep","s":"transform","type":"single","diff":1,"tag":"Transpose","q":"A small settings table from Excel has field names in the first column and values in the second column, but you need the field names as column headers. What should you do?","opts":["Transpose the table, then Use first row as headers","Unpivot all columns","Pivot the second column","Group by the first column"],"ans":0,"exp":"Transpose turns rows into columns. After transposing, the field names are in the first row, so you promote them to headers.","why":["","Unpivot makes the table longer, not wider.","Pivoting the second column would turn the values, not the field names, into headers.","Group by aggregates rows."],"ar":"لقلب الصفوف إلى أعمدة: Transpose ثم Use first row as headers.","ref":[{"t":"Pivot columns","u":"https://learn.microsoft.com/en-us/power-query/pivot-columns"}]},{"id":"PL-TRF-024","d":"prep","s":"transform","type":"single","diff":2,"tag":"Group by","q":"In Power Query you grouped Sales by Region with the operation All rows, creating a nested Rows column. What can you do with it next?","opts":["Add a custom column that works on each nested table, for example to rank or get the top row per region","Nothing, All rows can't be used","Load it directly as a relationship","Use it only in DAX"],"ans":0,"exp":"All rows keeps the detail rows for each group as a nested table. Custom columns can process each nested table (for example, Table.Max or adding an index) before expanding the results.","why":["","All rows is a powerful pattern for per-group logic.","Nested tables can't become relationships.","Nested tables must be expanded before load."],"ar":"Group by مع All rows يسمح بعمليات على كل مجموعة مثل أعلى صف لكل منطقة.","ref":[{"t":"Grouping or summarizing rows","u":"https://learn.microsoft.com/en-us/power-query/group-by"}]},{"id":"PL-TRF-025","d":"prep","s":"transform","type":"single","diff":2,"tag":"Dimensions","q":"You need a Date dimension with every date from 1 January 2024 to 31 December 2027, created in Power Query so it's available to all tables. Which approach works?","opts":["Create a blank query with List.Dates, convert it to a table, then add Year, Month and other columns","Use Group by on the Sales date column","Use Remove duplicates on the Sales date column only","Unpivot the Sales table"],"ans":0,"exp":"List.Dates builds a complete, contiguous list of dates, which is required for a proper date table. Extracting unique dates from Sales would miss days without sales.","why":["","Grouping sales dates skips days with no sales.","Unique sales dates also leave gaps.","Unpivot doesn't create dates."],"ar":"جدول تاريخ كامل بدون فجوات: List.Dates في Power Query أو CALENDAR في DAX.","ref":[{"t":"Date table guidance for Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/guidance/model-date-tables"}]},{"id":"PL-DES-001","d":"model","s":"design","type":"single","diff":1,"tag":"Relationships","q":"A Product table has one row per ProductID. A Sales table has many rows per ProductID. What cardinality should the relationship have?","opts":["One-to-many (Product to Sales)","Many-to-many","One-to-one","Many-to-one from Product to Sales"],"ans":0,"exp":"The dimension side (Product) has unique keys and the fact side (Sales) repeats them, so the relationship is one-to-many from Product to Sales.","why":["","Many-to-many is only needed when neither side has unique values.","One-to-one means both sides are unique, which Sales isn't.","The \"one\" side is Product, not Sales."],"ar":"البعد (قيم فريدة) إلى الحقائق (قيم مكررة) = One-to-many.","ref":[{"t":"Model relationships in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-relationships-understand"}]},{"id":"PL-DES-002","d":"model","s":"design","type":"single","diff":2,"tag":"Cross-filter direction","q":"Your model has Product related to Sales (one-to-many, single direction). A slicer on Sales[Channel] must filter a visual that lists products. What's the recommended approach that avoids ambiguity?","opts":["Use a measure that counts sales rows and filter the product visual where the measure isn't blank","Set every relationship in the model to Both directions","Create a many-to-many relationship","Duplicate the Product table"],"ans":0,"exp":"Bi-directional filters can cause ambiguity and slower queries. Filtering the product visual by a measure based on Sales (for example, Sales rows is not blank) achieves the same result while keeping single-direction relationships.","why":["","Setting all relationships to Both creates ambiguous filter paths and hurts performance.","Many-to-many isn't needed for a one-to-many key.","Duplicating Product doesn't make Sales filter it."],"ar":"تجنب Both direction قدر الإمكان، واستخدم مقياسًا لفلترة الأبعاد من جدول الحقائق.","ref":[{"t":"Bi-directional relationship guidance","u":"https://learn.microsoft.com/en-us/power-bi/guidance/relationships-bidirectional-filtering"}]},{"id":"PL-DES-003","d":"model","s":"design","type":"yesno","diff":2,"tag":"Cross-filter direction","q":"You're reviewing relationship settings.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["In a one-to-many relationship with single cross-filter direction, filters flow from the one side to the many side.","Bi-directional filtering is required for row-level security to reach the fact table from a dimension.","A one-to-one relationship always filters in both directions."],"ans":[true,false,true],"exp":"Single direction filters from the dimension to the fact. RLS on a dimension already reaches the fact through a one-to-many relationship. One-to-one relationships always use both directions.","why":["Yes. That's the default and recommended direction.","No. RLS on a dimension filters the related fact rows through the normal one-to-many direction. Bi-directional RLS is only needed in special cases.","Yes. One-to-one relationships are always bi-directional."],"ar":"الفلترة الافتراضية من البعد للحقائق، وRLS على البعد يصل للحقائق بدون Both.","ref":[{"t":"Model relationships in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-relationships-understand"},{"t":"Row-level security (RLS) guidance in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/guidance/rls-guidance"}]},{"id":"PL-DES-004","d":"model","s":"design","type":"single","diff":2,"tag":"Role-playing dimension","q":"Sales has OrderDate, ShipDate and DueDate. There's one Date table. You created three relationships; one is active and two are inactive. You need a measure that shows sales by ship date. What should you use?","opts":["CALCULATE([Sales], USERELATIONSHIP(Sales[ShipDate], 'Date'[Date]))","RELATED('Date'[Date])","Make all three relationships active","CROSSFILTER with Both"],"ans":0,"exp":"Only one relationship between two tables can be active. USERELATIONSHIP activates an inactive relationship for the duration of the CALCULATE, which is the standard way to use a role-playing date dimension.","why":["","RELATED fetches a value in row context; it doesn't change which relationship filters.","Only one active relationship is allowed between the same two tables.","CROSSFILTER changes direction, not which relationship is used."],"ar":"البعد متعدد الأدوار: علاقة واحدة نشطة والباقي عبر USERELATIONSHIP داخل CALCULATE.","ref":[{"t":"USERELATIONSHIP function (DAX)","u":"https://learn.microsoft.com/en-us/dax/userelationship-function-dax"},{"t":"Understand star schema and the importance for Power BI","u":"https://learn.microsoft.com/en-us/power-bi/guidance/star-schema"}]},{"id":"PL-DES-005","d":"model","s":"design","type":"single","diff":2,"tag":"Role-playing dimension","q":"Report authors in your company find USERELATIONSHIP measures confusing. They want to slice by Order Date and Ship Date at the same time in the same visual. What model design supports this?","opts":["Create a second date table (Ship Date) related to Sales[ShipDate] as an active relationship","Add a Both direction filter on the Date relationship","Hide the Date table","Create a calculated column with USERELATIONSHIP"],"ans":0,"exp":"Separate role-playing dimension tables (Order Date and Ship Date), each with its own active relationship, let users filter by both dates at once without special measures.","why":["","Direction doesn't create a second role.","Hiding the table removes filtering.","USERELATIONSHIP only works inside CALCULATE in measures."],"ar":"للتصفية بتاريخين معًا: جدولي تاريخ منفصلين لكل دور.","ref":[{"t":"Understand star schema and the importance for Power BI","u":"https://learn.microsoft.com/en-us/power-bi/guidance/star-schema"}]},{"id":"PL-DES-006","d":"model","s":"design","type":"single","diff":1,"tag":"Date table","q":"You created a Date table with CALENDAR. Time intelligence functions such as TOTALYTD must use it. What should you do?","opts":["Mark it as a date table and select its Date column","Rename it to Calendar","Hide it","Set its storage mode to Dual"],"ans":0,"exp":"Marking a table as a date table tells Power BI which column holds the dates. It validates the column (unique, no blanks, contiguous) and makes time intelligence use your table instead of automatic date tables.","why":["","The table's name doesn't matter.","Hiding doesn't define it as a date table.","Storage mode is unrelated."],"ar":"جدول التاريخ يجب تعليمه Mark as date table.","ref":[{"t":"Set and use date tables in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-date-tables"}]},{"id":"PL-DES-007","d":"model","s":"design","type":"multi","n":2,"diff":2,"tag":"Date table","q":"Which two requirements must a column meet before you can mark its table as a date table? Each correct answer presents a complete solution. Select TWO.","opts":["It contains unique values with no blanks","It contains contiguous dates covering full years with no gaps","It must be named Date","It must be in DirectQuery mode","It must include a time portion"],"ans":[0,1],"exp":"The date column must be of type Date or Date/Time, have unique values, contain no blanks and have no missing dates in the range. Its name and storage mode don't matter.","why":["Correct.","Correct.","Any column name is allowed.","Any storage mode is allowed.","A time portion isn't required; dates at midnight are typical."],"ar":"شروط جدول التاريخ: قيم فريدة بدون فراغات، وتواريخ متصلة بلا فجوات.","ref":[{"t":"Set and use date tables in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-date-tables"},{"t":"Date table guidance for Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/guidance/model-date-tables"}]},{"id":"PL-DES-008","d":"model","s":"design","type":"single","diff":2,"tag":"Date table","q":"Your model has 12 date columns across several tables, and the file size is larger than expected. You already have a proper Date table. What setting should you change?","opts":["Turn off Auto date/time for the file","Turn on Auto date/time","Change every date column to Text","Mark every table as a date table"],"ans":0,"exp":"Auto date/time creates a hidden date table for every date column, which inflates the model. With a dedicated Date table, turn it off in File > Options > Current file > Data load.","why":["","That's what causes the hidden tables.","Text dates break time intelligence.","Only one table should be the date table."],"ar":"عند وجود جدول تاريخ خاص أوقف Auto date/time لتقليل حجم النموذج.","ref":[{"t":"Auto date/time guidance in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/guidance/auto-date-time"}]},{"id":"PL-DES-009","d":"model","s":"design","type":"single","diff":1,"tag":"Properties","q":"A Month Name column sorts alphabetically (April, August, December). You need calendar order. What should you do?","opts":["Set Sort by column on Month Name to a Month Number column","Change Month Name to a Date type","Sort the visual by value","Add a leading number to each month name"],"ans":0,"exp":"Sort by column tells Power BI to order one column by the values of another column, such as MonthNumber 1 to 12.","why":["","Month names aren't dates.","Sorting by value orders by the measure, not the calendar.","Adding numbers changes the displayed names."],"ar":"لترتيب أسماء الشهور زمنيًا استخدم Sort by column برقم الشهر.","ref":[{"t":"Sort one column by another column in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-sort-by-column"}]},{"id":"PL-DES-010","d":"model","s":"design","type":"yesno","diff":2,"tag":"Properties","q":"You're configuring column properties in Model view.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["Setting a City column's Data category to City helps map visuals place it correctly.","Setting Summarize by to None stops a Year column from being summed when added to a visual.","Hiding a column in Report view also removes it from the model's memory."],"ans":[true,true,false],"exp":"Data category gives geographic and URL hints to visuals. Summarize by None prevents default aggregation of numeric columns such as Year. Hidden columns are still loaded; they're just not shown in the Data pane.","why":["Yes. Geographic categories improve map geocoding.","Yes. The column will be grouped, not summed.","No. Hidden columns still use memory. Remove them in Power Query to save space."],"ar":"Data category للخرائط، وSummarize by None لمنع جمع عمود السنة، والإخفاء لا يقلل الذاكرة.","ref":[{"t":"Work with Model explorer","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/model-explorer"}]},{"id":"PL-DES-011","d":"model","s":"design","type":"single","diff":2,"tag":"Calculated column vs measure","q":"You need each customer classified as Small, Medium or Large based on the customer's lifetime sales, and the class must be usable in a slicer. What should you create?","opts":["A calculated column in the Customer table","A measure","A visual calculation","A quick measure"],"ans":0,"exp":"Slicers and axes need columns. A calculated column is evaluated for each customer row at refresh time and stored, so it can be used to slice and group.","why":["","Measures can't be placed in slicers.","Visual calculations live on one visual and can't be used as slicers.","Quick measures create measures."],"ar":"للتقسيم في Slicer تحتاج عمودًا (calculated column) وليس مقياسًا.","ref":[{"t":"Use calculation options in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-calculations-options"}]},{"id":"PL-DES-012","d":"model","s":"design","type":"single","diff":2,"tag":"Calculated tables","q":"You need a table listing the top 10 products by sales at refresh time, used for a separate relationship-free analysis page. Which option fits best?","opts":["A calculated table using TOPN","A measure using TOPN","A calculated column using TOPN","A Power Query parameter"],"ans":0,"exp":"A calculated table is evaluated at refresh and stores rows in the model, so it can hold a static top-10 list. Measures return scalar values and calculated columns add values to an existing table.","why":["","Measures return single values, not tables in the model.","A calculated column can't create new rows.","Parameters store single values."],"ar":"لإنشاء جدول من DAX وقت الـ refresh استخدم calculated table.","ref":[{"t":"Use calculation options in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-calculations-options"}]},{"id":"PL-DES-013","d":"model","s":"design","type":"single","diff":3,"tag":"Many-to-many","q":"A Budget table is at Category and Month grain, while Sales is at Product and Date grain. You need Budget and Sales in the same visual by Category and Month. What's the recommended design?","opts":["Relate Budget to Category and Month dimension tables (or bridge tables) so both facts share dimensions at the right grain","Create a direct many-to-many relationship between Budget and Sales","Merge Budget into Sales","Use bi-directional filters on every relationship"],"ans":0,"exp":"Facts at different grains should connect through shared dimensions at the level they both support. A dimension (or a bridge) for Category and for Month lets filters flow to both facts.","why":["","Relating two fact tables directly is ambiguous and not recommended.","Merging duplicates budget values on every sales row.","Bi-directional filters everywhere cause ambiguity."],"ar":"جداول حقائق بمستويات مختلفة تُربط عبر أبعاد مشتركة بالمستوى المناسب.","ref":[{"t":"Apply many-to-many relationships in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-many-to-many-relationships"},{"t":"Understand star schema and the importance for Power BI","u":"https://learn.microsoft.com/en-us/power-bi/guidance/star-schema"}]},{"id":"PL-DES-014","d":"model","s":"design","type":"single","diff":2,"tag":"Hierarchies","q":"Users want to drill from Category to Subcategory to Product in visuals. What should you create in the model?","opts":["A hierarchy in the Product table with Category, Subcategory and Product levels","Three separate slicers","A calculated table for each level","A bookmark"],"ans":0,"exp":"A hierarchy groups columns into levels. Visuals can then drill down and up through the levels without adding fields one by one.","why":["","Slicers filter but don't provide drill-down.","Separate tables break the natural path.","Bookmarks capture states, not drill paths."],"ar":"للـ drill down أنشئ hierarchy في جدول البعد.","ref":[{"t":"Work with Model explorer","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/model-explorer"}]},{"id":"PL-DES-015","d":"model","s":"design","type":"single","diff":1,"tag":"Properties","q":"You want users to find measures quickly. What property groups related measures into folders in the Data pane?","opts":["Display folder","Description","Synonyms","Data category"],"ans":0,"exp":"Display folders organize measures and columns into folders in the Data pane without changing the model.","why":["","Descriptions appear as tooltips on hover.","Synonyms help Q&A and Copilot understand terms.","Data category helps visuals interpret values."],"ar":"Display folder لتنظيم المقاييس في مجلدات.","ref":[{"t":"Work with Model explorer","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/model-explorer"}]},{"id":"PL-DES-016","d":"model","s":"design","type":"single","diff":3,"tag":"Relationships","q":"You create a relationship between Customer[CustomerID] and Sales[CustomerID], but Power BI sets it to many-to-many. You expected one-to-many. What's the most likely cause?","opts":["Customer[CustomerID] contains duplicate values (or blanks repeated)","Sales[CustomerID] contains duplicates","The columns have different names","Auto date/time is turned on"],"ans":0,"exp":"For one-to-many, the one side must be unique. If Power BI detects duplicates in Customer[CustomerID], it can't create one-to-many. Fix the duplicates in Power Query.","why":["","Duplicates on the many side are expected.","Column names don't have to match.","Auto date/time doesn't affect this relationship."],"ar":"لو ظهرت many-to-many بدل one-to-many فغالبًا المفتاح في جدول البعد مكرر.","ref":[{"t":"Model relationships in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-relationships-understand"}]},{"id":"PL-DES-017","d":"model","s":"design","type":"yesno","diff":3,"tag":"Calculation options","q":"You're deciding between calculated columns, measures and visual calculations.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["Measures are calculated at query time and respond to filters and slicers.","Calculated columns are recalculated each time a slicer changes.","A visual calculation can refer only to fields that are in its visual."],"ans":[true,false,true],"exp":"Measures are evaluated at query time in the filter context. Calculated columns are computed at refresh and stored. Visual calculations run on the visual's data and can only reference fields placed on that visual.","why":["Yes.","No. Calculated columns are computed during refresh and don't change with slicers.","Yes. Add a field to the visual first if the calculation needs it."],"ar":"المقاييس وقت الاستعلام، والأعمدة المحسوبة وقت الـ refresh، وVisual calculation تشير فقط لحقول الـ visual.","ref":[{"t":"Use calculation options in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-calculations-options"},{"t":"Visual calculations","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-visual-calculations-overview"}]},{"id":"PL-DES-018","d":"model","s":"design","type":"single","diff":2,"tag":"Properties","q":"A semantic model will be used by Copilot and Q&A. Users type \"revenue\" but the measure is named Net Sales Amount. What should you add to improve results?","opts":["Synonyms (and a description) on the Net Sales Amount measure","A display folder named Revenue","A second measure named Revenue that returns the same value","A Data category of Currency"],"ans":0,"exp":"Synonyms map business terms to model objects for Q&A and Copilot, and descriptions give extra context. This avoids duplicate measures.","why":["","Folders organize the Data pane but aren't used as names.","Duplicate measures create maintenance issues.","Data category doesn't map words to measures."],"ar":"أضف Synonyms ووصفًا للمقاييس حتى يفهمها Q&A وCopilot.","ref":[{"t":"Use Copilot with Power BI reports and semantic models","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/copilot-reports-overview"}]},{"id":"PL-DAX-001","d":"model","s":"dax","type":"single","diff":1,"tag":"Aggregation","q":"You need a measure that returns total revenue, where each Sales row has Quantity and UnitPrice columns and there's no Amount column. Which DAX expression is correct?","opts":["Revenue = SUMX(Sales, Sales[Quantity] * Sales[UnitPrice])","Revenue = SUM(Sales[Quantity]) * SUM(Sales[UnitPrice])","Revenue = SUM(Sales[Quantity] * Sales[UnitPrice])","Revenue = AVERAGEX(Sales, Sales[Quantity] * Sales[UnitPrice])"],"ans":0,"exp":"SUMX iterates the table, multiplies quantity by price for each row, then sums the results. Multiplying two totals gives a wrong number.","why":["","The product of two sums isn't the sum of products.","SUM accepts a single column, not an expression.","AVERAGEX returns an average, not a total."],"ar":"لجمع حاصل ضرب عمودين لكل صف استخدم SUMX.","ref":[{"t":"Statistical functions (DAX)","u":"https://learn.microsoft.com/en-us/dax/statistical-functions-dax"}]},{"id":"PL-DAX-002","d":"model","s":"dax","type":"single","diff":1,"tag":"Aggregation","q":"You need the number of different customers who bought something, from Sales[CustomerID]. Which function should you use?","opts":["DISTINCTCOUNT(Sales[CustomerID])","COUNT(Sales[CustomerID])","COUNTROWS(Sales)","COUNTA(Sales[CustomerID])"],"ans":0,"exp":"DISTINCTCOUNT counts unique values. COUNT and COUNTA count every non-blank row, and COUNTROWS counts every row.","why":["","COUNT counts all non-blank values, including repeats.","COUNTROWS counts sales rows, not customers.","COUNTA counts non-blank values including repeats."],"ar":"عدد العملاء المختلفين = DISTINCTCOUNT.","ref":[{"t":"Statistical functions (DAX)","u":"https://learn.microsoft.com/en-us/dax/statistical-functions-dax"}]},{"id":"PL-DAX-003","d":"model","s":"dax","type":"single","diff":2,"tag":"DIVIDE","q":"You need a Margin % measure that returns blank instead of an error when Revenue is zero. Which expression is best?","opts":["DIVIDE([Profit], [Revenue])","[Profit] / [Revenue]","IFERROR([Profit] / [Revenue], 0)","DIVIDE([Revenue], [Profit])"],"ans":0,"exp":"DIVIDE handles division by zero and returns blank (or an alternate result you provide). It's clearer and faster than wrapping division in IFERROR.","why":["","The / operator returns infinity or an error when dividing by zero.","IFERROR works but is slower and returns 0, which can show misleading values.","The operands are reversed."],"ar":"للقسمة الآمنة استخدم DIVIDE.","ref":[{"t":"DIVIDE function (DAX)","u":"https://learn.microsoft.com/en-us/dax/divide-function-dax"}]},{"id":"PL-DAX-004","d":"model","s":"dax","type":"single","diff":2,"tag":"CALCULATE","q":"Which measure returns sales for the Bikes category only, regardless of the category selected in a slicer?","opts":["CALCULATE([Sales], Product[Category] = \"Bikes\")","FILTER(Sales, RELATED(Product[Category]) = \"Bikes\")","[Sales] * (Product[Category] = \"Bikes\")","CALCULATE([Sales], KEEPFILTERS(Product[Category] = \"Bikes\"))"],"ans":0,"exp":"A Boolean filter in CALCULATE replaces any existing filter on Product[Category] with Bikes, so the result is Bikes sales even when the slicer selects something else.","why":["","FILTER returns a table, not a number.","You can't reference a column like that in a measure without row context.","KEEPFILTERS intersects with the slicer, so selecting Helmets would return blank."],"ar":"CALCULATE مع فلتر بسيط يستبدل فلتر العمود نفسه، وKEEPFILTERS يجعله تقاطعًا.","ref":[{"t":"CALCULATE function (DAX)","u":"https://learn.microsoft.com/en-us/dax/calculate-function-dax"}]},{"id":"PL-DAX-005","d":"model","s":"dax","type":"single","diff":2,"tag":"CALCULATE","q":"You need a measure that shows total sales for all categories on every row of a table visual grouped by category, to calculate each category's share. Which expression returns the grand total?","opts":["CALCULATE([Sales], REMOVEFILTERS(Product[Category]))","CALCULATE([Sales], Product[Category])","SUM(Sales[Amount])","CALCULATE([Sales], VALUES(Product[Category]))"],"ans":0,"exp":"REMOVEFILTERS (or ALL) removes the filter coming from the category row, so the measure returns the total across all categories. Divide [Sales] by it to get the share.","why":["","A column reference alone isn't a valid filter here.","SUM respects the category filter of each row.","VALUES keeps the current category filter."],"ar":"لإزالة فلتر عمود داخل CALCULATE استخدم REMOVEFILTERS أو ALL.","ref":[{"t":"CALCULATE function (DAX)","u":"https://learn.microsoft.com/en-us/dax/calculate-function-dax"}]},{"id":"PL-DAX-006","d":"model","s":"dax","type":"yesno","diff":3,"tag":"CALCULATE","q":"Consider this measure:<pre>Sales Red = CALCULATE ( [Sales], Product[Color] = \"Red\" )</pre>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["In a visual grouped by Product[Color], every row shows the sales of red products.","The measure still respects a slicer on Customer[Country].","Wrapping the filter in KEEPFILTERS would make non-red rows return blank."],"ans":[true,true,true],"exp":"The Boolean filter overrides the Color filter from the row, so every color row shows red sales. Filters on other columns, such as Country, stay. KEEPFILTERS intersects the new filter with the existing one, so only the Red row keeps a value.","why":["Yes. The Color filter from the row is replaced.","Yes. CALCULATE only replaces filters on the columns it filters.","Yes. The intersection of Blue and Red is empty."],"ar":"فلتر CALCULATE يستبدل فلتر نفس العمود فقط، وKEEPFILTERS يحوّله إلى تقاطع.","ref":[{"t":"CALCULATE function (DAX)","u":"https://learn.microsoft.com/en-us/dax/calculate-function-dax"}]},{"id":"PL-DAX-007","d":"model","s":"dax","type":"single","diff":1,"tag":"Time intelligence","q":"You need year-to-date sales that reset each January, using a marked Date table. Which measure is correct?","opts":["TOTALYTD([Sales], 'Date'[Date])","SUM(Sales[Amount])","CALCULATE([Sales], 'Date'[Year])","DATESYTD([Sales])"],"ans":0,"exp":"TOTALYTD evaluates the measure from the start of the year up to the last date in the current filter context. It's shorthand for CALCULATE([Sales], DATESYTD('Date'[Date])).","why":["","A plain sum doesn't accumulate.","A column reference alone isn't a valid filter.","DATESYTD takes a date column and returns a table of dates, not a measure."],"ar":"المجموع منذ بداية السنة: TOTALYTD أو CALCULATE مع DATESYTD.","ref":[{"t":"Time intelligence functions (DAX)","u":"https://learn.microsoft.com/en-us/dax/time-intelligence-functions-dax"}]},{"id":"PL-DAX-008","d":"model","s":"dax","type":"single","diff":2,"tag":"Time intelligence","q":"Your fiscal year ends on 30 June. Which measure returns fiscal year-to-date sales?","opts":["TOTALYTD([Sales], 'Date'[Date], \"06-30\")","TOTALYTD([Sales], 'Date'[Date])","TOTALQTD([Sales], 'Date'[Date])","DATEADD('Date'[Date], -6, MONTH)"],"ans":0,"exp":"TOTALYTD and DATESYTD accept a year-end date as text, such as \"06-30\", so the year-to-date resets on 1 July.","why":["","Without the year-end argument, the year resets on 1 January.","TOTALQTD is quarter to date.","DATEADD shifts dates and returns a table, not a measure."],"ar":"السنة المالية: مرر تاريخ نهاية السنة مثل \"06-30\" إلى TOTALYTD.","ref":[{"t":"Time intelligence functions (DAX)","u":"https://learn.microsoft.com/en-us/dax/time-intelligence-functions-dax"}]},{"id":"PL-DAX-009","d":"model","s":"dax","type":"single","diff":2,"tag":"Time intelligence","q":"You need sales for the same period last year to compare with current sales in any date grouping (month, quarter or year). Which measure should you use?","opts":["CALCULATE([Sales], SAMEPERIODLASTYEAR('Date'[Date]))","CALCULATE([Sales], PREVIOUSYEAR('Date'[Date]))","[Sales] - 365","CALCULATE([Sales], 'Date'[Year] = YEAR(TODAY()) - 1)"],"ans":0,"exp":"SAMEPERIODLASTYEAR shifts the current set of dates back by one year, so it works at month, quarter or year level.","why":["","PREVIOUSYEAR returns the entire previous year, not the matching period.","Subtracting 365 from sales is meaningless.","That hard-codes last calendar year and ignores the visual's grouping."],"ar":"للمقارنة بنفس الفترة من السنة الماضية استخدم SAMEPERIODLASTYEAR.","ref":[{"t":"Time intelligence functions (DAX)","u":"https://learn.microsoft.com/en-us/dax/time-intelligence-functions-dax"}]},{"id":"PL-DAX-010","d":"model","s":"dax","type":"single","diff":3,"tag":"Time intelligence","q":"You need a year-over-year growth % measure that returns blank when there are no prior year sales. Which expression is best?","opts":["VAR PY = CALCULATE([Sales], SAMEPERIODLASTYEAR('Date'[Date])) RETURN DIVIDE([Sales] - PY, PY)","([Sales] - [Sales]) / [Sales]","DIVIDE([Sales], CALCULATE([Sales], SAMEPERIODLASTYEAR('Date'[Date])))","[Sales] / CALCULATE([Sales], PREVIOUSYEAR('Date'[Date])) - 1"],"ans":0,"exp":"A variable stores the prior year value once. DIVIDE returns blank when the prior year is blank or zero, and the numerator is the change.","why":["","That always returns zero.","This is a ratio, not growth, and it's 100% when there's no change.","PREVIOUSYEAR returns the full year, and the / operator fails on zero."],"ar":"نسبة النمو: (الحالي - السابق) / السابق باستخدام DIVIDE ومتغير VAR.","ref":[{"t":"Time intelligence functions (DAX)","u":"https://learn.microsoft.com/en-us/dax/time-intelligence-functions-dax"},{"t":"DIVIDE function (DAX)","u":"https://learn.microsoft.com/en-us/dax/divide-function-dax"}]},{"id":"PL-DAX-011","d":"model","s":"dax","type":"single","diff":2,"tag":"Time intelligence","q":"You need a rolling 3-month sales measure that includes the current month. Which expression is correct?","opts":["CALCULATE([Sales], DATESINPERIOD('Date'[Date], MAX('Date'[Date]), -3, MONTH))","CALCULATE([Sales], DATEADD('Date'[Date], -3, MONTH))","CALCULATE([Sales], PREVIOUSMONTH('Date'[Date]))","TOTALMTD([Sales], 'Date'[Date]) * 3"],"ans":0,"exp":"DATESINPERIOD returns the dates from the last visible date back three months, covering a rolling window.","why":["","DATEADD shifts the period by three months instead of widening it.","PREVIOUSMONTH returns only the previous month.","Multiplying month-to-date by 3 is an estimate, not a rolling total."],"ar":"المجموع المتحرك لآخر 3 أشهر: DATESINPERIOD بقيمة -3 MONTH.","ref":[{"t":"Time intelligence functions (DAX)","u":"https://learn.microsoft.com/en-us/dax/time-intelligence-functions-dax"}]},{"id":"PL-DAX-012","d":"model","s":"dax","type":"single","diff":2,"tag":"Semi-additive","q":"An Inventory table stores the stock quantity per product for each day. Stock should be summed across products but not across dates; each month should show the stock on the last day of the month. Which measure is correct?","opts":["CLOSINGBALANCEMONTH(SUM(Inventory[Qty]), 'Date'[Date])","SUM(Inventory[Qty])","AVERAGE(Inventory[Qty])","TOTALMTD(SUM(Inventory[Qty]), 'Date'[Date])"],"ans":0,"exp":"Stock is semi-additive: it adds across products but not across time. CLOSINGBALANCEMONTH returns the value at the last date of the month.","why":["","SUM adds every day's stock, overstating the month.","An average isn't the closing balance.","TOTALMTD accumulates across days, which is wrong for balances."],"ar":"الأرصدة شبه تراكمية: استخدم CLOSINGBALANCEMONTH أو LASTDATE.","ref":[{"t":"CLOSINGBALANCEMONTH function (DAX)","u":"https://learn.microsoft.com/en-us/dax/closingbalancemonth-function-dax"}]},{"id":"PL-DAX-013","d":"model","s":"dax","type":"single","diff":3,"tag":"Semi-additive","q":"Account balances are loaded only on days when they change. A month's closing balance must use the last date that has a value, not the last calendar day. Which expression fits best?","opts":["CALCULATE(SUM(Balance[Amount]), LASTNONBLANK('Date'[Date], CALCULATE(SUM(Balance[Amount]))))","CALCULATE(SUM(Balance[Amount]), LASTDATE('Date'[Date]))","SUM(Balance[Amount])","MAX(Balance[Amount])"],"ans":0,"exp":"LASTNONBLANK finds the last date in the period where the expression isn't blank, so the balance comes from the latest day that has data.","why":["","LASTDATE uses the last calendar day, which may have no balance row.","SUM adds balances across days.","MAX returns the largest balance, not the latest."],"ar":"لو البيانات غير يومية استخدم LASTNONBLANK لآخر يوم فيه قيمة.","ref":[{"t":"LASTNONBLANK function (DAX)","u":"https://learn.microsoft.com/en-us/dax/lastnonblank-function-dax"}]},{"id":"PL-DAX-014","d":"model","s":"dax","type":"single","diff":1,"tag":"Quick measures","q":"A new analyst needs a running total measure but isn't comfortable writing DAX. What should they use?","opts":["Quick measures, choosing the Running total calculation","Performance Analyzer","Column from examples","A what-if parameter"],"ans":0,"exp":"Quick measures generate the DAX for common calculations such as running totals, year-to-date or percent of total from a dialog. The generated DAX can be reviewed and edited.","why":["","Performance Analyzer measures performance.","Column from examples is a Power Query feature.","What-if parameters create scenario inputs."],"ar":"Quick measures تكتب DAX جاهزًا لحسابات شائعة مثل Running total.","ref":[{"t":"Use quick measures for common calculations","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-quick-measures"}]},{"id":"PL-DAX-015","d":"model","s":"dax","type":"single","diff":2,"tag":"Statistics","q":"You need the middle value of order amounts, which is less affected by a few huge orders than the average. Which function should you use?","opts":["MEDIAN(Sales[Amount])","AVERAGE(Sales[Amount])","STDEV.P(Sales[Amount])","MAX(Sales[Amount])"],"ans":0,"exp":"MEDIAN returns the middle value of the sorted numbers, so outliers affect it far less than the mean.","why":["","Averages are pulled up by outliers.","Standard deviation measures spread, not the center.","MAX returns the largest value."],"ar":"القيمة الوسطى الأقل تأثرًا بالقيم الشاذة = MEDIAN.","ref":[{"t":"Statistical functions (DAX)","u":"https://learn.microsoft.com/en-us/dax/statistical-functions-dax"}]},{"id":"PL-DAX-016","d":"model","s":"dax","type":"multi","n":2,"diff":2,"tag":"Statistics","q":"Which two DAX functions are statistical functions that measure the spread of values? Each correct answer presents a complete solution. Select TWO.","opts":["STDEV.P","VAR.S","MEDIAN","RANKX","DISTINCTCOUNT"],"ans":[0,1],"exp":"Standard deviation and variance describe how spread out values are around the mean. MEDIAN describes the center, RANKX ranks items and DISTINCTCOUNT counts unique values.","why":["Correct.","Correct.","MEDIAN measures the center.","RANKX returns a rank.","DISTINCTCOUNT counts values."],"ar":"الانحراف المعياري والتباين يقيسان التشتت.","ref":[{"t":"Statistical functions (DAX)","u":"https://learn.microsoft.com/en-us/dax/statistical-functions-dax"}]},{"id":"PL-DAX-017","d":"model","s":"dax","type":"single","diff":2,"tag":"Calculation groups","q":"You have 20 base measures and need YTD, PY and YoY % versions of each. You want to avoid creating 60 more measures. What should you create?","opts":["A calculation group with YTD, PY and YoY % calculation items that use SELECTEDMEASURE()","60 quick measures","A field parameter","A calculated column for each version"],"ans":0,"exp":"Calculation items apply the same logic to whichever measure is in the visual through SELECTEDMEASURE(), so three items replace sixty measures.","why":["","That's the 60 measures you want to avoid.","Field parameters switch fields but don't apply time logic.","Calculated columns can't respond to filters like measures do."],"ar":"مجموعة حسابات Calculation group مع SELECTEDMEASURE تقلل عدد المقاييس المكررة.","ref":[{"t":"Create calculation groups","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/calculation-groups"},{"t":"SELECTEDMEASURE function (DAX)","u":"https://learn.microsoft.com/en-us/dax/selectedmeasure-function-dax"}]},{"id":"PL-DAX-018","d":"model","s":"dax","type":"yesno","diff":3,"tag":"Calculation groups","q":"You add your first calculation group in Model view of Power BI Desktop.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["Power BI requires the Discourage implicit measures property to be on.","Calculation items apply to columns dragged directly into a visual as implicit sums.","A calculation item can use a dynamic format string, for example to show YoY % as a percentage."],"ans":[true,false,true],"exp":"Creating a calculation group turns on Discourage implicit measures because calculation items only apply to explicit measures. Items can have dynamic format strings.","why":["Yes. You're prompted to turn it on.","No. Calculation items only work with explicit measures.","Yes. Turn on Dynamic format string on the item."],"ar":"Calculation groups تحتاج Discourage implicit measures، وتعمل على المقاييس الصريحة فقط، وتدعم dynamic format string.","ref":[{"t":"Create calculation groups","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/calculation-groups"}]},{"id":"PL-DAX-019","d":"model","s":"dax","type":"single","diff":2,"tag":"Calculated columns","q":"In the Sales table you need a column with the product's category from the related Product table (many-to-one relationship). Which expression should you use in the calculated column?","opts":["RELATED(Product[Category])","RELATEDTABLE(Product)","LOOKUPVALUE(Sales[ProductID], Product[Category])","VALUES(Product[Category])"],"ans":0,"exp":"RELATED follows a many-to-one relationship from the current row to the one side and returns a value.","why":["","RELATEDTABLE goes from the one side to the many side and returns a table.","The LOOKUPVALUE arguments are wrong and it's slower than RELATED when a relationship exists.","VALUES returns a table of values, not the row's value."],"ar":"لجلب قيمة من جدول الطرف الواحد إلى عمود محسوب استخدم RELATED.","ref":[{"t":"Use calculation options in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-calculations-options"}]},{"id":"PL-DAX-020","d":"model","s":"dax","type":"single","diff":2,"tag":"Visual calculations","q":"In a matrix of sales by month, you need a running total that only exists in this visual and doesn't add a measure to the shared model. What should you use?","opts":["A visual calculation: RUNNINGSUM([Sales])","A quick measure","A calculated column with RUNNINGSUM","A calculation group"],"ans":0,"exp":"Visual calculations are stored on the visual, not in the model. RUNNINGSUM works only in visual calculations and follows the visual's axis.","why":["","A quick measure adds a measure to the model.","RUNNINGSUM can't be used in calculated columns.","Calculation groups are model objects."],"ar":"حساب خاص بـ visual واحد بدون تعديل النموذج: Visual calculation مثل RUNNINGSUM.","ref":[{"t":"Visual calculations","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-visual-calculations-overview"}]},{"id":"PL-DAX-021","d":"model","s":"dax","type":"yesno","diff":3,"tag":"Visual calculations","q":"You're using visual calculations.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["MOVINGAVERAGE([Sales], 3) in a visual calculation averages the current row and the two previous rows by default.","Visual calculation results are included when a reader exports underlying data.","A visual calculation can be hidden in the visual while still being used by other visual calculations."],"ans":[true,false,true],"exp":"MOVINGAVERAGE includes the current row by default. Exports of underlying data don't include visual calculation results. You can hide a helper visual calculation and reference it from others or from conditional formatting.","why":["Yes. includeCurrent defaults to TRUE.","No. Underlying data exports don't include visual calculations.","Yes. Hidden visual calculations are common helpers."],"ar":"MOVINGAVERAGE يشمل الصف الحالي افتراضيًا، والتصدير لا يشمل visual calculations، ويمكن إخفاؤها واستخدامها.","ref":[{"t":"Visual calculations","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-visual-calculations-overview"},{"t":"Export data from a Power BI visualization","u":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualization-export-data"}]},{"id":"PL-DAX-022","d":"model","s":"dax","type":"single","diff":3,"tag":"Variables","q":"A measure calculates [Sales] three times inside an IF. It's slow and hard to read. What's the best improvement?","opts":["Store [Sales] in a VAR and reference the variable","Replace IF with SWITCH","Convert the measure to a calculated column","Wrap each [Sales] in CALCULATE"],"ans":0,"exp":"Variables are evaluated once and reused, which improves both performance and readability.","why":["","SWITCH changes structure but still evaluates [Sales] several times.","A calculated column wouldn't respond to filters.","Extra CALCULATE calls add context transitions and don't reduce work."],"ar":"استخدم VAR لتخزين قيمة تتكرر في المقياس.","ref":[{"t":"CALCULATE function (DAX)","u":"https://learn.microsoft.com/en-us/dax/calculate-function-dax"}]},{"id":"PL-DAX-023","d":"model","s":"dax","type":"single","diff":2,"tag":"Iterators","q":"You need the rank of each product by sales, where 1 is the best seller, shown in a table visual by product. Which measure is correct?","opts":["RANKX(ALL(Product[ProductName]), [Sales])","RANKX(Product, Product[ProductName])","RANK.EQ([Sales], Sales[Amount])","TOPN(1, Product, [Sales])"],"ans":0,"exp":"RANKX evaluates [Sales] for every product in the ALL table and ranks the current product's value among them, descending by default.","why":["","Ranking by the name column ranks alphabetically, not by sales.","RANK.EQ ranks a value in a column, not a measure across products.","TOPN returns a table, not a rank."],"ar":"لترتيب المنتجات حسب المبيعات: RANKX مع ALL.","ref":[{"t":"Statistical functions (DAX)","u":"https://learn.microsoft.com/en-us/dax/statistical-functions-dax"}]},{"id":"PL-DAX-024","d":"model","s":"dax","type":"single","diff":2,"tag":"Filter functions","q":"A card must show sales for the product selected in a single-select slicer, and show \"Select one product\" otherwise. Which function detects a single selection?","opts":["HASONEVALUE(Product[ProductName])","ISBLANK(Product[ProductName])","ISFILTERED(Sales)","COUNTROWS(ALL(Product))"],"ans":0,"exp":"HASONEVALUE returns TRUE when exactly one value is in the filter context for the column, so you can switch between the value and a prompt with IF.","why":["","ISBLANK checks a value, not the selection.","ISFILTERED only tells you a filter exists, not that one value remains.","ALL removes filters and counts every product."],"ar":"للتحقق من اختيار قيمة واحدة استخدم HASONEVALUE أو SELECTEDVALUE.","ref":[{"t":"CALCULATE function (DAX)","u":"https://learn.microsoft.com/en-us/dax/calculate-function-dax"}]},{"id":"PL-DAX-025","d":"model","s":"dax","type":"order","diff":3,"tag":"Time intelligence","q":"You need a YoY % measure that works with any date grouping. Which three measures should you create in sequence?","opts":["Sales = SUM(Sales[Amount])","Sales PY = CALCULATE([Sales], SAMEPERIODLASTYEAR('Date'[Date]))","Sales YoY % = DIVIDE([Sales] - [Sales PY], [Sales PY])","Sales PY = [Sales] - 365","Sales YoY % = [Sales] / [Sales]"],"ans":[0,1,2],"exp":"Build the base measure first, then the prior-year measure that reuses it, and finally the growth measure that divides the change by the prior year safely.","why":["Step 1.","Step 2.","Step 3.","Subtracting 365 from a sales total doesn't shift time.","That always returns 1."],"ar":"ابنِ المقاييس بالتدرج: الأساس ثم السنة السابقة ثم النسبة.","ref":[{"t":"Time intelligence functions (DAX)","u":"https://learn.microsoft.com/en-us/dax/time-intelligence-functions-dax"},{"t":"DIVIDE function (DAX)","u":"https://learn.microsoft.com/en-us/dax/divide-function-dax"}]},{"id":"PL-PRF-001","d":"model","s":"perf","type":"single","diff":1,"tag":"Performance Analyzer","q":"A report page takes 12 seconds to load. You need to find which visual is slow and whether the time is spent on the DAX query or on rendering. What should you use?","opts":["Performance Analyzer in Power BI Desktop","Column profile in Power Query","Query dependencies view","The Selection pane"],"ans":0,"exp":"Performance Analyzer records each visual's duration split into DAX query, Visual display and Other, so you can see which visual and which part is slow.","why":["","Column profile shows data statistics, not report performance.","Query dependencies show query lineage.","The Selection pane manages visibility and layering."],"ar":"لمعرفة الـ visual البطيء وسبب البطء استخدم Performance Analyzer.","ref":[{"t":"Use Performance Analyzer to examine report element performance","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-performance-analyzer"}]},{"id":"PL-PRF-002","d":"model","s":"perf","type":"single","diff":2,"tag":"Performance Analyzer","q":"Performance Analyzer shows that a table visual spends 9 seconds in DAX query. You want to test changes to its measure without clicking through the report. What should you do?","opts":["Copy the query from Performance Analyzer and run it in DAX query view","Export the visual to Excel","Change the page size","Turn on Auto date/time"],"ans":0,"exp":"Performance Analyzer can copy the exact DAX query a visual sends. DAX query view in Desktop runs it, shows timings and lets you define and test alternative measures.","why":["","Exporting data doesn't help tune the query.","Page size doesn't change the query.","Auto date/time adds hidden tables and doesn't help."],"ar":"انسخ استعلام الـ visual من Performance Analyzer وجربه في DAX query view.","ref":[{"t":"Use Performance Analyzer to examine report element performance","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-performance-analyzer"},{"t":"Work with DAX query view","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/dax-query-view"}]},{"id":"PL-PRF-003","d":"model","s":"perf","type":"yesno","diff":2,"tag":"Performance Analyzer","q":"You're reading Performance Analyzer results.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["A large Visual display time with a small DAX query time points to a visual that renders too many points or elements.","The Other category includes time a visual spends waiting for other visuals to finish.","Performance Analyzer results in Desktop measure how the report runs for every user in the service."],"ans":[true,true,false],"exp":"Visual display is rendering time, often high for visuals with many data points or custom visuals. Other includes waiting and background work. Desktop timings depend on your machine and data, so they're indicators, not service measurements.","why":["Yes.","Yes. Many visuals on a page make each one wait longer.","No. Service performance also depends on capacity, network and concurrent users."],"ar":"وقت Visual display الكبير يعني عرضًا ثقيلًا، وOther يشمل الانتظار، ونتائج Desktop مؤشرات فقط.","ref":[{"t":"Use Performance Analyzer to examine report element performance","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-performance-analyzer"}]},{"id":"PL-PRF-004","d":"model","s":"perf","type":"single","diff":1,"tag":"Reduce data","q":"Your Import model loads a Sales table with 10 years of history, but reports only cover the last 3 years. What's the simplest way to reduce model size and refresh time?","opts":["Filter the rows in Power Query to the last 3 years","Hide the old rows with a report-level filter","Create a measure that ignores old years","Change the table to Dual storage mode"],"ans":0,"exp":"Filtering rows in Power Query stops unneeded rows from loading at all. Report filters and measures still leave every row in memory.","why":["","Filtered rows are still loaded.","A measure doesn't reduce the data loaded.","Dual keeps an imported copy anyway."],"ar":"أبسط تقليل للحجم: فلترة الصفوف غير المطلوبة في Power Query.","ref":[{"t":"Data reduction techniques for Import modeling","u":"https://learn.microsoft.com/en-us/power-bi/guidance/import-modeling-data-reduction"}]},{"id":"PL-PRF-005","d":"model","s":"perf","type":"multi","n":2,"diff":2,"tag":"Reduce data","q":"Which two actions reduce the size of an Import semantic model? Each correct answer presents a complete solution. Select TWO.","opts":["Remove columns that no report or measure uses","Reduce the granularity of the fact table by grouping to daily totals when transaction detail isn't needed","Hide unused columns","Add more calculated columns","Turn on Auto date/time"],"ans":[0,1],"exp":"Removing columns and summarizing to a coarser grain both reduce the amount of data stored. Hiding columns doesn't remove them, and calculated columns and auto date tables add size.","why":["Correct.","Correct.","Hidden columns are still stored.","Calculated columns add stored data.","Auto date/time adds hidden tables."],"ar":"حذف الأعمدة وتقليل مستوى التفصيل يصغّر النموذج، أما الإخفاء فلا.","ref":[{"t":"Data reduction techniques for Import modeling","u":"https://learn.microsoft.com/en-us/power-bi/guidance/import-modeling-data-reduction"}]},{"id":"PL-PRF-006","d":"model","s":"perf","type":"single","diff":2,"tag":"Reduce data","q":"A fact table has a DateTime column with seconds, making it the largest column in the model. Reports only need dates and hours. What should you do?","opts":["Split it into a Date column and an Hour column (or round it) in Power Query","Change it to Text","Hide the column","Create a calculated column that extracts the date"],"ans":0,"exp":"High-cardinality columns compress poorly. Splitting a timestamp into date and a small time part greatly reduces the number of unique values and memory.","why":["","Text is still high cardinality and loses date features.","Hidden columns still take memory.","A calculated column adds data and keeps the original."],"ar":"قلل عدد القيم الفريدة: افصل التاريخ عن الوقت أو قرّب الوقت.","ref":[{"t":"Data reduction techniques for Import modeling","u":"https://learn.microsoft.com/en-us/power-bi/guidance/import-modeling-data-reduction"}]},{"id":"PL-PRF-007","d":"model","s":"perf","type":"single","diff":2,"tag":"Relationships","q":"A visual is slow. The model relates two large fact tables through a many-to-many relationship with bi-directional filtering. What change most likely improves performance?","opts":["Replace it with shared dimension tables in a star schema with single-direction relationships","Add more bi-directional relationships","Turn off query folding","Add a calculated column to each fact table"],"ans":0,"exp":"Star schemas with single-direction one-to-many relationships are what the engine is optimized for. Fact-to-fact many-to-many relationships with bi-directional filters are expensive and ambiguous.","why":["","More bi-directional filters add cost.","Folding affects refresh, not this visual.","Calculated columns increase size and don't fix the relationship."],"ar":"علاقات many-to-many ثنائية الاتجاه بين جداول الحقائق بطيئة، استبدلها بـ star schema.","ref":[{"t":"Understand star schema and the importance for Power BI","u":"https://learn.microsoft.com/en-us/power-bi/guidance/star-schema"},{"t":"Bi-directional relationship guidance","u":"https://learn.microsoft.com/en-us/power-bi/guidance/relationships-bidirectional-filtering"}]},{"id":"PL-PRF-008","d":"model","s":"perf","type":"single","diff":3,"tag":"Measures","q":"A measure uses FILTER(Sales, Sales[Color] = \"Red\") inside CALCULATE and is slow on a 50 million row table. What's the better expression?","opts":["CALCULATE([Sales], Product[Color] = \"Red\") using the Product dimension column","CALCULATE([Sales], FILTER(ALL(Sales), Sales[Color] = \"Red\"))","SUMX(FILTER(Sales, Sales[Color] = \"Red\"), Sales[Amount]) * 2","A calculated column that multiplies Amount by 1"],"ans":0,"exp":"Filtering a whole fact table with FILTER iterates every row. A simple column filter on a dimension column lets the engine filter efficiently and reuse the relationship.","why":["","FILTER(ALL(Sales)) iterates the full table and also removes other filters.","That still iterates the table and doubles the result.","That does nothing useful."],"ar":"تجنب FILTER على جدول حقائق كامل، واستخدم فلتر عمود بسيط على البعد.","ref":[{"t":"CALCULATE function (DAX)","u":"https://learn.microsoft.com/en-us/dax/calculate-function-dax"}]},{"id":"PL-PRF-009","d":"model","s":"perf","type":"single","diff":1,"tag":"Visuals","q":"A report page has 35 visuals and loads slowly. Most are small cards. What's the recommended design change?","opts":["Reduce the number of visuals, for example by combining cards into one multi-row card or table, or moving detail to other pages","Add more slicers","Use a larger page size","Turn on automatic page refresh"],"ans":0,"exp":"Every visual sends its own query. Fewer, well-chosen visuals per page load faster and are easier to read.","why":["","More slicers add more queries.","Page size doesn't reduce the queries.","Automatic page refresh adds even more queries."],"ar":"كل visual يرسل استعلامًا، قلل عددها لتسريع الصفحة.","ref":[{"t":"Use Performance Analyzer to examine report element performance","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-performance-analyzer"}]},{"id":"PL-PRF-010","d":"model","s":"perf","type":"single","diff":2,"tag":"DAX query view","q":"What can you do in DAX query view in Power BI Desktop?","opts":["Write and run DAX queries with EVALUATE, and define measures in the query to test them before adding them to the model","Edit Power Query M steps","Change relationship cardinality","Configure row-level security membership in the service"],"ans":0,"exp":"DAX query view runs DAX queries against the model, shows results and lets you DEFINE MEASURE to test logic. You can then update the model with the tested measure.","why":["","M steps are edited in Power Query Editor.","Relationships are edited in Model view.","RLS membership is managed in the service."],"ar":"DAX query view لتشغيل استعلامات EVALUATE وتجربة المقاييس.","ref":[{"t":"Work with DAX query view","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/dax-query-view"}]},{"id":"PL-PRF-011","d":"model","s":"perf","type":"yesno","diff":2,"tag":"Reduce data","q":"You're optimizing an Import model.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["Columns with fewer distinct values compress better in memory.","Changing a numeric key column from Text to Whole Number can reduce memory.","Incremental refresh reduces the number of rows stored in the model."],"ans":[true,true,false],"exp":"The VertiPaq engine compresses by distinct values, so low cardinality helps and integers store efficiently. Incremental refresh reduces the data refreshed each time, not the history kept in the model.","why":["Yes.","Yes. Integer keys are usually smaller than text keys.","No. It refreshes only recent partitions but keeps the full history."],"ar":"القيم الفريدة الأقل تضغط أفضل، والأرقام أصغر من النصوص، وincremental refresh يسرّع التحديث ولا يقلل التاريخ المخزن.","ref":[{"t":"Data reduction techniques for Import modeling","u":"https://learn.microsoft.com/en-us/power-bi/guidance/import-modeling-data-reduction"},{"t":"Incremental refresh and real-time data for semantic models","u":"https://learn.microsoft.com/en-us/power-bi/connect-data/incremental-refresh-overview"}]},{"id":"PL-PRF-012","d":"model","s":"perf","type":"single","diff":2,"tag":"Reduce data","q":"Your model has a Customer table with 3 million rows, but the Sales table only references 200,000 of those customers. Reports never show customers without sales. What's a good optimization?","opts":["Filter the Customer query to customers that appear in Sales (for example with an inner join or a list of keys)","Hide the Customer table","Mark Customer as a date table","Set Customer to DirectQuery"],"ans":0,"exp":"Loading only dimension rows that the fact table uses reduces memory and speeds up filtering. An inner merge or a filter on a list of used keys does this in Power Query.","why":["","Hidden tables are still loaded.","Customer isn't a date table.","DirectQuery on a dimension usually slows visuals down."],"ar":"لا تحمّل صفوف أبعاد غير مستخدمة في جدول الحقائق.","ref":[{"t":"Data reduction techniques for Import modeling","u":"https://learn.microsoft.com/en-us/power-bi/guidance/import-modeling-data-reduction"}]},{"id":"PL-REP-001","d":"viz","s":"reports","type":"single","diff":1,"tag":"Choose a visual","q":"You need to show how monthly revenue changed over the past 24 months. Which visual is most appropriate?","opts":["Line chart","Pie chart","Table","Card"],"ans":0,"exp":"Line charts show trends over continuous time clearly.","why":["","Pie charts compare parts of a whole at one point in time.","Tables are for exact values, not trends.","Cards show a single number."],"ar":"للاتجاه عبر الزمن استخدم Line chart.","ref":[{"t":"Visualization types in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualization-types-for-reports-and-q-and-a"}]},{"id":"PL-REP-002","d":"viz","s":"reports","type":"single","diff":1,"tag":"Choose a visual","q":"You need to show how a starting profit becomes a final profit through positive and negative contributions such as price, volume and costs. Which visual fits best?","opts":["Waterfall chart","Funnel","Scatter chart","Treemap"],"ans":0,"exp":"Waterfall charts show a running total as values are added or subtracted, which suits bridge or variance analysis.","why":["","Funnels show stages of a process.","Scatter charts show relationships between two measures.","Treemaps show part-to-whole with rectangles."],"ar":"تحليل الفروقات والجسور: Waterfall chart.","ref":[{"t":"Visualization types in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualization-types-for-reports-and-q-and-a"}]},{"id":"PL-REP-003","d":"viz","s":"reports","type":"single","diff":2,"tag":"Choose a visual","q":"You need to compare actual sales against a target for a single KPI, showing the value, the goal and the trend over time in one visual. Which visual should you use?","opts":["KPI visual","Gauge without a target","Stacked column chart","Slicer"],"ans":0,"exp":"The KPI visual shows an indicator value, a target (goal) and a trend axis with color coding for whether the goal is met.","why":["","A gauge can show a target but not the trend over time.","Stacked columns don't highlight a single KPI against a goal.","Slicers filter data."],"ar":"KPI visual يعرض القيمة والهدف والاتجاه معًا.","ref":[{"t":"Visualization types in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualization-types-for-reports-and-q-and-a"}]},{"id":"PL-REP-004","d":"viz","s":"reports","type":"single","diff":1,"tag":"Themes","q":"Your company wants every new report to use the brand colors and fonts without formatting each visual. What should you do?","opts":["Create and apply a report theme JSON file","Format each visual and copy the format with Format painter","Set colors with conditional formatting","Use a bookmark"],"ans":0,"exp":"A theme JSON defines data colors, text styles and default visual formatting for the whole report. Applying it styles every visual at once.","why":["","Format painter works one visual at a time.","Conditional formatting depends on data values.","Bookmarks capture report states."],"ar":"لتوحيد ألوان وخطوط التقارير استخدم theme JSON.","ref":[{"t":"Use report themes in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-report-themes"}]},{"id":"PL-REP-005","d":"viz","s":"reports","type":"single","diff":2,"tag":"Conditional formatting","q":"In a table visual, the Margin % column must show a red background below 10%, yellow from 10% to 20%, and green above 20%. What should you configure?","opts":["Conditional formatting on the background color, formatted by Rules","A theme with three data colors","Three bookmarks","A gradient color scale with default settings"],"ans":0,"exp":"Rules-based conditional formatting sets exact thresholds and colors. Gradients blend colors and don't give sharp bands.","why":["","Theme colors aren't tied to values.","Bookmarks don't color cells.","A default gradient blends colors instead of fixed bands."],"ar":"ألوان بحدود دقيقة: Conditional formatting بـ Rules.","ref":[{"t":"Apply conditional table formatting in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-conditional-table-formatting"}]},{"id":"PL-REP-006","d":"viz","s":"reports","type":"single","diff":2,"tag":"Conditional formatting","q":"A column chart must color each bar with a hex color stored in a measure, for example green when above target and red when below. What should you use?","opts":["Conditional formatting on the data colors with Format style: Field value, pointing to the color measure","Rules with 20 conditions","A theme file","A tooltip page"],"ans":0,"exp":"Field value formatting reads a color (hex code or color name) from a measure or column, so the logic lives in DAX and is easy to maintain.","why":["","Many rules are hard to maintain and can't compare to a target measure easily.","Theme colors don't depend on values.","Tooltips don't color bars."],"ar":"لون يُحسب في DAX: Conditional formatting بخيار Field value.","ref":[{"t":"Apply conditional table formatting in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-conditional-table-formatting"}]},{"id":"PL-REP-007","d":"viz","s":"reports","type":"single","diff":1,"tag":"Slicers","q":"Users need to pick a date range with a start and end date on the report page. Which slicer style fits best?","opts":["A date slicer set to Between","A list slicer with every date","A dropdown slicer with single select","A relative date slicer set to Next 3 months"],"ans":0,"exp":"A Between date slicer shows a range with start and end inputs and a timeline slider.","why":["","Listing every date is hard to use.","Single select allows only one date.","Relative date shows rolling periods, not a custom range."],"ar":"لاختيار فترة من-إلى استخدم date slicer بنمط Between.","ref":[{"t":"Slicers in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualization-slicers"}]},{"id":"PL-REP-008","d":"viz","s":"reports","type":"single","diff":2,"tag":"Filters","q":"A filter must apply to every page of a report, but report readers must not be able to change it. What should you do?","opts":["Add it to Filters on all pages and lock it","Add a slicer to each page","Add it to Filters on this visual","Hide the Filters pane on one page only"],"ans":0,"exp":"Report-level filters apply to all pages. Locking a filter keeps it visible but stops readers from changing it, and hiding it keeps it invisible.","why":["","Slicers can be changed by readers.","Visual-level filters affect one visual.","The filter still needs to be report level."],"ar":"فلتر على كل الصفحات ولا يتغير: Filters on all pages ثم Lock.","ref":[{"t":"Change settings for Power BI reports","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/power-bi-report-settings"}]},{"id":"PL-REP-009","d":"viz","s":"reports","type":"yesno","diff":2,"tag":"Copilot","q":"You plan to use Copilot in Power BI to create a report page and a narrative visual.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["The report must be in a workspace on a paid Fabric capacity or Power BI Premium (P1 or higher).","Copilot is supported on Fabric trial capacities.","To add a narrative visual with Copilot, you need edit access to the report or Build access to the semantic model."],"ans":[true,false,true],"exp":"Copilot requires a paid Fabric capacity or Premium P1+, and trial SKUs aren't supported. Adding a narrative visual is an authoring action, so it needs edit access to the workspace or report or Build on the model.","why":["Yes.","No. Only paid SKUs support Copilot.","Yes. Readers can still summarize in the Copilot pane."],"ar":"Copilot يحتاج Fabric capacity مدفوعة أو Premium، ولا يعمل على trial، وإضافة narrative visual تحتاج صلاحية تعديل.","ref":[{"t":"Copilot for Power BI overview","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/copilot-introduction"},{"t":"Create a narrative visual with Copilot for Power BI","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/copilot-create-narrative"}]},{"id":"PL-REP-010","d":"viz","s":"reports","type":"single","diff":2,"tag":"Copilot","q":"You want Copilot to propose an outline of report pages based on your semantic model before you build anything. Which Copilot capability should you use?","opts":["Suggest content for a new report page","Create a narrative visual","Write DAX queries","Add measure descriptions"],"ans":0,"exp":"Suggest content evaluates the data and returns an outline of suggested pages you can choose to create.","why":["","A narrative summarizes existing visuals.","DAX queries return data, not a report outline.","Measure descriptions document the model."],"ar":"لاقتراح صفحات التقرير استخدم Suggest content في Copilot.","ref":[{"t":"Use Copilot with Power BI reports and semantic models","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/copilot-reports-overview"},{"t":"Create and edit Power BI reports with Copilot","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/copilot-create-reports"}]},{"id":"PL-REP-011","d":"viz","s":"reports","type":"single","diff":2,"tag":"Copilot","q":"A narrative visual created with Copilot summarizes the visuals on a page. After users change a slicer, the summary still shows the old numbers. What's expected behavior?","opts":["Users must refresh the narrative visual to regenerate the summary after filters change","The visual can't read slicers","The visual only summarizes the semantic model, not the page","Copilot narratives never update"],"ans":0,"exp":"The narrative is generated from the visuals on the page. When the page is filtered or the data changes, users refresh the narrative to get an updated summary.","why":["","The summary reflects the page's filters after it's refreshed.","It summarizes what's on the report canvas.","It updates when refreshed."],"ar":"بعد تغيير الفلاتر يجب تحديث الـ narrative visual ليعكس الأرقام الجديدة.","ref":[{"t":"Create a narrative visual with Copilot for Power BI","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/copilot-create-narrative"}]},{"id":"PL-REP-012","d":"viz","s":"reports","type":"single","diff":2,"tag":"Paginated reports","q":"Finance needs a 40-page invoice listing that prints exactly, with a header on every page and every row shown, exported to PDF. What should you build?","opts":["A paginated report in Power BI Report Builder","A Power BI report with a table visual","A dashboard","A mobile layout"],"ans":0,"exp":"Paginated reports are designed for pixel-perfect, printable output that spans pages and shows all rows, with repeated headers and exports to PDF.","why":["","Interactive reports scroll inside visuals and aren't designed for exact multi-page printing.","Dashboards are single-page tile canvases.","Mobile layouts optimize for phones."],"ar":"للطباعة الدقيقة متعددة الصفحات استخدم Paginated report.","ref":[{"t":"What are paginated reports in Power BI?","u":"https://learn.microsoft.com/en-us/power-bi/paginated-reports/paginated-reports-report-builder-power-bi"}]},{"id":"PL-REP-013","d":"viz","s":"reports","type":"multi","n":2,"diff":2,"tag":"Paginated reports","q":"Which two scenarios are better served by a paginated report than an interactive Power BI report? Each correct answer presents a complete solution. Select TWO.","opts":["A regulatory statement that must print on fixed-size pages with exact layout","A detailed list of 50,000 transactions to export to Excel or PDF","An executive dashboard for exploring trends with drill-down","A mobile-first sales overview","A report that relies on cross-highlighting between charts"],"ans":[0,1],"exp":"Paginated reports excel at fixed layouts and long detailed lists for print or export. Exploration, cross-highlighting and mobile views are strengths of interactive reports.","why":["Correct.","Correct.","Interactive reports suit exploration.","Mobile layouts are interactive report features.","Cross-highlighting is an interactive feature."],"ar":"الـ paginated للطباعة والقوائم الطويلة، والتفاعلية للاستكشاف.","ref":[{"t":"What are paginated reports in Power BI?","u":"https://learn.microsoft.com/en-us/power-bi/paginated-reports/paginated-reports-report-builder-power-bi"}]},{"id":"PL-REP-014","d":"viz","s":"reports","type":"single","diff":2,"tag":"Page setup","q":"You're building a report page to use as a tooltip for another page. What should you set on the tooltip page?","opts":["Page information: Allow use as tooltip, and set Canvas settings to the Tooltip size","Page visibility: Hidden only","A bookmark","Mobile layout"],"ans":0,"exp":"A report page tooltip is a page with Allow use as tooltip turned on, usually sized as Tooltip. Visuals then point to it in their Tooltips settings.","why":["","Hiding the page doesn't make it a tooltip.","Bookmarks capture states.","Mobile layout is for phones."],"ar":"صفحة Tooltip: فعّل Allow use as tooltip واختر مقاس Tooltip.","ref":[{"t":"Create tooltips based on report pages","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-tooltips"}]},{"id":"PL-REP-015","d":"viz","s":"reports","type":"single","diff":1,"tag":"Page setup","q":"A report page should be taller than a screen so users can scroll down to more visuals. What should you change?","opts":["Canvas settings: set a custom page height","Page view: Fit to width only","The theme","The mobile layout"],"ans":0,"exp":"Custom page sizes in Canvas settings allow longer pages. Fit to width controls how the page scales, not its height.","why":["","Fit to width scales the page but doesn't add space.","Themes don't set page size.","Mobile layout doesn't change the desktop page."],"ar":"لصفحة أطول غيّر ارتفاع الصفحة من Canvas settings.","ref":[{"t":"Change settings for Power BI reports","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/power-bi-report-settings"}]},{"id":"PL-REP-016","d":"viz","s":"reports","type":"single","diff":2,"tag":"Visual calculations","q":"In a matrix by Product and Month, you need each month's sales as a percentage of the product's total across months, without adding a model measure. What should you use?","opts":["A visual calculation using COLLAPSE, for example DIVIDE([Sales], COLLAPSE([Sales], COLUMNS))","A calculated column","A calculation group","A what-if parameter"],"ans":0,"exp":"Visual calculations can reference parent levels in the visual matrix. COLLAPSE moves to the parent level (the product total across columns) so the share can be calculated on the visual only.","why":["","Calculated columns can't respond to the visual layout.","Calculation groups are model objects.","What-if parameters are scenario inputs."],"ar":"نسبة من إجمالي المستوى الأعلى داخل visual واحد: visual calculation مع COLLAPSE.","ref":[{"t":"Visual calculations","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-visual-calculations-overview"}]},{"id":"PL-REP-017","d":"viz","s":"reports","type":"yesno","diff":2,"tag":"Filters","q":"You're reviewing filters in a report.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["A Top N filter on a visual can show the top 5 products by sales.","Filters on this page affect other pages.","A relative date filter can show the last 12 complete months."],"ans":[true,false,true],"exp":"Top N is a visual or page filter type. Page filters stay on their page. Relative date filters support rolling periods such as last 12 calendar months.","why":["Yes.","No. Use Filters on all pages for report scope.","Yes. Choose In the last 12 calendar months."],"ar":"Top N لأعلى القيم، وفلاتر الصفحة لا تؤثر على غيرها، وRelative date للفترات المتحركة.","ref":[{"t":"Slicers in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualization-slicers"}]},{"id":"PL-REP-018","d":"viz","s":"reports","type":"single","diff":2,"tag":"Field parameters","q":"Users want to switch a chart's axis between Category, Region and Channel with a slicer, without separate charts. What should you create?","opts":["A field parameter with Category, Region and Channel","A what-if parameter","Three bookmarks","A calculation group"],"ans":0,"exp":"Field parameters create a slicer that swaps the fields used in a visual, such as the axis or values.","why":["","What-if parameters create numeric inputs.","Bookmarks work but need three copies and buttons, which is harder to maintain.","Calculation groups change measures, not axis fields."],"ar":"لتبديل محور الرسم بـ slicer استخدم Field parameter.","ref":[{"t":"Let report readers use field parameters to change visuals","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/power-bi-field-parameters"}]},{"id":"PL-REP-019","d":"viz","s":"reports","type":"single","diff":1,"tag":"Formatting","q":"A bar chart shows long product names that are cut off. What's the simplest formatting fix?","opts":["Use a bar chart (horizontal) and increase the Y-axis width or enable word wrap","Change to a pie chart","Remove the axis","Turn on data labels only"],"ans":0,"exp":"Horizontal bar charts give category labels more room, and axis settings let you widen or wrap labels.","why":["","Pie charts with many categories are hard to read.","Removing the axis hides the names.","Data labels show values, not names."],"ar":"للأسماء الطويلة استخدم Bar chart أفقي ووسّع المحور.","ref":[{"t":"Visualization types in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualization-types-for-reports-and-q-and-a"}]},{"id":"PL-REP-020","d":"viz","s":"reports","type":"single","diff":2,"tag":"Choose a visual","q":"You need to show the relationship between marketing spend and revenue for 200 stores and spot stores that don't follow the pattern. Which visual should you use?","opts":["Scatter chart","Donut chart","Ribbon chart","Card"],"ans":0,"exp":"A scatter chart plots two measures against each other for each item, making correlation and outliers easy to see.","why":["","Donuts show part-to-whole.","Ribbon charts show rank changes over time.","Cards show one value."],"ar":"العلاقة بين مقياسين: Scatter chart.","ref":[{"t":"Visualization types in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualization-types-for-reports-and-q-and-a"}]},{"id":"PL-REP-021","d":"viz","s":"reports","type":"single","diff":2,"tag":"Report settings","q":"Report readers should be able to export only the summarized data that a visual shows, never the underlying rows. What should you configure?","opts":["Report settings: Export data set to Allow end users to export only summarized data","Hide the columns in the model","A visual-level filter","Row-level security"],"ans":0,"exp":"The Export data report setting controls whether readers can export summarized and underlying data, only summarized data, or nothing. Tenant settings can restrict it further.","why":["","Hidden columns can still be exported as underlying data in some cases.","Filters don't control export options.","RLS limits rows by user, not export type."],"ar":"للتحكم في التصدير استخدم إعداد Export data في Report settings.","ref":[{"t":"Change settings for Power BI reports","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/power-bi-report-settings"},{"t":"Export data from a Power BI visualization","u":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualization-export-data"}]},{"id":"PL-REP-022","d":"viz","s":"reports","type":"single","diff":2,"tag":"Automatic page refresh","q":"A DirectQuery report on a production database must update its visuals every 5 minutes while the page is open. What should you configure?","opts":["Automatic page refresh on the page with a fixed interval of 5 minutes","Scheduled refresh every 5 minutes","A dashboard tile refresh","Incremental refresh"],"ans":0,"exp":"Automatic page refresh re-queries DirectQuery sources at a fixed interval while the page is open. Scheduled refresh applies to imported data and can't run every 5 minutes.","why":["","Scheduled refresh is for Import and allows at most 8 or 48 refreshes per day.","Dashboard tile cache refresh doesn't update the report page.","Incremental refresh partitions imported data."],"ar":"تحديث صفحة DirectQuery كل عدة دقائق: Automatic page refresh.","ref":[{"t":"Automatic page refresh in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-automatic-page-refresh"}]},{"id":"PL-USE-001","d":"viz","s":"usability","type":"single","diff":1,"tag":"Bookmarks","q":"You want a button that switches a page between a chart view and a table view. What should you use?","opts":["Two bookmarks that show and hide the visuals, and buttons that trigger them","Two report pages with drillthrough","A field parameter","Edit interactions"],"ans":0,"exp":"Bookmarks capture the visibility state of visuals (set in the Selection pane). Buttons with a Bookmark action switch between them.","why":["","Drillthrough passes filters to a detail page.","Field parameters swap fields, not whole visuals.","Edit interactions control cross-filtering."],"ar":"للتبديل بين عرضين على نفس الصفحة: Bookmarks مع Selection pane وأزرار.","ref":[{"t":"Create report bookmarks in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-bookmarks"}]},{"id":"PL-USE-002","d":"viz","s":"usability","type":"single","diff":2,"tag":"Bookmarks","q":"A bookmark should only change which visuals are visible, and must not reset the filters and slicer choices users made. What should you do?","opts":["Clear the Data option on the bookmark","Clear the Display option on the bookmark","Clear the Current page option on the bookmark","Select All visuals"],"ans":0,"exp":"The Data option captures filters and slicers. Turning it off makes the bookmark apply only display properties such as visibility, so user filters stay.","why":["","Display controls visibility, which you need to keep.","Current page controls navigation to the page.","All visuals affects scope, not whether filters are captured."],"ar":"لإبقاء فلاتر المستخدم ألغِ خيار Data في الـ bookmark.","ref":[{"t":"Create report bookmarks in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-bookmarks"}]},{"id":"PL-USE-003","d":"viz","s":"usability","type":"yesno","diff":2,"tag":"Bookmarks","q":"You're configuring bookmarks in Power BI Desktop.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["A bookmark can apply only to selected visuals.","A bookmark navigator visual creates buttons for a group of bookmarks automatically.","Readers in the service can create personal bookmarks without edit permissions."],"ans":[true,true,true],"exp":"Bookmarks can target selected visuals, the bookmark navigator builds buttons from a bookmark group, and readers can save personal bookmarks in the service.","why":["Yes. Use Selected visuals in the bookmark options.","Yes. Point the navigator at a bookmark group.","Yes. Personal bookmarks don't need edit rights."],"ar":"الـ bookmarks تدعم Selected visuals وBookmark navigator والـ personal bookmarks للقراء.","ref":[{"t":"Create report bookmarks in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-bookmarks"}]},{"id":"PL-USE-004","d":"viz","s":"usability","type":"single","diff":2,"tag":"Tooltips","q":"When users hover over a region in a map, they should see a small chart of that region's monthly trend. What should you create?","opts":["A report page tooltip and assign it in the map's Tooltips settings","A drillthrough page","A bookmark","A second map"],"ans":0,"exp":"Report page tooltips show a whole mini page on hover, filtered to the hovered data point.","why":["","Drillthrough requires a click and navigates away.","Bookmarks don't show on hover.","A second map doesn't show on hover."],"ar":"لعرض رسم صغير عند المرور: Report page tooltip.","ref":[{"t":"Create tooltips based on report pages","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-tooltips"}]},{"id":"PL-USE-005","d":"viz","s":"usability","type":"single","diff":1,"tag":"Interactions","q":"Selecting a bar in a column chart cross-highlights a donut chart, but you want the donut chart to be filtered instead. What should you change?","opts":["Edit interactions on the column chart and set the donut to Filter","Change the donut's theme","Add a slicer","Turn on drill down"],"ans":0,"exp":"Edit interactions controls how a selected visual affects every other visual on the page: filter, highlight or none.","why":["","Themes don't change interactions.","A slicer adds another control but doesn't change the chart's behavior.","Drill down changes hierarchy levels."],"ar":"لتغيير Highlight إلى Filter استخدم Edit interactions.","ref":[{"t":"Change how visuals interact in a Power BI report","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/service-reports-visual-interactions"}]},{"id":"PL-USE-006","d":"viz","s":"usability","type":"single","diff":2,"tag":"Interactions","q":"A KPI card showing the company total must never change when users click other visuals on the page. What should you do?","opts":["In Edit interactions, set None on the card for each visual that could affect it","Lock the card in the Filters pane","Put the card on another page","Change the card to a table"],"ans":0,"exp":"Setting the interaction to None stops cross-filtering from other visuals, so the card keeps showing the total. (Use REMOVEFILTERS in the measure if slicers must be ignored too.)","why":["","Filter pane locks apply to filters, not visual interactions.","Moving it hides it from the page's context.","Visual type doesn't stop interactions."],"ar":"لمنع تأثر الـ card بالنقر على غيره: Edit interactions ثم None.","ref":[{"t":"Change how visuals interact in a Power BI report","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/service-reports-visual-interactions"}]},{"id":"PL-USE-007","d":"viz","s":"usability","type":"single","diff":1,"tag":"Navigation","q":"You need a set of buttons across the top of every page that takes users to each page of the report and updates automatically when pages are added. What should you use?","opts":["A page navigator","Individual buttons with Page navigation actions","Bookmarks","Drillthrough"],"ans":0,"exp":"The page navigator creates a button for each visible page and updates as pages are added, removed or renamed.","why":["","Individual buttons work but must be updated by hand.","Bookmarks capture states, not pages.","Drillthrough is for detail pages with filters."],"ar":"قائمة تنقل تلقائية بين الصفحات: Page navigator.","ref":[{"t":"Create buttons in Power BI reports","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-buttons"}]},{"id":"PL-USE-008","d":"viz","s":"usability","type":"single","diff":2,"tag":"Drillthrough","q":"From a sales summary page, users should right-click a product and open a Product details page filtered to that product. What should you configure on the Product details page?","opts":["Add Product[ProductName] to the Drill through well of the details page","Add a slicer on ProductName","Create a bookmark per product","Turn on Personalize visuals"],"ans":0,"exp":"Drillthrough pages have a Drill through field well. Any visual using that field offers a Drill through option that opens the page filtered to the selected value.","why":["","A slicer requires the user to reselect the product.","Bookmarks per product don't scale.","Personalization changes visuals, not navigation."],"ar":"صفحة تفاصيل مفلترة بالمنتج: أضف الحقل إلى Drill through.","ref":[{"t":"Set up drillthrough in Power BI reports","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-drillthrough"}]},{"id":"PL-USE-009","d":"viz","s":"usability","type":"yesno","diff":3,"tag":"Drillthrough","q":"You're configuring drillthrough.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["With Keep all filters on, the target page also receives the filters from the source page's slicers.","Power BI adds a back button to a drillthrough page automatically.","Cross-report drillthrough can open a page in a different report in the same workspace."],"ans":[true,true,true],"exp":"Keep all filters passes the whole filter context. A back button is added to new drillthrough pages. Cross-report drillthrough works across reports in the same workspace or app when enabled.","why":["Yes.","Yes. It uses the Back action.","Yes. Turn on Cross-report on the target page and allow it in report settings."],"ar":"Keep all filters ينقل كل الفلاتر، وزر الرجوع يضاف تلقائيًا، ويمكن التنقل بين التقارير.","ref":[{"t":"Set up drillthrough in Power BI reports","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-drillthrough"}]},{"id":"PL-USE-010","d":"viz","s":"usability","type":"single","diff":2,"tag":"Drillthrough","q":"A drillthrough button on the summary page should stay disabled until a user selects a product in a chart, and then open the details page. What should you configure?","opts":["A button with Action type Drill through and Destination set to the details page","A page navigator","A bookmark navigator","An image with a URL"],"ans":0,"exp":"Drillthrough buttons are disabled until the selection meets the drill through fields of the destination page, then navigate with that filter.","why":["","Page navigators navigate without passing selection.","Bookmark navigators apply bookmarks.","Web URLs leave the report."],"ar":"زر Drill through يتفعّل بعد اختيار قيمة مناسبة.","ref":[{"t":"Create buttons in Power BI reports","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-buttons"},{"t":"Set up drillthrough in Power BI reports","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-drillthrough"}]},{"id":"PL-USE-011","d":"viz","s":"usability","type":"single","diff":1,"tag":"Sync slicers","q":"A Year slicer on the Overview page should also filter the Details and Trends pages, and appear only on Overview. What should you configure?","opts":["Sync slicers: sync the slicer to all three pages but make it visible only on Overview","Filters on this page on each page","Three separate slicers","Edit interactions"],"ans":0,"exp":"The Sync slicers pane controls on which pages a slicer filters (sync) and where it's shown (visible), independently.","why":["","Page filters aren't linked to the slicer.","Separate slicers don't stay in sync.","Edit interactions apply within one page."],"ar":"Sync slicers يحدد أين يفلتر الـ slicer وأين يظهر.","ref":[{"t":"Slicers in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualization-slicers"}]},{"id":"PL-USE-012","d":"viz","s":"usability","type":"single","diff":2,"tag":"Selection pane","q":"Two visuals overlap and the wrong one is on top, so users can't click the chart. What should you use?","opts":["The Selection pane to change the layer order","The Filters pane","Edit interactions","The Analytics pane"],"ans":0,"exp":"The Selection pane lists visuals by layer. You can reorder them, group them, hide them and set tab order.","why":["","The Filters pane manages filters.","Interactions control cross-filtering.","The Analytics pane adds reference lines."],"ar":"ترتيب الطبقات والتجميع والإخفاء من Selection pane.","ref":[{"t":"Create report bookmarks in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-bookmarks"}]},{"id":"PL-USE-013","d":"viz","s":"usability","type":"single","diff":2,"tag":"Selection pane","q":"Keyboard users navigate a report page with Tab, but focus jumps randomly between visuals and lands on decorative shapes. What should you do?","opts":["In the Selection pane, set the tab order and hide decorative objects from tab order","Change the theme","Add alt text to the shapes only","Move the page to a mobile layout"],"ans":0,"exp":"Tab order in the Selection pane defines the keyboard sequence, and decorative items can be removed from the tab order so users skip them.","why":["","Themes don't control focus order.","Alt text helps screen readers but doesn't change tab order.","Mobile layout doesn't fix desktop keyboard navigation."],"ar":"ترتيب التنقل بلوحة المفاتيح من Tab order في Selection pane.","ref":[{"t":"Design Power BI reports for accessibility","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-accessibility-overview"}]},{"id":"PL-USE-014","d":"viz","s":"usability","type":"multi","n":2,"diff":2,"tag":"Accessibility","q":"Which two practices make a report more accessible to users with visual impairments? Each correct answer presents a complete solution. Select TWO.","opts":["Add alt text to visuals","Use markers or patterns in addition to color to distinguish series","Use red and green as the only way to show good and bad","Put key information only in tooltips","Use very light gray text on white for a clean look"],"ans":[0,1],"exp":"Alt text is read by screen readers, and markers or labels mean color isn't the only way to tell series apart. Red and green alone fail for color vision deficiency, tooltips aren't reachable for everyone and low contrast text is hard to read.","why":["Correct.","Correct.","Color alone excludes color-blind users.","Tooltips aren't accessible to every user.","Low contrast fails accessibility guidelines."],"ar":"للإتاحة: Alt text، وعدم الاعتماد على اللون وحده، وتباين كافٍ.","ref":[{"t":"Design Power BI reports for accessibility","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-accessibility-overview"}]},{"id":"PL-USE-015","d":"viz","s":"usability","type":"single","diff":1,"tag":"Sorting","q":"A bar chart of sales by region is sorted alphabetically. You need the largest region at the top. What should you do?","opts":["Use Sort axis on the visual and sort by the Sales measure, descending","Sort by column in the model","Rename the regions","Change the theme"],"ans":0,"exp":"Visual sorting (More options > Sort axis) can sort by any field in the visual, including the measure, in ascending or descending order.","why":["","Sort by column defines a column's default order, not sorting by values.","Renaming doesn't reorder by value.","Themes don't sort."],"ar":"لترتيب الأعمدة حسب القيمة استخدم Sort axis على الـ visual.","ref":[{"t":"Sort one column by another column in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-sort-by-column"}]},{"id":"PL-USE-016","d":"viz","s":"usability","type":"single","diff":2,"tag":"Mobile","q":"Sales reps open reports on their phones in the Power BI app. The desktop layout is hard to read in portrait mode. What should you do?","opts":["Create a mobile layout for the key pages","Reduce the page size to phone dimensions","Publish a separate report for phones","Turn on automatic page refresh"],"ans":0,"exp":"A mobile-optimized layout arranges selected visuals for portrait phones and appears automatically in the Power BI mobile apps. The desktop layout remains unchanged.","why":["","A small page would also shrink the desktop view.","A separate report doubles maintenance.","Page refresh doesn't affect layout."],"ar":"للهواتف أنشئ Mobile layout للصفحات المهمة.","ref":[{"t":"Create mobile-optimized Power BI reports","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/power-bi-create-mobile-optimized-report-about"}]},{"id":"PL-USE-017","d":"viz","s":"usability","type":"yesno","diff":2,"tag":"Mobile","q":"You created mobile layouts in Power BI Desktop.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["The mobile layout is shown when the report is viewed in the Power BI mobile app in portrait orientation.","The mobile layout is shown in web browsers on a phone.","Changes you make to visual formatting in mobile layout don't change the desktop layout."],"ans":[true,false,true],"exp":"Mobile-optimized views appear in the mobile apps in portrait. Browsers always show the standard layout. Mobile formatting changes are specific to the mobile layout.","why":["Yes.","No. Browsers show the standard, non-optimized view.","Yes. Mobile format settings are independent."],"ar":"تخطيط الهاتف يظهر في تطبيق Power BI فقط، وتنسيقه مستقل عن تخطيط الكمبيوتر.","ref":[{"t":"Create mobile-optimized Power BI reports","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/power-bi-create-mobile-optimized-report-about"}]},{"id":"PL-USE-018","d":"viz","s":"usability","type":"single","diff":2,"tag":"Personalization","q":"Readers want to change a chart's visual type and swap the measure in the Power BI service without edit rights, and save their version. What should you enable?","opts":["Personalize visuals in the report settings","Allow users to edit the report","Build permission on the semantic model","Automatic page refresh"],"ans":0,"exp":"Personalize visuals lets readers change visual type, fields, legends and aggregations in reading view, and save changes as personal bookmarks.","why":["","Edit rights let them change the report for everyone.","Build permission lets them create new content, not personalize this report.","Page refresh is unrelated."],"ar":"لتخصيص القارئ للـ visuals بدون صلاحية تعديل: Personalize visuals.","ref":[{"t":"Let users personalize visuals in a report","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/power-bi-personalize-visuals"}]},{"id":"PL-USE-019","d":"viz","s":"usability","type":"single","diff":2,"tag":"Export settings","q":"A report on sensitive HR data must not allow readers to export any data from visuals, while still allowing them to view the report. What should you configure?","opts":["Report settings: Export data set to No export allowed","Remove the Export data button from the theme","Apply row-level security","Hide every column"],"ans":0,"exp":"The report's Export data setting can block all exports. Admin tenant settings can override report settings, so check both.","why":["","Themes can't remove export.","RLS limits rows, not exports.","Hiding columns doesn't block export of what's shown."],"ar":"لمنع التصدير تمامًا: Export data = No export allowed.","ref":[{"t":"Change settings for Power BI reports","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/power-bi-report-settings"},{"t":"Export data from a Power BI visualization","u":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualization-export-data"}]},{"id":"PL-USE-020","d":"viz","s":"usability","type":"single","diff":3,"tag":"Automatic page refresh","q":"You publish a DirectQuery report with automatic page refresh every 1 minute to a workspace on shared capacity (Pro). What happens in the service?","opts":["The refresh interval is limited to 30 minutes","It refreshes every minute","Automatic page refresh is removed from the report","It switches to Import mode"],"ans":0,"exp":"Outside Premium or Fabric capacity, fixed-interval automatic page refresh is locked at a minimum of 30 minutes, and change detection isn't available.","why":["","Short intervals need a Premium or Fabric capacity that allows them.","The setting stays, with the shared-capacity limit.","Storage mode doesn't change."],"ar":"في Pro بدون Premium يكون أقل تحديث تلقائي للصفحة 30 دقيقة.","ref":[{"t":"Automatic page refresh in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-automatic-page-refresh"}]},{"id":"PL-USE-021","d":"viz","s":"usability","type":"order","diff":2,"tag":"Tooltips","q":"You need a custom tooltip showing a product's image and margin when users hover over bars in a sales chart. Which three actions should you perform in sequence?","opts":["Create a new page and turn on Allow use as tooltip in Page information","Add the image and margin visuals to the tooltip page, sized for a tooltip","On the sales chart, set Tooltips type to Report page and select the tooltip page","Add the tooltip page to the Drill through well","Create a bookmark for each product"],"ans":[0,1,2],"exp":"Create the tooltip page, design it, then point the visual's tooltip settings to it. Drill through wells and bookmarks aren't involved.","why":["Step 1.","Step 2.","Step 3.","Drillthrough is a different feature.","Bookmarks aren't needed for tooltips."],"ar":"الخطوات: صفحة tooltip ثم تصميمها ثم ربطها بالـ visual.","ref":[{"t":"Create tooltips based on report pages","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-tooltips"}]},{"id":"PL-PAT-001","d":"viz","s":"patterns","type":"single","diff":1,"tag":"Analyze","q":"A line chart shows a sudden sales increase in March. You want Power BI to find which categories or regions explain the increase. What should you use?","opts":["Right-click the data point and select Analyze > Explain the increase","Performance Analyzer","Sync slicers","A what-if parameter"],"ans":0,"exp":"The Analyze feature explores the data automatically and shows the factors that contributed most to an increase or decrease.","why":["","Performance Analyzer measures speed.","Sync slicers link slicers across pages.","What-if parameters create scenarios."],"ar":"لتفسير الزيادة أو النقصان استخدم Analyze > Explain the increase.","ref":[{"t":"Apply insights to explain fluctuations in visuals","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-insights"}]},{"id":"PL-PAT-002","d":"viz","s":"patterns","type":"single","diff":1,"tag":"Grouping and binning","q":"You need to group customer ages into 10-year bands for a histogram. What's the fastest way?","opts":["Create a bin (New group > Bin) on the Age column with a bin size of 10","Write a nested IF measure","Create a hierarchy","Use a Top N filter"],"ans":0,"exp":"Binning divides a numeric or date column into equal-size ranges, creating a new column you can use on an axis.","why":["","Measures can't be axes.","Hierarchies organize levels, not ranges.","Top N filters limit items."],"ar":"لتقسيم الأعمار إلى فئات متساوية استخدم Bin.","ref":[{"t":"Use grouping and binning in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-grouping-and-binning"}]},{"id":"PL-PAT-003","d":"viz","s":"patterns","type":"single","diff":2,"tag":"Grouping and binning","q":"In a chart of sales by country, you want to combine five small countries into one Other group directly from the visual. What should you do?","opts":["Select the five countries, right-click and choose Group data","Create a calculated table","Unpivot the country column","Add a Top N filter"],"ans":0,"exp":"Grouping creates a new group column where selected values are combined, and the rest can be kept or put into Other.","why":["","A calculated table isn't needed.","Unpivot reshapes columns.","Top N hides the countries instead of grouping them."],"ar":"لدمج قيم في مجموعة من الـ visual: Group data.","ref":[{"t":"Use grouping and binning in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-grouping-and-binning"}]},{"id":"PL-PAT-004","d":"viz","s":"patterns","type":"single","diff":2,"tag":"Clustering","q":"You have a scatter chart of customers by frequency and spend, and you want Power BI to find natural segments automatically. What should you use?","opts":["Automatically find clusters on the scatter chart","Binning","A decomposition tree","A reference line"],"ans":0,"exp":"Clustering groups similar data points in scatter charts (and tables) into segments and adds a cluster column you can reuse.","why":["","Bins split one column into equal ranges.","Decomposition trees break a measure down by dimensions.","Reference lines add a constant or statistic."],"ar":"لاكتشاف شرائح العملاء تلقائيًا: Automatically find clusters.","ref":[{"t":"Use grouping and binning in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-grouping-and-binning"}]},{"id":"PL-PAT-005","d":"viz","s":"patterns","type":"single","diff":2,"tag":"AI visuals","q":"Marketing wants to know which factors most affect whether a customer gives a low satisfaction rating. Which visual should you use?","opts":["Key influencers","Decomposition tree","Q&A","Smart narrative"],"ans":0,"exp":"The key influencers visual analyzes which factors drive a metric or outcome, such as a low rating, and ranks them.","why":["","Decomposition trees let users drill a measure down by dimensions, but don't rank drivers automatically.","Q&A answers natural language questions.","Smart narratives summarize visuals in text."],"ar":"لمعرفة العوامل المؤثرة في نتيجة: Key influencers.","ref":[{"t":"Create key influencers visualizations","u":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualization-influencers"}]},{"id":"PL-PAT-006","d":"viz","s":"patterns","type":"single","diff":2,"tag":"AI visuals","q":"Managers want to break total sales down by region, then by product, then by channel, choosing the next level at each step themselves or letting AI pick the highest value. Which visual should you use?","opts":["Decomposition tree","Key influencers","Waterfall chart","Funnel"],"ans":0,"exp":"The decomposition tree lets users drill a measure into any dimension in any order, with AI splits that pick the highest or lowest next value.","why":["","Key influencers ranks drivers of an outcome.","Waterfall shows adds and subtracts to a total.","Funnel shows process stages."],"ar":"تفكيك المقياس حسب أبعاد متعددة: Decomposition tree.","ref":[{"t":"Create and view decomposition tree visuals","u":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualization-decomposition-tree"}]},{"id":"PL-PAT-007","d":"viz","s":"patterns","type":"single","diff":2,"tag":"Anomaly detection","q":"A line chart of daily website sessions over a year should automatically highlight unusual spikes and dips, with an explanation of possible reasons. What should you turn on?","opts":["Find anomalies in the Analytics pane of the line chart","Forecast","Error bars","Constant line"],"ans":0,"exp":"Anomaly detection on line charts with a date axis flags values outside an expected range and can explain them using fields you choose.","why":["","Forecast projects future values.","Error bars show uncertainty ranges from measures.","Constant lines show fixed values."],"ar":"لإبراز القيم الشاذة في line chart: Find anomalies.","ref":[{"t":"Anomaly detection","u":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualization-anomaly-detection"}]},{"id":"PL-PAT-008","d":"viz","s":"patterns","type":"yesno","diff":2,"tag":"Analytics pane","q":"You're using the Analytics pane.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["You can add an average line to a column chart.","Forecasting is available on a line chart with a continuous date axis.","Forecasting is available on a pie chart."],"ans":[true,true,false],"exp":"Reference lines such as average, median and constant lines are available on many charts. Forecasting needs a line chart with a continuous time axis. Pie charts don't support the Analytics pane features.","why":["Yes.","Yes. The axis must be continuous, not categorical.","No."],"ar":"خط المتوسط متاح لكثير من الرسوم، والتنبؤ يحتاج line chart بمحور زمني مستمر.","ref":[{"t":"Use the Analytics pane in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-analytics-pane"}]},{"id":"PL-PAT-009","d":"viz","s":"patterns","type":"single","diff":2,"tag":"Analytics pane","q":"A line chart shows monthly sales with a measure for the lower and upper estimate range. You want to show that range around the line. What should you add?","opts":["Error bars using the lower and upper bound measures","A median line","A trend line","A Top N filter"],"ans":0,"exp":"Error bars in the Analytics pane use measures for upper and lower bounds to draw ranges around each data point.","why":["","A median line is a single reference value.","A trend line shows direction, not a range.","Top N filters items."],"ar":"لإظهار نطاق حول الخط: Error bars بقيم الحد الأعلى والأدنى.","ref":[{"t":"Use the Analytics pane in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-analytics-pane"}]},{"id":"PL-PAT-010","d":"viz","s":"patterns","type":"single","diff":1,"tag":"Q&A","q":"Business users want to type questions like \"total sales by region last year\" and get a chart. Which visual should you add?","opts":["Q&A visual","Smart narrative","Key influencers","Paginated report visual"],"ans":0,"exp":"The Q&A visual accepts natural language questions and returns the best-matching visual, which you can convert to a standard visual.","why":["","Smart narrative summarizes existing visuals.","Key influencers analyzes drivers.","Paginated report visuals embed a paginated report."],"ar":"للأسئلة باللغة الطبيعية: Q&A visual.","ref":[{"t":"Q&A visuals in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualization-q-and-a"}]},{"id":"PL-PAT-011","d":"viz","s":"patterns","type":"single","diff":2,"tag":"Copilot","q":"A new analyst wants a quick overview of what tables, measures and topics a semantic model covers before building a report. Which Copilot capability helps most?","opts":["Ask Copilot to summarize the underlying semantic model","Create a narrative visual","Add measure descriptions","Suggest content for a new page"],"ans":0,"exp":"Copilot can summarize a semantic model in the Copilot pane, describing its data and important insights so the analyst understands it faster.","why":["","Narratives summarize visuals on a page.","Descriptions document measures, they don't summarize the model.","Suggest content proposes pages."],"ar":"لفهم الـ semantic model بسرعة اطلب من Copilot تلخيصه.","ref":[{"t":"Use Copilot with Power BI reports and semantic models","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/copilot-reports-overview"}]},{"id":"PL-PAT-012","d":"viz","s":"patterns","type":"multi","n":2,"diff":3,"tag":"Outliers","q":"You need to spot stores whose sales are unusually high or low compared with others. Which two approaches help? Each correct answer presents a complete solution. Select TWO.","opts":["A scatter chart of sales against store size, looking for points far from the cluster","A box-and-whisker style comparison using percentile or standard deviation measures with conditional formatting","A pie chart of sales by store","A card with total sales","Sorting stores alphabetically"],"ans":[0,1],"exp":"Scatter charts reveal points far from the pattern, and measures based on percentiles or standard deviation can flag outliers with conditional formatting. Pies, totals and alphabetical sorting hide outliers.","why":["Correct.","Correct.","Pies make comparisons between many stores hard.","A total hides the distribution.","Alphabetical order doesn't reveal outliers."],"ar":"لاكتشاف القيم الشاذة: Scatter chart أو مقاييس إحصائية مع تنسيق شرطي.","ref":[{"t":"Statistical functions (DAX)","u":"https://learn.microsoft.com/en-us/dax/statistical-functions-dax"},{"t":"Visualization types in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualization-types-for-reports-and-q-and-a"}]},{"id":"PL-WSP-001","d":"manage","s":"workspace","type":"single","diff":1,"tag":"Workspaces","q":"Your team of five analysts needs a shared place to publish and co-edit semantic models and reports. Where should they publish?","opts":["A shared workspace with each analyst assigned a role","Each analyst's My workspace","A dashboard","An app"],"ans":0,"exp":"Workspaces are the collaboration space for creators. My workspace is personal, and apps are for distributing content to consumers.","why":["","My workspace can't be shared for co-editing.","Dashboards are items, not publishing locations.","Apps distribute content read-only."],"ar":"للتعاون بين المطورين استخدم workspace مشتركة بأدوار.","ref":[{"t":"Create a workspace in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/collaborate-share/service-create-the-new-workspaces"},{"t":"Roles in workspaces in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/collaborate-share/service-roles-new-workspaces"}]},{"id":"PL-WSP-002","d":"manage","s":"workspace","type":"single","diff":2,"tag":"Workspace roles","q":"A user must publish and update reports in a workspace, but must not add people to the workspace or publish the workspace app. Which role should you assign?","opts":["Contributor","Member","Admin","Viewer"],"ans":0,"exp":"Contributors can create, edit and delete content. Adding users and publishing the app requires Member or Admin.","why":["","Members can add users and publish the app.","Admins can do everything, including deleting the workspace.","Viewers can only view."],"ar":"نشر وتعديل المحتوى بدون إدارة الأعضاء أو التطبيق = Contributor.","ref":[{"t":"Roles in workspaces in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/collaborate-share/service-roles-new-workspaces"}]},{"id":"PL-WSP-003","d":"manage","s":"workspace","type":"yesno","diff":2,"tag":"Workspace roles","q":"You're assigning workspace roles.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["A Member can add other users as Members, Contributors or Viewers.","A Contributor can update the workspace app if the workspace Admin allows it.","A Viewer can download the .pbix file of a report."],"ans":[true,true,false],"exp":"Members add users with the same or lower permissions. Admins can let Contributors update the app. Downloading .pbix files needs Contributor or higher.","why":["Yes.","Yes. It's the Allow contributors to update the app setting.","No. Viewers can't download .pbix files."],"ar":"Member يضيف أعضاء بصلاحيات مساوية أو أقل، وContributor يحدّث التطبيق إذا سُمح له، وViewer لا ينزّل pbix.","ref":[{"t":"Roles in workspaces in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/collaborate-share/service-roles-new-workspaces"}]},{"id":"PL-WSP-004","d":"manage","s":"workspace","type":"single","diff":1,"tag":"Apps","q":"You need to distribute 6 reports and 2 dashboards to 800 sales employees in a consistent, read-only package with navigation. What should you use?","opts":["Publish a workspace app","Share each report individually","Add all 800 users as workspace Viewers","Email PDF exports"],"ans":0,"exp":"Apps package content from a workspace with navigation and audiences, and they're the recommended way to distribute to large groups of consumers.","why":["","Sharing items one by one is hard to manage at scale.","Viewers see all workspace content, including work in progress.","PDFs are static and lose interactivity."],"ar":"لتوزيع محتوى على جمهور كبير: Workspace app.","ref":[{"t":"Publish an app in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/collaborate-share/service-create-distribute-apps"}]},{"id":"PL-WSP-005","d":"manage","s":"workspace","type":"single","diff":2,"tag":"Apps","q":"Managers should see all eight reports in the app, while the wider sales team sees only three. You want to maintain a single app. What should you configure?","opts":["Two audiences in the app, each with its own content and groups","Two workspaces","Row-level security","Two separate apps from the same workspace"],"ans":0,"exp":"App audiences let one app show different content to different groups.","why":["","Two workspaces duplicate content.","RLS filters rows, not which reports appear.","A workspace can publish only one app."],"ar":"لإظهار محتوى مختلف لمجموعات مختلفة داخل تطبيق واحد: Audiences.","ref":[{"t":"Publish an app in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/collaborate-share/service-create-distribute-apps"}]},{"id":"PL-WSP-006","d":"manage","s":"workspace","type":"single","diff":2,"tag":"Apps","q":"You changed a report in the workspace, but app users still see the old version. What should you do?","opts":["Update the app","Refresh the semantic model","Clear the browser cache for all users","Republish the .pbix to My workspace"],"ans":0,"exp":"Apps show the last published version of the content. After editing, select Update app so consumers get the changes.","why":["","Data refresh doesn't publish report design changes to the app.","The app itself hasn't been updated.","My workspace isn't the app's source."],"ar":"بعد تعديل التقرير يجب Update app حتى يراه المستخدمون.","ref":[{"t":"Publish an app in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/collaborate-share/service-create-distribute-apps"}]},{"id":"PL-WSP-007","d":"manage","s":"workspace","type":"single","diff":1,"tag":"Publishing","q":"You finished a report in Power BI Desktop. How do you get it to the team workspace?","opts":["Select Publish and choose the workspace","Save the .pbix to OneDrive only","Email the .pbix file","Export the report to PDF"],"ans":0,"exp":"Publishing uploads the semantic model and report to the selected workspace.","why":["","Saving to OneDrive doesn't publish it (unless you import it from the service).","Emailing files breaks governance.","PDF is static."],"ar":"النشر من Desktop: Publish ثم اختر الـ workspace.","ref":[{"t":"Publish semantic models and reports from Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-upload-desktop-files"}]},{"id":"PL-WSP-008","d":"manage","s":"workspace","type":"single","diff":2,"tag":"Dashboards","q":"Executives want a single page that combines key visuals from three different reports and lets them set alerts on KPI values. What should you create?","opts":["A dashboard with pinned tiles from the three reports","A new report page with copies of the visuals","A paginated report","An app audience"],"ans":0,"exp":"Dashboards are single-page canvases in the service that can hold tiles pinned from several reports. Data alerts are set on dashboard tiles.","why":["","Copying visuals across reports requires combining models.","Paginated reports are for print layouts.","Audiences control app content visibility."],"ar":"لجمع visuals من عدة تقارير مع تنبيهات: Dashboard.","ref":[{"t":"Create a Power BI dashboard from a report","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/service-dashboard-create"}]},{"id":"PL-WSP-009","d":"manage","s":"workspace","type":"single","diff":2,"tag":"Alerts","q":"A manager wants an email when daily revenue drops below 50,000. On which item can a data alert be set?","opts":["A card, KPI or gauge tile on a dashboard","A line chart on a report page","A table visual in Power BI Desktop","A paginated report"],"ans":0,"exp":"Data alerts are set in the service on dashboard tiles of type card, KPI and gauge.","why":["","Report visuals don't support data alerts.","Alerts aren't available in Desktop.","Paginated reports use subscriptions, not data alerts."],"ar":"التنبيهات تُضبط على tiles من نوع card أو KPI أو gauge في Dashboard.","ref":[{"t":"Set data alerts in the Power BI service","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/service-set-data-alerts"}]},{"id":"PL-WSP-010","d":"manage","s":"workspace","type":"single","diff":1,"tag":"Subscriptions","q":"A regional manager wants a snapshot of a report page in their inbox every Monday at 8 AM. What should you set up?","opts":["An email subscription to the report page","A data alert","Automatic page refresh","A bookmark"],"ans":0,"exp":"Subscriptions email a snapshot and link on a schedule.","why":["","Alerts trigger on thresholds, not schedules.","Page refresh updates visuals on screen.","Bookmarks don't send email."],"ar":"لإرسال التقرير بالبريد دوريًا: Subscription.","ref":[{"t":"Email subscriptions for reports and dashboards","u":"https://learn.microsoft.com/en-us/power-bi/collaborate-share/end-user-subscribe"}]},{"id":"PL-WSP-011","d":"manage","s":"workspace","type":"single","diff":2,"tag":"Distribution","q":"You need to share one report with three colleagues quickly. They have Pro licenses and aren't in the workspace. They must not be able to reshare it. What should you do?","opts":["Share the report with the three users and clear Allow recipients to share this report","Add them as workspace Members","Publish to web","Create an app for three users"],"ans":0,"exp":"Direct sharing is quick for a few people, and you control resharing and build permissions in the share dialog.","why":["","Members get broad rights over every item.","Publish to web makes the report public on the internet.","An app works but is heavier than needed."],"ar":"مشاركة سريعة مع عدد قليل: Share مع إلغاء إعادة المشاركة.","ref":[{"t":"Share Power BI reports and dashboards","u":"https://learn.microsoft.com/en-us/power-bi/collaborate-share/service-share-dashboards"}]},{"id":"PL-WSP-012","d":"manage","s":"workspace","type":"single","diff":3,"tag":"Distribution","q":"A marketing team wants to embed a report on the company's public website so anyone can see it without signing in. The data isn't confidential. Which option does this, and what's the main risk?","opts":["Publish to web; anyone with the link can see the data, with no security","Secure embed; it requires sign-in","An app; it's public by default","Share with the entire organization"],"ans":0,"exp":"Publish to web creates a public embed code with no authentication, so it must only be used for public data and may be disabled by admins.","why":["","Secure embed requires sign-in.","Apps require sign-in and permissions.","Organization sharing still needs sign-in."],"ar":"Publish to web للمحتوى العام فقط لأنه بدون أي حماية.","ref":[{"t":"Share Power BI reports and dashboards","u":"https://learn.microsoft.com/en-us/power-bi/collaborate-share/service-share-dashboards"}]},{"id":"PL-WSP-013","d":"manage","s":"workspace","type":"single","diff":2,"tag":"Endorsement","q":"Your Center of Excellence has verified that the Finance semantic model meets company standards. Only authorized reviewers can apply this badge. Which endorsement should be applied?","opts":["Certified","Promoted","Featured","Sensitivity label"],"ans":0,"exp":"Certification is applied by reviewers authorized by the admin and signals the content meets organizational quality standards. Promotion can be applied by anyone with write permission.","why":["","Promotion doesn't require authorized reviewers.","Featured puts content on Home, it isn't endorsement.","Labels classify sensitivity, not quality."],"ar":"اعتماد رسمي من مراجعين مخولين = Certified.","ref":[{"t":"Promote and certify Power BI content with endorsement","u":"https://learn.microsoft.com/en-us/power-bi/collaborate-share/service-endorsement-overview"}]},{"id":"PL-WSP-014","d":"manage","s":"workspace","type":"yesno","diff":2,"tag":"Endorsement","q":"You're using endorsement in Power BI.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["Any user with write permission on the workspace can promote a semantic model.","Dashboards can be certified.","Endorsed semantic models appear higher in lists when users choose a model to build on."],"ans":[true,false,true],"exp":"Promotion is open to content owners and workspace writers. Dashboards can't be promoted or certified. Endorsed items are highlighted and prioritized in lists.","why":["Yes.","No. Endorsement supports semantic models, reports, apps and dataflows, not dashboards.","Yes."],"ar":"الـ Promote لأي شخص لديه write، والـ dashboards لا تُعتمد، والمحتوى المعتمد يظهر أولًا.","ref":[{"t":"Promote and certify Power BI content with endorsement","u":"https://learn.microsoft.com/en-us/power-bi/collaborate-share/service-endorsement-overview"}]},{"id":"PL-WSP-015","d":"manage","s":"workspace","type":"single","diff":2,"tag":"Gateways","q":"A semantic model uses an Excel file on a network file share (\\\\fs01\\finance\\budget.xlsx). Scheduled refresh fails in the service. What's missing?","opts":["An on-premises data gateway with a data source for the file share","A Premium capacity","A sensitivity label","Row-level security"],"ans":0,"exp":"Files on a local network share are on-premises sources, so the service needs an on-premises data gateway to reach them.","why":["","Capacity type doesn't give network access.","Labels don't affect connectivity.","RLS doesn't affect refresh."],"ar":"الملفات على مشاركة شبكة داخلية تحتاج gateway للتحديث.","ref":[{"t":"What is an on-premises data gateway?","u":"https://learn.microsoft.com/en-us/power-bi/connect-data/service-gateway-onprem"}]},{"id":"PL-WSP-016","d":"manage","s":"workspace","type":"single","diff":2,"tag":"Scheduled refresh","q":"A semantic model in a Pro workspace needs to refresh every hour during working hours (10 times a day). What should you do?","opts":["Move the workspace to Premium Per User or a Fabric capacity, which allows up to 48 scheduled refreshes per day","Configure 10 time slots in the Pro workspace","Turn on automatic page refresh","Use incremental refresh"],"ans":0,"exp":"Shared (Pro) capacity allows up to 8 scheduled refreshes per day. PPU, Premium and Fabric capacities allow up to 48.","why":["","Pro workspaces are limited to 8 scheduled refreshes.","Page refresh applies to DirectQuery pages, not Import refresh.","Incremental refresh speeds up refreshes but doesn't raise the limit."],"ar":"Pro يسمح بـ 8 تحديثات يوميًا، وPPU أو Fabric حتى 48.","ref":[{"t":"Configure scheduled refresh","u":"https://learn.microsoft.com/en-us/power-bi/connect-data/refresh-scheduled-refresh"}]},{"id":"PL-WSP-017","d":"manage","s":"workspace","type":"yesno","diff":2,"tag":"Scheduled refresh","q":"You manage scheduled refresh for a semantic model.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["After four consecutive failures, Power BI turns off the refresh schedule.","If nobody views reports on the model for two months, scheduled refresh is paused.","A manual Refresh now counts toward the 8 scheduled refreshes per day on Pro."],"ans":[true,true,false],"exp":"Four consecutive failures disable the schedule, and two months of inactivity pause it. Manual Refresh now in the UI isn't counted in the eight scheduled refreshes.","why":["Yes. Fix the issue and turn the schedule back on.","Yes. Viewing a report resumes it.","No. UI-triggered on-demand refreshes aren't included in the limit."],"ar":"4 إخفاقات متتالية توقف الجدولة، وشهران بلا مشاهدة يوقفانها مؤقتًا، والتحديث اليدوي لا يُحسب.","ref":[{"t":"Configure scheduled refresh","u":"https://learn.microsoft.com/en-us/power-bi/connect-data/refresh-scheduled-refresh"},{"t":"Data refresh in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/connect-data/refresh-data"}]},{"id":"PL-WSP-018","d":"manage","s":"workspace","type":"order","diff":2,"tag":"Scheduled refresh","q":"A new Import semantic model uses an on-premises SQL Server. Which three actions should you perform in sequence to get a daily refresh working?","opts":["Install and register a standard on-premises data gateway that can reach the server","Add a connection for the SQL Server on the gateway and map the semantic model to it","Turn on Configure a refresh schedule in the semantic model settings and set the time","Set up a data alert on a dashboard tile","Create a personal bookmark"],"ans":[0,1,2],"exp":"Install the gateway, connect the model to the gateway data source (with credentials), then set the schedule.","why":["Step 1.","Step 2.","Step 3.","Alerts don't refresh data.","Bookmarks don't refresh data."],"ar":"الخطوات: gateway ثم connection للمصدر ثم جدولة التحديث.","ref":[{"t":"What is an on-premises data gateway?","u":"https://learn.microsoft.com/en-us/power-bi/connect-data/service-gateway-onprem"},{"t":"Configure scheduled refresh","u":"https://learn.microsoft.com/en-us/power-bi/connect-data/refresh-scheduled-refresh"}]},{"id":"PL-WSP-019","d":"manage","s":"workspace","type":"single","diff":2,"tag":"Workspaces","q":"A workspace must be assigned to a Fabric capacity so that Copilot and larger models are available. Where is this set?","opts":["Workspace settings > License info (license mode)","Report settings","The semantic model's Security page","Power BI Desktop options"],"ans":0,"exp":"The workspace license mode (Pro, PPU, Premium or Fabric capacity) is set in the workspace settings by a workspace admin with the right capacity permissions.","why":["","Report settings affect one report.","Security manages RLS membership.","Desktop options don't change workspace capacity."],"ar":"ربط الـ workspace بـ capacity من إعدادات الـ workspace > License info.","ref":[{"t":"Create a workspace in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/collaborate-share/service-create-the-new-workspaces"}]},{"id":"PL-SEC-001","d":"manage","s":"security","type":"single","diff":1,"tag":"RLS","q":"Sales managers must see only their own region's data in a report. What should you implement?","opts":["Row-level security roles with a filter on Region","A page-level filter","Hiding the Region column","A separate report per region"],"ans":0,"exp":"RLS applies filters to the semantic model based on role membership, so every report on the model respects them.","why":["","Readers can change or see around report filters, and they aren't security.","Hiding columns doesn't restrict rows.","Separate reports multiply maintenance and don't protect the model."],"ar":"لتقييد الصفوف حسب المستخدم: Row-level security.","ref":[{"t":"Row-level security (RLS) with Power BI","u":"https://learn.microsoft.com/en-us/fabric/security/service-admin-row-level-security"}]},{"id":"PL-SEC-002","d":"manage","s":"security","type":"single","diff":2,"tag":"RLS","q":"Each salesperson should see only the customers assigned to them. A table maps each salesperson's email to their customers. Which DAX filter should you use in one RLS role on the mapping table?","opts":["[Email] = USERPRINCIPALNAME()","[Email] = \"anna@contoso.com\"","[Email] = USERNAME() || TRUE()","[Email] = SELECTEDVALUE([Email])"],"ans":0,"exp":"Dynamic RLS compares a column to the signed-in user's UPN, so one role works for everyone.","why":["","Hard-coding needs one role per person.","OR TRUE() returns every row.","SELECTEDVALUE depends on report filters, not the user."],"ar":"RLS ديناميكي بدور واحد: USERPRINCIPALNAME().","ref":[{"t":"Row-level security (RLS) with Power BI","u":"https://learn.microsoft.com/en-us/fabric/security/service-admin-row-level-security"},{"t":"Row-level security (RLS) guidance in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/guidance/rls-guidance"}]},{"id":"PL-SEC-003","d":"manage","s":"security","type":"yesno","diff":2,"tag":"RLS","q":"RLS is configured on a semantic model in a workspace.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["RLS applies to users with the Viewer role in the workspace.","RLS applies to workspace Contributors.","RLS still applies to a Viewer who has Build permission and uses Analyze in Excel."],"ans":[true,false,true],"exp":"RLS restricts users who only have read access, such as Viewers and app users. Admins, Members and Contributors can edit the model, so RLS doesn't restrict them. Build permission doesn't bypass RLS.","why":["Yes.","No. Contributors, Members and Admins aren't restricted by RLS.","Yes. Build doesn't remove RLS."],"ar":"RLS يطبق على Viewer فقط، ولا يطبق على Contributor وما فوق، ويبقى مع Build.","ref":[{"t":"Row-level security (RLS) with Power BI","u":"https://learn.microsoft.com/en-us/fabric/security/service-admin-row-level-security"}]},{"id":"PL-SEC-004","d":"manage","s":"security","type":"single","diff":2,"tag":"RLS","q":"You created RLS roles in Power BI Desktop and published the model. Where do you assign users and groups to the roles?","opts":["In the Power BI service, on the semantic model's Security page","In Power BI Desktop, in Manage roles","In the workspace access list","In the report's Filters pane"],"ans":0,"exp":"Role definitions (DAX filters) are authored in Desktop or web modeling, but membership is managed in the service on the semantic model's Security page.","why":["","Desktop defines roles and lets you test with View as, but doesn't assign members.","Workspace access sets workspace roles, not RLS roles.","Filters aren't security."],"ar":"تعريف الأدوار في Desktop، وإضافة الأعضاء في الخدمة من Security.","ref":[{"t":"Row-level security (RLS) with Power BI","u":"https://learn.microsoft.com/en-us/fabric/security/service-admin-row-level-security"}]},{"id":"PL-SEC-005","d":"manage","s":"security","type":"single","diff":2,"tag":"RLS","q":"You want to test an RLS role before publishing, to see the report as a member of the West role would. What should you use in Power BI Desktop?","opts":["Modeling > View as, then select the West role","Performance Analyzer","The Selection pane","DAX query view without roles"],"ans":0,"exp":"View as lets you preview the report under one or more roles (and optionally another user), so you can check the filters.","why":["","Performance Analyzer measures speed.","Selection pane manages visuals.","DAX query view runs queries without applying a role unless configured."],"ar":"لاختبار الدور قبل النشر: View as في Desktop، وTest as role في الخدمة.","ref":[{"t":"Row-level security (RLS) with Power BI","u":"https://learn.microsoft.com/en-us/fabric/security/service-admin-row-level-security"}]},{"id":"PL-SEC-006","d":"manage","s":"security","type":"multi","n":2,"diff":2,"tag":"RLS","q":"Which two types of groups can you add as members of an RLS role in the Power BI service? Each correct answer presents a complete solution. Select TWO.","opts":["Microsoft Entra security groups","Mail-enabled security groups or distribution groups","Microsoft 365 groups","Groups created inside Power BI","Workspace roles"],"ans":[0,1],"exp":"RLS membership supports security groups, mail-enabled groups and distribution groups. Microsoft 365 groups aren't supported, and Power BI has no groups of its own.","why":["Correct.","Correct.","Microsoft 365 groups can't be added to RLS roles.","Power BI doesn't create groups.","Workspace roles aren't groups you can add."],"ar":"عضوية RLS تقبل security groups والـ mail-enabled/distribution groups وليس Microsoft 365 groups.","ref":[{"t":"Row-level security (RLS) with Power BI","u":"https://learn.microsoft.com/en-us/fabric/security/service-admin-row-level-security"}]},{"id":"PL-SEC-007","d":"manage","s":"security","type":"single","diff":3,"tag":"RLS","q":"An RLS role filters the Region dimension. Sales rows for that region are correctly filtered, but a Targets table related to Region isn't filtered. Targets has a many-to-one relationship to Region with single direction from Region. What's the most likely cause?","opts":["The relationship to Targets is inactive","RLS only filters fact tables","RLS requires bi-directional relationships to reach any table","The Region table must be hidden"],"ans":0,"exp":"RLS filters propagate only through active relationships. If the Targets relationship is inactive, the filter doesn't reach it.","why":["","RLS filters the table it's defined on and propagates from there.","Single-direction relationships from the dimension already carry the filter.","Hiding tables doesn't affect RLS."],"ar":"فلاتر RLS تنتقل فقط عبر العلاقات النشطة.","ref":[{"t":"Row-level security (RLS) guidance in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/guidance/rls-guidance"}]},{"id":"PL-SEC-008","d":"manage","s":"security","type":"single","diff":1,"tag":"Item access","q":"A colleague needs to build their own reports on your published semantic model, but shouldn't get a workspace role. What permission should you grant on the semantic model?","opts":["Build","Read only","Reshare only","Write"],"ans":0,"exp":"Build permission lets users create new reports and composite models on the semantic model, use Analyze in Excel and query it, without a workspace role.","why":["","Read lets them view reports but not build new ones.","Reshare lets them share, not build.","Write lets them edit the model, more than needed."],"ar":"لبناء تقارير على الـ semantic model بدون دور في الـ workspace: Build.","ref":[{"t":"Build permission for shared semantic models","u":"https://learn.microsoft.com/en-us/power-bi/connect-data/service-datasets-build-permissions"}]},{"id":"PL-SEC-009","d":"manage","s":"security","type":"yesno","diff":2,"tag":"Item access","q":"You share a report directly with a user.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["The user gets read access to the underlying semantic model through the report.","Without RLS, the user can see all data in the model through the report, not only the data in visible visuals.","Clearing Allow recipients to build content with the data associated with this report prevents them from getting Build permission."],"ans":[true,true,true],"exp":"Sharing a report grants read access to its model. Without RLS or OLS, data access isn't limited to what visuals show. The share dialog controls reshare and build permissions.","why":["Yes.","Yes. Use RLS or OLS to restrict data.","Yes."],"ar":"مشاركة التقرير تمنح قراءة الـ model، وبدون RLS تُتاح كل البيانات، ويمكن منع Build من نافذة المشاركة.","ref":[{"t":"Share Power BI reports and dashboards","u":"https://learn.microsoft.com/en-us/power-bi/collaborate-share/service-share-dashboards"}]},{"id":"PL-SEC-010","d":"manage","s":"security","type":"single","diff":2,"tag":"Object-level security","q":"HR analysts can see a Salary column, but other report users must not even know it exists, and visuals using it should fail for them. What should you implement?","opts":["Object-level security (OLS) on the Salary column for a role","Row-level security","Hide the Salary column","A sensitivity label"],"ans":0,"exp":"OLS secures tables or columns so that users in the role can't query or see them.","why":["","RLS filters rows, not columns.","Hidden columns can still be queried.","Labels classify content but don't hide columns."],"ar":"لإخفاء عمود أمنيًا عن مستخدمين: Object-level security.","ref":[{"t":"Object-level security","u":"https://learn.microsoft.com/en-us/analysis-services/tabular-models/object-level-security"}]},{"id":"PL-SEC-011","d":"manage","s":"security","type":"single","diff":1,"tag":"Sensitivity labels","q":"A report contains confidential financial data. When users export it to Excel or PDF, the files must stay protected and marked Confidential. What should you apply?","opts":["A Microsoft Purview sensitivity label on the report or semantic model","Row-level security","A theme with a red banner","Certified endorsement"],"ans":0,"exp":"Sensitivity labels classify content and, when exported to supported files such as Excel, PowerPoint and PDF, the label and its protection travel with the file.","why":["","RLS filters rows but doesn't protect exported files.","A theme isn't protection.","Certification is about quality."],"ar":"لحماية الملفات المصدّرة: Sensitivity label من Purview.","ref":[{"t":"Sensitivity labels in Power BI","u":"https://learn.microsoft.com/en-us/fabric/enterprise/powerbi/service-security-sensitivity-label-overview"}]},{"id":"PL-SEC-012","d":"manage","s":"security","type":"yesno","diff":2,"tag":"Sensitivity labels","q":"Your tenant uses sensitivity labels in Power BI.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["A new report created in the service on a labeled semantic model inherits the model's label.","You can apply a sensitivity label in Power BI Desktop.","Exporting data to a .csv file keeps the sensitivity label."],"ans":[true,true,false],"exp":"New content inherits the parent's label, and Desktop supports labeling .pbix files. CSV exports don't support sensitivity labels.","why":["Yes.","Yes. The label is shown in the status bar and kept in the .pbix.","No. Only file types that support labels, such as Excel, keep them."],"ar":"التقارير الجديدة ترث التصنيف، ويمكن التصنيف في Desktop، وملفات CSV لا تحمل التصنيف.","ref":[{"t":"Sensitivity labels in Power BI","u":"https://learn.microsoft.com/en-us/fabric/enterprise/powerbi/service-security-sensitivity-label-overview"},{"t":"Export data from a Power BI visualization","u":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualization-export-data"}]},{"id":"PL-SEC-013","d":"manage","s":"security","type":"single","diff":2,"tag":"Workspace roles","q":"To follow the principle of least privilege, business users who only read reports should get which access?","opts":["The app audience or the Viewer role","Member role","Contributor role","Admin role"],"ans":0,"exp":"Consumers only need read access. Apps or the Viewer role give that, and RLS applies to them.","why":["","Members can manage content and users.","Contributors can change content.","Admins control everything."],"ar":"القارئ يأخذ Viewer أو تطبيق، وهذا أيضًا يفعّل RLS عليه.","ref":[{"t":"Roles in workspaces in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/collaborate-share/service-roles-new-workspaces"}]},{"id":"PL-SEC-014","d":"manage","s":"security","type":"single","diff":3,"tag":"Semantic model access","q":"A user with the Viewer role wants to use Analyze in Excel on a semantic model in the workspace, but the option is unavailable. What should you grant?","opts":["Build permission on the semantic model","The Admin role","Write permission on the report","A Pro license only"],"ans":0,"exp":"Viewers need Build permission on the semantic model to use Analyze in Excel or export underlying data.","why":["","Admin is far more than needed.","Report write permission doesn't give model access for Excel.","A license alone doesn't grant the permission."],"ar":"Viewer يحتاج Build لاستخدام Analyze in Excel.","ref":[{"t":"Roles in workspaces in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/collaborate-share/service-roles-new-workspaces"},{"t":"Build permission for shared semantic models","u":"https://learn.microsoft.com/en-us/power-bi/connect-data/service-datasets-build-permissions"}]},{"id":"PL-SEC-015","d":"manage","s":"security","type":"order","diff":3,"tag":"RLS","q":"You need dynamic row-level security so each store manager sees only their stores. Which three actions should you perform in sequence?","opts":["Load a mapping table of manager email to StoreID and relate it to the Store dimension","Create a role with the filter [ManagerEmail] = USERPRINCIPALNAME() on the mapping table, then test it with View as","Publish, then add the managers' security group to the role on the semantic model's Security page","Give managers the Contributor role","Hide the Store table"],"ans":[0,1,2],"exp":"Model the user-to-data mapping first, define and test the role, then publish and assign members in the service. Contributors would bypass RLS, and hiding tables isn't security.","why":["Step 1.","Step 2.","Step 3.","Contributors aren't restricted by RLS.","Hiding isn't security."],"ar":"الخطوات: جدول ربط، دور ديناميكي واختباره، ثم النشر وإضافة الأعضاء.","ref":[{"t":"Row-level security (RLS) with Power BI","u":"https://learn.microsoft.com/en-us/fabric/security/service-admin-row-level-security"},{"t":"Row-level security (RLS) guidance in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/guidance/rls-guidance"}]},{"id":"PL-SEC-016","d":"manage","s":"security","type":"single","diff":2,"tag":"Item access","q":"A user who isn't in the workspace received a link to an app report, but sees an access request page. The app was published to the Sales audience only. What should you do?","opts":["Add the user (or their group) to the app audience","Give them Build permission only","Add them to the RLS role only","Certify the report"],"ans":0,"exp":"App access comes from the audiences configured when publishing the app. RLS and Build don't grant access to the app itself.","why":["","Build doesn't give app access.","RLS membership doesn't give app access.","Endorsement doesn't grant access."],"ar":"الوصول للتطبيق يُمنح عبر إضافة المستخدم إلى الـ audience.","ref":[{"t":"Publish an app in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/collaborate-share/service-create-distribute-apps"}]},{"id":"PL-GET-019","d":"prep","s":"get","type":"order","diff":2,"tag":"Shared semantic model","q":"You need to add a local Excel table of budgets to a report that currently uses a live connection to a published semantic model. Which three actions should you perform in sequence?","opts":["Select Make changes to this model to switch to a DirectQuery connection to the semantic model","Get data from the Excel workbook and load the budget table","Create a relationship from the budget table to the model's Date table","Download the semantic model's .pbix and edit it","Change the semantic model's storage mode to Import in the service"],"ans":[0,1,2],"exp":"A live connection can't mix sources. Converting to a composite model (DirectQuery to the semantic model) allows adding local tables and relationships.","why":["Step 1.","Step 2.","Step 3.","That creates a separate copy of the model.","You can't change a published model's storage mode from a report."],"ar":"الخطوات: Make changes to this model ثم إضافة الجدول ثم إنشاء العلاقة.","ref":[{"t":"Use composite models in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-composite-models"}]},{"id":"PL-CLN-016","d":"prep","s":"clean","type":"order","diff":2,"tag":"Data quality","q":"A Phone column has values with spaces, dashes and the country code in different formats. You need one consistent format. Which three actions should you perform in sequence in Power Query?","opts":["Trim the column and use Replace values to remove spaces and dashes","Add a conditional column (or custom column) that adds the country code when it's missing","Remove the original column and rename the new one to Phone","Change the Phone column type to Decimal Number","Pivot the Phone column"],"ans":[0,1,2],"exp":"Normalize the characters first, then apply the formatting rule, and finally replace the old column. Phone numbers are text, not numbers.","why":["Step 1.","Step 2.","Step 3.","Numbers lose leading zeros and the plus sign.","Pivot doesn't clean values."],"ar":"تنظيف الهاتف: إزالة المسافات والشرطات ثم توحيد كود الدولة ثم استبدال العمود.","ref":[{"t":"Data types in Power Query","u":"https://learn.microsoft.com/en-us/power-query/data-types"}]},{"id":"PL-TRF-026","d":"prep","s":"transform","type":"multi","n":2,"diff":2,"tag":"Merge and append","q":"You're combining data in Power Query. Which two statements are correct? Each correct answer presents a complete solution. Select TWO.","opts":["Append adds rows from tables with the same columns","Merge adds columns from another table by matching key values","Append requires a key column to match rows","Merge can only combine two tables that have identical columns","Append removes duplicate rows automatically"],"ans":[0,1],"exp":"Append stacks rows and matches columns by name. Merge joins tables on keys and adds columns. Append needs no key and doesn't remove duplicates.","why":["Correct.","Correct.","Append matches by column name, not key.","Merge works on any tables with a matching key.","Duplicates stay unless you remove them."],"ar":"Append يضيف صفوفًا، وMerge يضيف أعمدة بمطابقة مفتاح.","ref":[{"t":"Append queries","u":"https://learn.microsoft.com/en-us/power-query/append-queries"},{"t":"Merge queries overview","u":"https://learn.microsoft.com/en-us/power-query/merge-queries-overview"}]},{"id":"PL-DES-019","d":"model","s":"design","type":"order","diff":2,"tag":"Date table","q":"You need a proper Date table for time intelligence in a model that has no date table yet. Which three actions should you perform in sequence?","opts":["Create a table with a contiguous list of dates covering all years in the data (CALENDAR or Power Query List.Dates)","Add Year, Month, Month Number and other columns, and sort Month by Month Number","Mark it as a date table and relate its Date column to the fact tables' date columns","Turn on Auto date/time","Create a many-to-many relationship to Sales"],"ans":[0,1,2],"exp":"Build a complete date range, add the attributes users need with correct sorting, then mark it and relate it. Auto date/time isn't needed with a proper date table.","why":["Step 1.","Step 2.","Step 3.","Auto date/time adds hidden tables instead.","Date to Sales is one-to-many."],"ar":"الخطوات: قائمة تواريخ كاملة، ثم الأعمدة والترتيب، ثم Mark as date table والعلاقات.","ref":[{"t":"Set and use date tables in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-date-tables"},{"t":"Date table guidance for Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/guidance/model-date-tables"}]},{"id":"PL-DAX-026","d":"model","s":"dax","type":"multi","n":2,"diff":3,"tag":"Time intelligence","q":"Which two measures return sales for the previous month when used in a visual grouped by month? Each correct answer presents a complete solution. Select TWO.","opts":["CALCULATE([Sales], PREVIOUSMONTH('Date'[Date]))","CALCULATE([Sales], DATEADD('Date'[Date], -1, MONTH))","CALCULATE([Sales], SAMEPERIODLASTYEAR('Date'[Date]))","TOTALMTD([Sales], 'Date'[Date])","[Sales] - 30"],"ans":[0,1],"exp":"PREVIOUSMONTH returns the dates of the previous month, and DATEADD shifts the current dates back one month. SAMEPERIODLASTYEAR goes back a year, TOTALMTD is month to date and subtracting 30 isn't a time shift.","why":["Correct.","Correct.","That's the same month last year.","That's month-to-date of the current month.","That subtracts 30 from the sales amount."],"ar":"الشهر السابق: PREVIOUSMONTH أو DATEADD بقيمة -1 MONTH.","ref":[{"t":"Time intelligence functions (DAX)","u":"https://learn.microsoft.com/en-us/dax/time-intelligence-functions-dax"}]},{"id":"PL-DAX-027","d":"model","s":"dax","type":"order","diff":3,"tag":"Calculation groups","q":"You need a Time Intelligence calculation group with Current, YTD and PY items in Power BI Desktop. Which three actions should you perform in sequence?","opts":["In Model view, select Calculation group and accept turning on Discourage implicit measures","Create calculation items such as YTD = CALCULATE(SELECTEDMEASURE(), DATESYTD('Date'[Date]))","Put the calculation group column on a matrix's columns and a measure in Values","Create a what-if parameter","Create an implicit SUM of Sales[Amount] in the matrix"],"ans":[0,1,2],"exp":"Create the group (which requires discouraging implicit measures), define items with SELECTEDMEASURE, then use the group's column in a visual with an explicit measure.","why":["Step 1.","Step 2.","Step 3.","What-if parameters are unrelated.","Calculation items don't apply to implicit measures."],"ar":"الخطوات: إنشاء المجموعة، ثم العناصر بـ SELECTEDMEASURE، ثم استخدامها في visual.","ref":[{"t":"Create calculation groups","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/calculation-groups"}]},{"id":"PL-PRF-013","d":"model","s":"perf","type":"order","diff":2,"tag":"Performance Analyzer","q":"A report page is slow and you want to find and fix the slowest measure. Which three actions should you perform in sequence?","opts":["Open Performance Analyzer, start recording and refresh the visuals","Sort by duration and copy the query of the slowest visual","Paste it into DAX query view, test an improved measure with DEFINE MEASURE and update the model","Turn on Auto date/time","Add more visuals to compare"],"ans":[0,1,2],"exp":"Measure first, isolate the slowest query, then test and apply a fix in DAX query view.","why":["Step 1.","Step 2.","Step 3.","That adds hidden tables and doesn't help.","More visuals add load."],"ar":"الخطوات: تسجيل Performance Analyzer، نسخ أبطأ استعلام، ثم تحسينه في DAX query view.","ref":[{"t":"Use Performance Analyzer to examine report element performance","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-performance-analyzer"},{"t":"Work with DAX query view","u":"https://learn.microsoft.com/en-us/power-bi/transform-model/dax-query-view"}]},{"id":"PL-REP-023","d":"viz","s":"reports","type":"multi","n":2,"diff":2,"tag":"Choose a visual","q":"Which two visuals are good choices to compare the sales of 12 product categories at one point in time? Each correct answer presents a complete solution. Select TWO.","opts":["Clustered bar chart","Clustered column chart","Line chart","Pie chart with 12 slices","Card"],"ans":[0,1],"exp":"Bars and columns make it easy to compare category sizes. Lines imply continuity over time, pies with many slices are hard to compare and cards show one value.","why":["Correct.","Correct.","Lines are for trends.","Twelve slices are hard to compare.","Cards show one number."],"ar":"للمقارنة بين فئات كثيرة: Bar أو Column chart.","ref":[{"t":"Visualization types in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualization-types-for-reports-and-q-and-a"}]},{"id":"PL-USE-022","d":"viz","s":"usability","type":"order","diff":2,"tag":"Bookmarks","q":"You need buttons that switch a page between a map view and a table view. Which three actions should you perform in sequence?","opts":["Place both visuals on the page and use the Selection pane to hide the table","Create a bookmark MapView, then show the table and hide the map, and create a bookmark TableView","Add two buttons with the Bookmark action set to MapView and TableView","Create a drillthrough page","Turn on Personalize visuals"],"ans":[0,1,2],"exp":"Visibility is set in the Selection pane, captured in bookmarks (Display state) and triggered by buttons.","why":["Step 1.","Step 2.","Step 3.","Drillthrough navigates to another page.","Personalization isn't needed."],"ar":"الخطوات: Selection pane للإخفاء، ثم Bookmarks لكل حالة، ثم أزرار.","ref":[{"t":"Create report bookmarks in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-bookmarks"},{"t":"Create buttons in Power BI reports","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-buttons"}]},{"id":"PL-PAT-013","d":"viz","s":"patterns","type":"order","diff":2,"tag":"Grouping and binning","q":"You need a histogram of order amounts in bands of 100. Which three actions should you perform in sequence?","opts":["Right-click the Amount column and select New group","Choose Bin as the group type and set the bin size to 100","Put the new bin column on the axis of a column chart and a count of orders in Values","Add Amount to a slicer","Create a Top N filter"],"ans":[0,1,2],"exp":"Binning creates a new column with equal-size ranges that you use as the chart axis.","why":["Step 1.","Step 2.","Step 3.","A slicer doesn't create bands.","Top N limits items."],"ar":"الخطوات: New group ثم Bin بحجم 100 ثم وضعه على المحور.","ref":[{"t":"Use grouping and binning in Power BI Desktop","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-grouping-and-binning"}]},{"id":"PL-WSP-020","d":"manage","s":"workspace","type":"order","diff":2,"tag":"Apps","q":"You need to distribute a workspace's reports to the sales team as an app and update it later. Which three actions should you perform in sequence?","opts":["Select Create app in the workspace and choose the content and navigation","Configure an audience with the sales team's security group and publish the app","After changing a report, select Update app","Add every salesperson as a workspace Contributor","Share the .pbix file by email"],"ans":[0,1,2],"exp":"Create the app from the workspace, set audiences and publish, then update the app when content changes.","why":["Step 1.","Step 2.","Step 3.","Contributors could edit content.","Emailing files breaks governance."],"ar":"الخطوات: Create app ثم audience والنشر ثم Update app بعد التعديلات.","ref":[{"t":"Publish an app in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/collaborate-share/service-create-distribute-apps"}]},{"id":"PL-SEC-017","d":"manage","s":"security","type":"multi","n":2,"diff":2,"tag":"Sensitivity labels","q":"Which two export formats keep a Power BI sensitivity label and its protection? Each correct answer presents a complete solution. Select TWO.","opts":["Excel (.xlsx)","PDF","CSV","A screenshot image","Copying values to the clipboard"],"ans":[0,1],"exp":"Sensitivity labels are applied to supported exported files such as Excel, PowerPoint and PDF. CSV, images and clipboard copies don't carry labels.","why":["Correct.","Correct.","CSV doesn't support sensitivity labels.","Images don't carry labels.","Clipboard content isn't labeled."],"ar":"التصنيف ينتقل مع Excel وPowerPoint وPDF، وليس مع CSV.","ref":[{"t":"Sensitivity labels in Power BI","u":"https://learn.microsoft.com/en-us/fabric/enterprise/powerbi/service-security-sensitivity-label-overview"},{"t":"Export data from a Power BI visualization","u":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualization-export-data"}]},{"id":"PL-SEC-018","d":"manage","s":"security","type":"multi","n":2,"diff":3,"tag":"Workspace roles","q":"Which two workspace roles can publish the workspace app and add users to the workspace? Each correct answer presents a complete solution. Select TWO.","opts":["Admin","Member","Contributor","Viewer","Any user with Build permission"],"ans":[0,1],"exp":"Admins and Members can publish or unpublish the app and add users (Members can add roles up to Member). Contributors can only update the app when allowed, and Viewers read content.","why":["Correct.","Correct.","Contributors can't publish the app or add users.","Viewers only view.","Build permission is for building content."],"ar":"نشر التطبيق وإضافة المستخدمين: Admin وMember.","ref":[{"t":"Roles in workspaces in Power BI","u":"https://learn.microsoft.com/en-us/power-bi/collaborate-share/service-roles-new-workspaces"}]}],"cases":[{"id":"PCS1","title":"Gulf Auto Group","scenario":"<h4>Overview</h4><p>Gulf Auto Group sells and services cars in 14 showrooms across the UAE. The analytics team uses Power BI Pro licenses. A new workspace named Sales Analytics is assigned to a Fabric F64 capacity.</p><h4>Existing environment</h4><ul><li>Leads and sales are stored in a SQL Server database named CRMDB in the company datacenter. There's no network connectivity from Azure to the datacenter.</li><li>Monthly showroom targets are maintained by Finance in an Excel workbook in a SharePoint Online site. The workbook has one row per showroom and one column per month.</li><li>CRMDB has a table named Sales with the columns SaleID, ShowroomID, ModelID, SaleDate, DeliveryDate, CustomerID and Amount.</li><li>A Showroom table stores ShowroomID, ShowroomName, City and ManagerEmail.</li></ul><h4>Requirements</h4><h5>Reporting</h5><ul><li>Managers must compare sales by sale date and by delivery date in the same visual.</li><li>A report page must show each month's sales against the Finance target.</li><li>Sales must refresh every day at 7:00 AM.</li><li>Executives want an email when monthly sales drop below target.</li></ul><h5>Security</h5><ul><li>Each showroom manager must see only their showroom's data. Managers must not be able to edit reports.</li><li>Regional directors must be able to build their own reports on the semantic model without a workspace role.</li></ul>","questions":[{"id":"PCS1-01","d":"prep","s":"get","type":"single","diff":2,"tag":"Gateways","q":"You need to meet the daily refresh requirement for the CRMDB data. What should you deploy?","opts":["A standard on-premises data gateway on a server that can reach CRMDB","A virtual network data gateway","Nothing; the Fabric capacity reaches CRMDB directly","A personal mode gateway on a manager's laptop"],"ans":0,"exp":"CRMDB is in the company datacenter with no Azure connectivity, so the service needs an on-premises data gateway. Standard mode is shared and runs on an always-on server.","why":["","VNet gateways reach sources in Azure virtual networks.","Capacities don't open network paths to on-premises servers.","A laptop gateway is personal and goes offline."],"ar":"CRMDB داخل مركز البيانات، لذلك تحتاج standard on-premises gateway.","ref":[{"t":"What is an on-premises data gateway?","u":"https://learn.microsoft.com/en-us/power-bi/connect-data/service-gateway-onprem"}]},{"id":"PCS1-02","d":"prep","s":"transform","type":"single","diff":2,"tag":"Unpivot","q":"You need to prepare the Finance target workbook so each month's target can be compared with sales. What should you do in Power Query?","opts":["Select ShowroomID and use Unpivot other columns, then convert the attribute to a month date","Pivot the month columns","Append the workbook to the Sales query","Transpose the table and load it"],"ans":0,"exp":"The workbook is wide (one column per month). Unpivoting gives one row per showroom and month, which can relate to the Showroom and Date tables.","why":["","Pivot makes it wider.","Append stacks rows from tables with the same columns.","Transpose puts showrooms in columns, still not a fact table."],"ar":"جدول الأهداف العريض يُحول بـ Unpivot other columns.","ref":[{"t":"Unpivot columns","u":"https://learn.microsoft.com/en-us/power-query/unpivot-column"}]},{"id":"PCS1-03","d":"model","s":"design","type":"single","diff":2,"tag":"Role-playing dimension","q":"You need to meet the requirement to compare sales by sale date and by delivery date in the same visual. What should you do?","opts":["Create two date tables, Sale Date and Delivery Date, each with an active relationship to Sales","Create one Date table with two active relationships","Use USERELATIONSHIP in a single measure only","Make the relationship bi-directional"],"ans":0,"exp":"To slice by both dates in the same visual, each date role needs its own table with an active relationship. USERELATIONSHIP measures switch the relationship but don't allow two date axes at once.","why":["","Only one active relationship is allowed between two tables.","USERELATIONSHIP alone doesn't give two separate date fields to slice by.","Direction doesn't add a second role."],"ar":"للتصفية بتاريخين في نفس الـ visual: جدولا تاريخ منفصلان.","ref":[{"t":"Understand star schema and the importance for Power BI","u":"https://learn.microsoft.com/en-us/power-bi/guidance/star-schema"},{"t":"USERELATIONSHIP function (DAX)","u":"https://learn.microsoft.com/en-us/dax/userelationship-function-dax"}]},{"id":"PCS1-04","d":"manage","s":"security","type":"single","diff":2,"tag":"RLS","q":"You need to meet the showroom manager requirement. What should you configure?","opts":["A dynamic RLS role on Showroom with [ManagerEmail] = USERPRINCIPALNAME(), and give managers the app audience or Viewer role","A static role per showroom, and give managers the Contributor role","A page filter on ShowroomName, and give managers the Member role","Hide the Showroom table, and give managers the Viewer role"],"ans":0,"exp":"Dynamic RLS with the user's UPN serves all managers with one role, and RLS only applies to read-only users such as Viewers or app users, who also can't edit.","why":["","Contributors can edit and bypass RLS.","Page filters aren't security and Members can edit.","Hiding a table doesn't filter rows."],"ar":"RLS ديناميكي + Viewer أو تطبيق حتى يطبق RLS ولا يعدلوا.","ref":[{"t":"Row-level security (RLS) with Power BI","u":"https://learn.microsoft.com/en-us/fabric/security/service-admin-row-level-security"}]},{"id":"PCS1-05","d":"manage","s":"workspace","type":"single","diff":2,"tag":"Alerts","q":"You need to meet the executive email requirement. What should you create?","opts":["A dashboard with a KPI or card tile for monthly sales versus target, and a data alert on it","A subscription to the report page every Monday","Automatic page refresh on the report","A bookmark"],"ans":0,"exp":"Data alerts send notifications when a dashboard tile value crosses a threshold. They're available on card, KPI and gauge tiles.","why":["","Subscriptions send on a schedule, not when a value drops.","Page refresh doesn't send email.","Bookmarks don't notify."],"ar":"تنبيه عند انخفاض القيمة = data alert على tile في dashboard.","ref":[{"t":"Set data alerts in the Power BI service","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/service-set-data-alerts"},{"t":"Create a Power BI dashboard from a report","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/service-dashboard-create"}]},{"id":"PCS1-06","d":"manage","s":"security","type":"yesno","diff":2,"tag":"Item access","q":"Regional directors must build their own reports on the semantic model without a workspace role.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["Granting Build permission on the semantic model lets them create reports in Power BI Desktop with a live connection.","If directors are also members of an RLS role, RLS applies to their new reports.","Directors need the Member role to connect to the semantic model."],"ans":[true,true,false],"exp":"Build permission allows creating content on the model without a workspace role. RLS applies to them because they only have read and build access. No workspace role is required.","why":["Yes.","Yes. Build doesn't bypass RLS.","No. Build permission is enough to connect and build."],"ar":"Build يكفي لبناء تقارير، وRLS يبقى مطبقًا عليهم.","ref":[{"t":"Build permission for shared semantic models","u":"https://learn.microsoft.com/en-us/power-bi/connect-data/service-datasets-build-permissions"},{"t":"Row-level security (RLS) with Power BI","u":"https://learn.microsoft.com/en-us/fabric/security/service-admin-row-level-security"}]}]},{"id":"PCS2","title":"Desert Retail Co.","scenario":"<h4>Overview</h4><p>Desert Retail Co. runs 60 supermarkets in Saudi Arabia and Qatar. The BI team publishes reports to a workspace named Retail BI that uses a Premium Per User (PPU) license mode.</p><h4>Existing environment</h4><ul><li>Point-of-sale data is exported nightly as CSV files to a SharePoint Online document library, one file per store per day.</li><li>A Product table in an Azure SQL database has 40,000 products. Only 9,000 products have ever been sold.</li><li>An Inventory table records the quantity on hand per product per store at the end of each day.</li><li>The current Sales table contains a DateTime column with seconds and a TransactionID column with 400 million unique values. Neither is used in any report.</li><li>The main report page has 28 visuals and takes 15 seconds to load.</li></ul><h4>Requirements</h4><ul><li>Monthly inventory must show the stock on the last day of each month, summed across stores.</li><li>Reduce model size and improve the main page load time.</li><li>Store managers use phones in the Power BI mobile app.</li><li>Reports must support Arabic-speaking readers who use screen readers.</li></ul>","questions":[{"id":"PCS2-01","d":"prep","s":"get","type":"single","diff":1,"tag":"Get data","q":"You need to load all the daily CSV files into one Sales table with the least ongoing effort. What should you use?","opts":["The SharePoint folder connector with Combine files","The Text/CSV connector once per file","The Web connector","A dataflow that copies files to a local folder"],"ans":0,"exp":"The SharePoint folder connector lists all files and Combine files appends them through a sample-file function, picking up new files at each refresh.","why":["","One query per file doesn't scale.","The Web connector reads single URLs.","Copying to a local folder adds a gateway and extra steps."],"ar":"ملفات يومية في SharePoint: SharePoint folder ثم Combine files.","ref":[{"t":"Append queries","u":"https://learn.microsoft.com/en-us/power-query/append-queries"}]},{"id":"PCS2-02","d":"model","s":"dax","type":"single","diff":2,"tag":"Semi-additive","q":"Which measure meets the monthly inventory requirement?","opts":["CLOSINGBALANCEMONTH(SUM(Inventory[Qty]), 'Date'[Date])","SUM(Inventory[Qty])","TOTALMTD(SUM(Inventory[Qty]), 'Date'[Date])","AVERAGE(Inventory[Qty])"],"ans":0,"exp":"Stock is semi-additive: sum across stores, but take the last day for the month. CLOSINGBALANCEMONTH does this.","why":["","SUM adds every day's stock.","TOTALMTD accumulates across days.","An average isn't the closing stock."],"ar":"المخزون آخر الشهر = CLOSINGBALANCEMONTH.","ref":[{"t":"CLOSINGBALANCEMONTH function (DAX)","u":"https://learn.microsoft.com/en-us/dax/closingbalancemonth-function-dax"}]},{"id":"PCS2-03","d":"model","s":"perf","type":"multi","n":2,"diff":2,"tag":"Reduce data","q":"Which two changes reduce the model size the most without affecting any report? Each correct answer presents a complete solution. Select TWO.","opts":["Remove the TransactionID column and replace the DateTime column with a Date column","Filter the Product query to products that appear in Sales","Hide the TransactionID column","Turn on Auto date/time","Add a calculated column for the date"],"ans":[0,1],"exp":"High-cardinality unused columns and unused dimension rows take memory. Removing them in Power Query shrinks the model. Hiding columns, auto date tables and extra calculated columns don't help or make it bigger.","why":["Correct.","Correct.","Hidden columns are still stored.","Auto date/time adds hidden tables.","Calculated columns add data."],"ar":"احذف الأعمدة عالية التفرد غير المستخدمة وصفوف الأبعاد غير المستخدمة.","ref":[{"t":"Data reduction techniques for Import modeling","u":"https://learn.microsoft.com/en-us/power-bi/guidance/import-modeling-data-reduction"}]},{"id":"PCS2-04","d":"model","s":"perf","type":"single","diff":2,"tag":"Performance Analyzer","q":"You need to find out why the main page takes 15 seconds. What should you do first?","opts":["Run Performance Analyzer on the page and review each visual's DAX query and visual display times","Turn on automatic page refresh","Add more slicers","Change the theme"],"ans":0,"exp":"Performance Analyzer shows exactly which of the 28 visuals are slow and whether the time is DAX or rendering, which guides the fix.","why":["","That adds more queries.","More slicers add more queries.","Themes don't affect query time."],"ar":"ابدأ دائمًا بـ Performance Analyzer لمعرفة سبب البطء.","ref":[{"t":"Use Performance Analyzer to examine report element performance","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-performance-analyzer"}]},{"id":"PCS2-05","d":"viz","s":"usability","type":"single","diff":1,"tag":"Mobile","q":"What should you do for the store managers who use phones?","opts":["Create a mobile layout for the pages they use","Make the page size 360 by 640","Publish a copy of the report for phones","Remove all slicers"],"ans":0,"exp":"Mobile layouts show automatically in the Power BI mobile apps in portrait orientation, without changing the desktop layout.","why":["","That shrinks the desktop view too.","A copy doubles maintenance.","Slicers can be optimized for mobile rather than removed."],"ar":"لمستخدمي الهاتف: Mobile layout.","ref":[{"t":"Create mobile-optimized Power BI reports","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/power-bi-create-mobile-optimized-report-about"}]},{"id":"PCS2-06","d":"viz","s":"usability","type":"yesno","diff":2,"tag":"Accessibility","q":"You're improving accessibility for screen reader users.<br>For each of the following statements, select Yes if the statement is true. Otherwise, select No.","opts":["Alt text on visuals is read by screen readers.","Setting the tab order in the Selection pane helps keyboard navigation.","Using only color to show good and bad results is enough for accessibility."],"ans":[true,true,false],"exp":"Alt text gives a text description, tab order controls keyboard focus, and color alone excludes users with color vision deficiency.","why":["Yes.","Yes.","No. Add icons, labels or markers in addition to color."],"ar":"Alt text وترتيب Tab مهمان، واللون وحده لا يكفي.","ref":[{"t":"Design Power BI reports for accessibility","u":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-accessibility-overview"}]}]}]};
